// Help language lt for the mock (generated by make-bank.py; do not edit by hand).
window.HELP=window.HELP||{};window.HELP.lt={"high-risk-b1-01":{"question":"Dėl darbo turėtumėte stovėti ant sustatomųjų kopėčių (stepladder) apie 2 valandas nenulipdami. Ką siūlo HSE (darbo saugos tarnyba)?","options":["Naudoti kitą įrangą, pvz., mobilųjį bokštelį (tower scaffold) ar keliamąją platformą","Naudoti sustatomąsias kopėčias, bet kas valandą nulipti pertraukai","Naudoti sustatomąsias kopėčias, jei kas nors laiko jų apačią","Naudoti aukštesnes sustatomąsias kopėčias, kad nereikėtų tiestis"],"explanation":"HSE (darbo saugos tarnyba) nurodo: jei ant kopėčių ar sustatomųjų kopėčių (stepladder) būtumėte ilgiau nei 30 minučių iš eilės, reikia naudoti kitą įrangą. Nulipant kartą per valandą vis tiek ant kopėčių stovima po valandą iš eilės. Apačią laikantis žmogus ar aukštesnės kopėčios nepakeičia to, kiek laiko ten būnate.","why_not":{"1":"Net nulipdami kas valandą, ant kopėčių vis tiek stovite po valandą iš eilės, o HSE (darbo saugos tarnyba) nurodo 30 minučių ribą.","2":"Apačią laikantis žmogus nesutrumpina laiko, kurį praleidžiate viršuje; naudokite kitą įrangą.","3":"Ant aukštesnių sustatomųjų kopėčių (stepladder) vis tiek būsite 2 valandas; po 30 minučių HSE (darbo saugos tarnyba) siūlo naudoti kitą įrangą."}},"high-risk-b1-02":{"question":"Dirbate nuo atremiamų kopėčių (leaning ladder) ir reikia pasiekti šiek tiek toliau į šoną. Ką sako HSE (darbo saugos tarnyba)?","options":["Diržo sagtis turi likti tarp dviejų kopėčių šonų. Jei nepasiekiate, nulipkite ir perstatykite kopėčias","Pasilenkti, jei viena ranka laikotės kopėčių","Stumdyti kopėčias į šoną, kol stovite ant jų","Pasilenkti, jei kas nors laiko kopėčių apačią"],"explanation":"Pasilenkus kopėčios traukiamos į šoną, ir jos gali nuslysti ar apvirsti. Paprastas HSE (darbo saugos tarnybos) patikrinimas: diržo sagtis (arba bamba) turi likti tarp dviejų ilgųjų kopėčių šonų. Niekada nebandykite perstatyti kopėčių, kol ant jų stovite. Nulipkite, perstatykite jas ir tada vėl lipkite.","why_not":{"1":"Pasilenkus kopėčios gali nuslysti ar apvirsti, net jei laikotės; diržo sagtis turi likti tarp kopėčių šonų.","2":"HSE (darbo saugos tarnyba) sako niekada nestumdyti kopėčių, kol ant jų stovite; pirmiausia nulipkite.","3":"Kai kas nors laiko kopėčių apačią (footing), pasilenkti per toli vis tiek nesaugu; diržo sagtis turi likti tarp kopėčių šonų."}},"high-risk-b1-03":{"question":"Reikia pritvirtinti atremiamas kopėčias (leaning ladder), kad jos stovėtų saugiai. Kurį būdą reikia naudoti tik tada, jei nė vienas kitas neįmanomas?","options":["Pririšti abu kopėčių šonus prie tvirto taško","Uždėti kopėčių stabilumo įtaisą (ladder stability device)","Tvirtai įremti kopėčias, pvz., į sieną","Paprašyti bendradarbio laikyti kopėčias (footing – laikyti apačioje)"],"explanation":"HSE (darbo saugos tarnyba) nurodo eilę, kurios reikia laikytis. Pirmiausia pririškite kopėčias, abu šonus. Jei negalite, naudokite stabilumo įtaisą. Jei ir to negalite, tvirtai jas įremkite. Kai kas nors laiko kopėčių apačią (footing), tai paskutinė išeitis, tik kai nė vieno kito būdo negalima pritaikyti.","why_not":{"0":"Pririšti abu šonus – pirmas HSE (darbo saugos tarnybos) pasirinkimas, o ne paskutinis.","1":"Stabilumo įtaisas (stability device) – antras pasirinkimas, kai kopėčių negalima pririšti.","2":"Įremti kopėčias reikia anksčiau nei laikyti jų apačią; laikymas apačioje (footing) – paskutinė išeitis."}},"high-risk-b1-04":{"question":"Reikia nustumti mobilųjį bokštelį (mobile tower scaffold) prie kitos pastato dalies. Kas turi būti padaryta pirmiausia?","options":["Visi nulipa nuo jo, ir nuimami visi įrankiai ir medžiagos","Viršuje esantis žmogus tvirtai laikosi, kol bokštelis stumiamas","Nieko, jei jis stumiamas tik trumpą atstumą","Kas nors ant viršutinės aikštelės traukia jį iš viršaus"],"explanation":"HSE (darbo saugos tarnyba) sako niekada nestumti bokštelio, kai ant jo yra žmonių ar medžiagų. Viršuje esantis žmogus ar krovinys gali nukristi arba apversti bokštelį. Stumkite ar traukite jį tik už apačios ir tik ant tvirto, lygaus pagrindo, kai virš jo nieko nėra.","why_not":{"1":"Niekada nestumkite bokštelio, kai ant jo yra žmonių: jie gali nukristi arba bokštelis gali apvirsti.","2":"Net trumpą atstumą stumti nesaugu, kai ant bokštelio yra žmonių ar medžiagų.","3":"Bokštelį stumkite tik už apačios ir niekada, kai ant jo yra žmonių."}},"high-risk-b1-09":{"question":"Kodėl žmogus ant žemės turėtų mokėti naudotis mobiliosios keliamosios darbo platformos (MEWP) valdymu nuo žemės (ground controls)?","options":["Kad avarijos atveju galėtų nuleisti platformą ir išgelbėti operatorių","Kad galėtų pakelti platformą greičiau nei operatorius","Kad krepšyje esančiam operatoriui nereikėtų jokių mokymų","Kad galėtų važinėti MEWP po statybvietę, kol operatorius dirba"],"explanation":"Operatorius gali įstrigti krepšyje, pvz., prispaustas prie plieninių konstrukcijų viršuje, ir gali nebegalėti sustabdyti mašinos. HSE (darbo saugos tarnyba) sako turėti gelbėjimo planą ir jį išbandyti praktiškai, o žmogus ant žemės turi žinoti, ką daryti ir kaip naudotis valdymu nuo žemės (ground controls). Valdymas nuo žemės skirtas avarijoms, o ne tam, kad būtų galima praleisti operatoriaus mokymus.","why_not":{"1":"Valdymas nuo žemės (ground controls) skirtas gelbėti avarijos atveju, o ne greičiau pakelti platformą.","2":"Operatoriui vis tiek reikia mokymų; valdymas nuo žemės (ground controls) skirtas gelbėti avarijos atveju.","3":"Valdymas nuo žemės (ground controls) skirtas ne važinėti, o tam, kad avarijos atveju kas nors galėtų nuleisti platformą."}},"high-risk-b1-10":{"question":"Vakar jūsų smūgį sugeriantis saugos lynas (energy-absorbing lanyard) sulaikė jus nuo kritimo. Šiandien jis atrodo gerai. Kas su juo turi būti daroma?","options":["Visam laikui jo nebenaudoti: jo niekada nebegalima naudoti","Toliau naudoti, jei jis praeina jūsų patikrinimą prieš naudojimą","Naudoti dar vieną savaitę, tada gauti naują","Išskalbti, išdžiovinti ir vėl naudoti"],"explanation":"Net jei jis atrodo gerai, HSE (darbo saugos tarnyba) sako, kad kritimą sulaikęs saugos lynas (lanyard) niekada nebeturi būti naudojamas. Iš karto jo nebenaudokite, kad jį būtų galima sunaikinti arba grąžinti gamintojui. Patikrinimas prieš naudojimą (pre-use check) negali padaryti jo vėl saugaus.","why_not":{"1":"Patikrinimas prieš naudojimą (pre-use check) negali padaryti jo saugaus; kritimą sulaikęs saugos lynas (lanyard) niekada nebeturi būti naudojamas.","2":"Net ne savaitę; jo reikia iš karto nebenaudoti.","3":"Išskalbtas jis netaps saugus; kritimą sulaikęs saugos lynas (lanyard) niekada nebeturi būti naudojamas."}},"high-risk-b1-11":{"question":"Jus siunčia ant seno gamyklos stogo iš lakštų. Niekas jums nepasakė, ar jis trapus (fragile). Kaip turite į jį žiūrėti?","options":["Kaip į trapų, kol kompetentingas asmuo nepatvirtins, kad jis ne trapus","Kaip į saugų, jei darbas užtruks tik kelias minutes","Kaip į saugų, jei praėjusį kartą jis atlaikė žmogaus svorį","Kaip į saugų, jei lipate tik ten, kur matote varžtus"],"explanation":"HSE (darbo saugos tarnyba) sako, kad kiekvienas stogas turi būti laikomas trapiu (fragile), kol kompetentingas asmuo (competent person) nepatvirtins, kad jis ne trapus. Pro trapius stogus ir stoglangius nukrenta ir žūsta daug darbuotojų, o trumpi darbai nėra saugesni: atsargumo priemonių reikia, kad ir koks trumpas būtų darbas. Lakštas, kuris kartą atlaikė, kitą kartą vis tiek gali lūžti.","why_not":{"1":"Trumpi darbai nėra saugesni; kiekvieną stogą laikykite trapiu (fragile), kol kompetentingas asmuo (competent person) nepatvirtins kitaip.","2":"Lakštas, kuris kartą atlaikė, vis tiek gali lūžti; laikykite stogą trapiu (fragile), kol jis nepatikrintas.","3":"Matomi varžtai neįrodo, kad stogas tvirtas; laikykite jį trapiu (fragile), kol kompetentingas asmuo (competent person) nepatikrins."}},"high-risk-b1-12":{"question":"Tranšėja su atramomis buvo patikrinta penktadienį po pietų. Dabar pirmadienio rytas, ir ruošiatės į ją lipti. Kas turi būti padaryta pirmiausia?","options":["Kompetentingas asmuo turi ją patikrinti šios pamainos pradžioje","Nieko: ji patikrinta penktadienį, todėl viskas gerai","Pirmas įlipęs žmogus ją patikrina dirbdamas","Nieko: ją reikia tikrinti tik kartą per savaitę"],"explanation":"Įstatymas sako, kad niekas negali dirbti sutvirtintoje iškasoje, nebent kompetentingas asmuo (competent person) ją patikrino tos pamainos pradžioje ir yra įsitikinęs, kad ji saugi. Tarp pamainų gali daug kas pasikeisti. Penktadienio patikrinimas pirmadienio pamainai negalioja.","why_not":{"1":"Penktadienio patikrinimas pirmadieniui negalioja; tranšėją reikia patikrinti kiekvienos pamainos pradžioje.","2":"Kompetentingas asmuo (competent person) turi ją patikrinti prieš kam nors įlipant, o ne kas nors dirbdamas.","3":"Kartą per savaitę – per retai; sutvirtinta tranšėja tikrinama kiekvienos pamainos pradžioje."}},"high-risk-b1-15":{"question":"Kasate tranšėją prie senos sodo sienos. Apie kokį pavojų įspėja HSE (darbo saugos tarnyba)?","options":["Tranšėja gali pakasti negilius sienos pamatus, ir siena gali užgriūti ant jūsų","Pavojaus nėra, jei ekskavatorius neliečia sienos","Jokio: siena padeda laikyti tranšėjos sieną, todėl taip saugiau","Vienintelė rizika – bauda už sienos sugadinimą"],"explanation":"Daugelio sodo ir ribų sienų pamatai labai negilūs. Net nedidelė tranšėja šalia gali juos pakasti, ir siena gali užgriūti ant tranšėjoje esančių žmonių. Prieš kasdami nuspręskite, ar sienai reikia papildomų atramų.","why_not":{"1":"Ekskavatoriui nebūtina liesti sienos; tranšėja gali pakasti negilius pamatus, ir siena gali nugriūti.","2":"Siena nepadeda; jos negilius pamatus galima pakasti, ir ji gali užgriūti ant jūsų.","3":"Tikrasis pavojus – kad siena užgrius ant tranšėjoje esančių žmonių, o ne bauda."}},"high-risk-b1-16":{"question":"Reikia patikrinti, ar nepažeistas kanalizacijos vamzdis. Kokį klausimą reikia užduoti pirmiausia, prieš kam nors planuojant lįsti į vidų?","options":["Ar darbą galima atlikti iš lauko, pvz., nuotoline kamera?","Koks mažiausias žmogus pralįs pro angą?","Ar visi turi dulkių kaukes?","Ar galima tai padaryti taip greitai, kad būtų galima praleisti saugos patikrinimus?"],"explanation":"Pirmoji pareiga, kai kalbama apie uždaras erdves (confined spaces), – visai į jas nelįsti, jei darbą galima atlikti kitaip. Patikrinimus viduje dažnai galima atlikti iš lauko, pvz., nuotoline kamera. Tik jei įlįsti neišvengiama, pereinate prie saugios darbo sistemos (safe system of work) ir gelbėjimo planų.","why_not":{"1":"Pirmiausia paklauskite, ar į vidų apskritai reikia kam nors lįsti; darbą gali būti įmanoma atlikti iš lauko.","2":"Kaukės – vėliau, jei jų išvis reikės; pirmas klausimas – ar galima išvengti lindimo į vidų.","3":"Niekada nepraleiskite saugos patikrinimų; pirmiausia paklauskite, ar darbą galima atlikti iš lauko."}},"high-risk-b1-17":{"question":"Jūsų brigada nori naudoti benzininį siurblį požeminėje kameroje vandeniui išsiurbti. Ką sako HSE (darbo saugos tarnyba)?","options":["Niekada neleisti: išmetamosiose dujose yra mirtinai nuodingo anglies monoksido (carbon monoxide)","Galima, jei dangtis paliekamas atidarytas","Galima trumpiems darbams, trumpesniems nei 15 minučių","Galima, jei vienas žmogus lieka viršuje"],"explanation":"Benzininio variklio išmetamosiose dujose yra anglies monoksido (smalkių) – nuodingų dujų, o uždaroje erdvėje (confined space) dūmai kaupiasi. HSE sako, kad tai taip pavojinga, jog įrangos su benzininiais varikliais į uždaras erdves niekada negalima leisti. Atidarytas dangtis, trumpas darbas ar žmogus viršuje to nepadaro saugaus.","why_not":{"1":"Atidarytas dangtis nepadaro to saugaus; benzininių variklių anglies monoksidas (carbon monoxide) kaupiasi po žeme.","2":"Anglies monoksidas (carbon monoxide) per daug pavojingas; HSE (darbo saugos tarnyba) sako niekada neleisti benzininių variklių uždarose erdvėse (confined spaces), net trumpam.","3":"Žmogus viršuje negali sustabdyti dūmų kaupimosi; to niekada negalima leisti."}},"high-risk-b1-18":{"question":"Kada turi būti paruoštas žmogaus gelbėjimo iš uždaros erdvės (confined space) planas?","options":["Prieš kam nors įlendant dirbti","Kai tik kas nors viduje patenka į bėdą","Tik jei darbas užtruks ilgiau nei valandą","Iki pirmos darbo dienos pabaigos"],"explanation":"Įstatymas sako, kad niekas negali įlįsti į uždarą erdvę (confined space) dirbti, jei tinkamos gelbėjimo priemonės jau nėra paruoštos. Avarijos metu nėra laiko kurti plano.","why_not":{"1":"Avarijos metu nėra laiko kurti plano; jis turi būti paruoštas prieš kam nors įlendant.","2":"Gelbėjimo plano reikia kiekvieną kartą lendant į uždarą erdvę (confined space), kad ir kiek truktų darbas.","3":"Planas turi būti paruoštas prieš kam nors įlendant, o ne dienos pabaigoje."}},"high-risk-b1-20":{"question":"Ant statybvietės keltuvo (hoist) yra ženklas, kad jis skirtas tik kroviniams (goods only). Jums reikia nusigauti į trečią aukštą. Ar galite juo važiuoti?","options":["Ne: niekada nevažiuokite keltuvu, skirtu tik kroviniams","Taip, jei stovite prie medžiagų, kad jos nejudėtų","Taip, jei keltuvo operatorius sako, kad galima","Taip, jei tvirtai laikotės už šono"],"explanation":"Keltuvas, skirtas tik kroviniams (goods-only hoist), nėra pagamintas ar pažymėtas žmonėms vežti. HSE (darbo saugos tarnyba) sako, kad keleiviai niekada negali juo važiuoti. Eikite laiptais arba naudokite keltuvą, pažymėtą kaip skirtą keleiviams.","why_not":{"1":"Stovėjimas prie krovinio nepadaro to saugaus; keltuvu, skirtu tik kroviniams (goods-only hoist), keleiviai niekada negali važiuoti.","2":"Niekas negali to leisti; HSE (darbo saugos tarnyba) sako niekada neleisti keleiviams važiuoti keltuvu, skirtu tik kroviniams (goods-only hoist).","3":"Laikymasis nepadeda; keltuvas, skirtas tik kroviniams (goods-only hoist), nepagamintas žmonėms vežti."}},"high-risk-b1-21":{"question":"Pasiimate grandininį stropą (chain sling) kėlimui. Ant jo nėra žymės, rodančios leistiną darbo apkrovą (safe working load). Ką turėtumėte daryti?","options":["Jo nenaudoti: padėti į šalį ir pasakyti darbų vadovui (supervisor)","Naudoti, jei jis atrodo pakankamai tvirtas","Naudoti, bet tik lengviems kroviniams","Spėti leistiną darbo apkrovą pagal jo dydį ir ją užrašyti"],"explanation":"HSE (darbo saugos tarnyba) sako naudoti tik sertifikuotą kėlimo įrangą, kuri pažymėta leistina darbo apkrova (safe working load) ir kurios patikrinimo terminas nepasibaigęs. Be žymės niekas nežino, kiek ji gali saugiai pakelti. Spėti pagal dydį nesaugu. Jo nenaudokite ir praneškite.","why_not":{"1":"Neužtenka, kad atrodo tvirtas; be leistinos darbo apkrovos (safe working load) žymės niekas nežino, kiek jis gali pakelti.","2":"Net lengvi kroviniai – rizika; naudokite tik įrangą, pažymėtą leistina darbo apkrova (safe working load).","3":"Spėti pagal dydį nesaugu; naudoti galima tik sertifikuotą, pažymėtą įrangą."}},"high-risk-b1-25":{"question":"Bus išimama siena, kuri gali laikyti dalį pastato. Kas turėtų nuspręsti, ar reikia laikinų atramų (props)?","options":["Tinkamos kvalifikacijos ir patirties inžinierius","Darbą atliekantis darbuotojas, pažiūrėjęs į ją","Niekas: atramų reikia tik tada, kai atsiranda įtrūkimų","Užsakovas, nes pastatas jo"],"explanation":"Išėmus sieną, dalis pastato gali sugriūti be įspėjimo. HSE (darbo saugos tarnyba) sako, kad tinkamos kvalifikacijos ir patirties inžinierius turi nuspręsti, ar reikia laikinų atramų (props). Laukti įtrūkimų – per vėlu, o spėti iš akies – nepakankamai gerai.","why_not":{"1":"Pažiūrėti neužtenka; turi nuspręsti tinkamos kvalifikacijos ir patirties inžinierius.","2":"Laukti įtrūkimų – per vėlu; pastatas gali sugriūti be įspėjimo.","3":"Tai, kad pastatas užsakovo, nedaro jo inžinieriumi; turi nuspręsti tinkamos kvalifikacijos inžinierius."}},"high-risk-b2-01":{"question":"Dirbate ant sustatomųjų kopėčių (stepladder), kurių viršuje nėra už ko laikytis. Ant kurių pakopų neturėtumėte stovėti ir dirbti?","options":["Tik ant pačios viršutinės pakopos","Ant trijų viršutinių pakopų, įskaitant pačią viršutinę","Tik ant dviejų apatinių pakopų","Ant nė vienos, jei tik bendradarbis laiko kopėčias"],"explanation":"HSE (darbo saugos tarnyba) sako nestovėti ir nedirbti ant trijų viršutinių sustatomųjų kopėčių (stepladder) pakopų, įskaitant pakopą, kuri yra pati viršutinė, nebent yra tinkama vieta įsikibti ranka. Tai ne tik pati viršutinė pakopa. Bendradarbis, laikantis kopėčias, neduoda jums už ko įsikibti.","why_not":{"0":"Ne tik pati viršutinė pakopa; nedirbkite ant trijų viršutinių pakopų, jei nėra už ko įsikibti.","2":"Apatinės pakopos nėra problema; problema – trys viršutinės pakopos, kai nėra už ko įsikibti.","3":"Bendradarbis, laikantis kopėčias, neduoda jums už ko įsikibti; nelipkite ant trijų viršutinių pakopų."}},"high-risk-b2-02":{"question":"Atremiamomis kopėčiomis (leaning ladder) lipama ant pastolių platformos. Kiek kopėčios turi kyšoti virš platformos, ant kurios nulipate?","options":["Jos turi baigtis platformos lygyje, kad galėtumėte tiesiai nulipti","Maždaug 30 centimetrų","Bent 1 metrą","Nesvarbu, jei tik kopėčios pririštos"],"explanation":"HSE (darbo saugos tarnyba) sako, kad kopėčios, kuriomis lipama į kitą lygį, turi būti pririštos ir kyšoti bent 1 metrą virš vietos, kur nulipate. Taip turite už ko saugiai laikytis, kai užlipate ir nulipate. Pririšti irgi reikia, bet tai neatstoja papildomo aukščio.","why_not":{"0":"Jei kopėčios baigiasi platformos lygyje, nėra už ko laikytis; jos turi kyšoti bent 1 metrą.","1":"30 centimetrų – per mažai; HSE (darbo saugos tarnyba) sako bent 1 metrą virš vietos, kur nulipate.","3":"Pririšti irgi reikia, bet kopėčios vis tiek turi kyšoti bent 1 metrą."}},"high-risk-b2-03":{"question":"Statote mobilųjį bokštelį (mobile tower scaffold). Vienas kampas yra žemesnėje vietoje, todėl bendradarbis nori pakišti po tuo ratuku statybinių blokelių. Ką sako HSE (darbo saugos tarnyba)?","options":["Niekada nenaudokite plytų ar blokelių bet kokios bokštelio dalies svoriui laikyti","Galima, jei blokeliai yra vientisi betoniniai","Galima, jei bokštelis nėra labai aukštas","Galima, jei niekas nestovi tame kampe"],"explanation":"HSE (darbo saugos tarnyba) sako, kad bokštelis turi stovėti ant tvirto, lygaus pagrindo, o jo užfiksuoti ratukai ar atraminės plokštės turi būti tinkamai paremti. Plytos ar statybiniai blokeliai niekada negali laikyti jokios bokštelio dalies svorio, kad ir iš ko jie būtų pagaminti ir kad ir koks aukštas būtų bokštelis.","why_not":{"1":"Net vientisi betoniniai blokeliai niekada negali laikyti jokios bokštelio dalies svorio.","2":"Aukštis nieko nekeičia; plytos ar blokeliai niekada negali laikyti bokštelio.","3":"Blokeliai niekada negali laikyti bokštelio svorio, nesvarbu, ar kas nors ten stovi."}},"high-risk-b2-04":{"question":"Darbų vadovas (supervisor) prašo jūsų pririšti plastikinę plėvelę prie pastolių išorės, kad dulkės liktų viduje. Niekas nepasakė pastolių įmonei. Kas turėtų būti padaryta pirmiausia?","options":["Nieko: plėvelė lengva, todėl pastoliams tai nieko nekeičia","Reikia pasakyti žmonėms, kurie suprojektavo ir pastatė pastolius, kad jie užtikrintų, jog pastoliai suprojektuoti atlaikyti plėvelę","Pririšti ją tik prie viršutinio pastolių aukšto (top lift), o pastolių įmonei pasakyti vėliau","Paklausti užsakovo, nes tai jo pastatas"],"explanation":"HSE (darbo saugos tarnyba) sako niekada nedėti plėvelės ar apsauginio tinklo nuo nuolaužų ant pastolių, prieš tai nepasakius žmonėms, kurie juos suprojektavo ir pastatė. Jie turi užtikrinti, kad pastoliai tam suprojektuoti. Pasakyti vėliau – per vėlu, o užsakovas nėra tas, kuris gali tai nuspręsti.","why_not":{"0":"Plėvelė gaudo vėją ir padidina apkrovą, todėl pastoliai turi būti tam suprojektuoti.","2":"Jiems reikia pasakyti prieš uždengiant bet kurią dalį; vėliau – per vėlu.","3":"Užsakovas negali to nuspręsti; reikia pasakyti pastolių projektuotojams ir montuotojams."}},"high-risk-b2-07":{"question":"Dirbate ant pastolių stogo lygyje. Vėjas sustiprėjo ir pučia gūsiais, laisvi lakštai pradeda kilti. Ką sako įstatymas?","options":["Dirbti toliau, bet greičiau, kad baigtumėte, kol oras nepablogėjo","Dirbti toliau, jei tik prisisegate saugos diržais (harness)","Dirbti toliau, nes pastoliai pritvirtinti prie pastato","Darbas aukštyje gali vykti tik tada, kai oras nekelia pavojaus žmonių saugai, todėl sustokite ir saugiai nulipkite"],"explanation":"Darbo aukštyje taisyklės (Work at Height Regulations) sako, kad darbas aukštyje gali būti atliekamas tik tada, kai oras nekelia pavojaus jį dirbančių žmonių sveikatai ar saugai. Greitesnis darbas, saugos diržai (harness) ar tai, kad pastoliai pritvirtinti, stiprių gūsių nepadaro saugiais.","why_not":{"0":"Dirbant greičiau, stiprūs gūsiai netampa saugūs; sustokite ir nulipkite.","1":"Saugos diržai (harness) nepadaro blogo oro saugaus; darbą aukštyje reikia nutraukti.","2":"Inkarai laiko pastolius, o ne jus; esant pavojingam orui, darbą aukštyje reikia nutraukti."}},"high-risk-b2-11":{"question":"Kiek, priklausomai nuo grunto, gali sverti vienas kubinis metras grunto? (Tai grunto luitas, kurio ilgis 1 metras, plotis 1 metras ir gylis 1 metras.)","options":["Apie 50 kilogramų","Apie 200 kilogramų","Daugiau nei 1,5 tonos (1 500 kilogramų)","Apie 500 kilogramų"],"explanation":"HSE (darbo saugos tarnyba) sako, kad, priklausomai nuo sąlygų, vienas kubinis metras grunto gali sverti daugiau nei 1,5 tonos. Todėl net nedidelis tranšėjos sienos nuošliaužis gali prispausti ar užpilti joje dirbantį žmogų.","why_not":{"0":"Gerokai per mažai; kubinis metras grunto gali sverti daugiau nei 1,5 tonos.","1":"Gerokai per mažai; HSE (darbo saugos tarnyba) sako, kad jis gali sverti daugiau nei 1,5 tonos.","3":"Vis tiek per mažai; HSE (darbo saugos tarnyba) sako, kad jis gali sverti daugiau nei 1,5 tonos."}},"high-risk-b2-12":{"question":"Esate tranšėjoje, kur atkasti vamzdis ir keli kabeliai. Kopėčios yra tolimajame gale. Ar galite atkastą vamzdį naudoti kaip laiptelį išlipti?","options":["Ne: atkastomis komunikacijomis niekada negalima laikytis ar ant jų stovėti išlipant","Taip, jei tai metalinis vamzdis","Taip, jei ant jo atsistojate atsargiai","Taip, jei vamzdis paremtas iš apačios"],"explanation":"HSE (darbo saugos tarnyba) sako, kad atkastas komunikacijas gali tekti paremti, ir jų niekada negalima naudoti kaip vietos įsikibti rankomis ar atsistoti kojomis išlipant iš kasinio. Naudokitės kopėčiomis ar kitu tinkamu būdu išlipti.","why_not":{"1":"Metalinės ar ne, atkastos komunikacijos niekada negali būti naudojamos kaip laiptelis.","2":"Atsargiai atsistojus, vis tiek ant jų stovima; niekada nesilaikykite už komunikacijų ir nestovėkite ant jų.","3":"Net paremtos komunikacijos niekada negali būti naudojamos išlipti; naudokitės kopėčiomis."}},"high-risk-b2-13":{"question":"Kasdami rankomis atkasate vamzdį ar kabelį, padengtą juodu plastiku. Kol kas niekas nežino, kas tai. Kaip turėtumėte į jį žiūrėti?","options":["Kaip į seną vandens vamzdį, kurį saugu perpjauti","Kaip į atjungtą kabelį, nes jo nėra brėžiniuose","Kaip į telefono kabelį, kuris negali sužeisti","Kaip į elektros kabelį, kuriame yra įtampa"],"explanation":"HSE (darbo saugos tarnyba) sako, kad juodu plastiku gali būti padengti ir vandens vamzdžiai, ir elektros kabeliai, ir telefono kabeliai. Kol tikrai nežinote, kas tai, į bet kokią juodo plastiko komunikaciją žiūrėkite kaip į elektros kabelį su įtampa. HSE taip pat sako visas komunikacijas laikyti esančiomis su įtampa, kol jos neatjungtos ir nepatikrinta, kad jos saugios ten, kur dirbate.","why_not":{"0":"Juodu plastiku gali būti padengti ir elektros kabeliai; žiūrėkite į jį kaip į kabelį su įtampa.","1":"Tai, kad jo nėra brėžiniuose, nereiškia, kad jis be įtampos; visas komunikacijas laikykite esančiomis su įtampa.","2":"Tai gali būti elektros kabelis; į bet kokią juodo plastiko komunikaciją žiūrėkite kaip į esančią su įtampa."}},"high-risk-b2-15":{"question":"Bendradarbis nori pasilenkti ir įkišti tik galvą į kameros angą greitai apsižiūrėti. Oras viduje nepatikrintas. Kodėl tai pavojinga?","options":["Deguonies trūkumas gali paveikti labai greitai, dažnai be jokio įspėjimo, net jei viduje tik galva","Tai nepavojinga, jei kojos lieka lauke","Tai pavojinga tik tada, jei užuodžiate kažką blogo","Tai pavojinga tik tada, jei ten išbūnate ilgiau nei 10 minučių"],"explanation":"HSE (darbo saugos tarnyba) sako, kad net nedidelis deguonies sumažėjimas gali paveikti, kaip gerai mąstote. Poveikis labai greitas, ir pojūčiai paprastai jokio įspėjimo neduoda. Taip gali nutikti net tada, kai uždaroje erdvėje (confined space) yra tik žmogaus galva, o labai mažas deguonies kiekis gali sukelti sąmonės netekimą ir mirtį.","why_not":{"1":"Deguonies trūkumas gali jus paveikti, net kai viduje tik galva.","2":"Pojūčiai paprastai jokio įspėjimo neduoda, todėl galite nieko neužuosti.","3":"Poveikis labai greitas, todėl net trumpas apsižiūrėjimas gali jums pakenkti."}},"high-risk-b2-16":{"question":"Jums reikia naudoti elektrinius įrankius ir šviestuvus metalinio rezervuaro viduje. Kokią įrangą, pasak HSE (darbo saugos tarnybos), reikia naudoti, kad būtų išvengta elektros smūgio?","options":["Įprastus elektros tinklo (230 voltų) įrankius, jei tik jie atrodo geros būklės","Bet kokius įrankius, jei mūvite gumines pirštines","Labai žemos įtampos įrangą (paprastai žemiau 25 voltų), o kur reikia – su srovės nuotėkio jungikliu (RCD)","Bet kokius įrankius, jei stovite ant sauso medžio gabalo"],"explanation":"HSE (darbo saugos tarnyba) sako, kad kai kuriose uždarose erdvėse (confined spaces), pvz., metalinių rezervuarų viduje, apsauga nuo elektros smūgio apima labai žemos įtampos įrangos, paprastai žemiau 25 voltų, naudojimą ir, kur reikia, srovės nuotėkio jungiklius (RCD). Pirštinės, medžio gabalas ar gerai atrodantys įrankiai nėra HSE nurodytos atsargumo priemonės.","why_not":{"0":"Neužtenka, kad atrodo geros būklės; HSE (darbo saugos tarnyba) sako metalinių rezervuarų viduje naudoti labai žemos įtampos įrangą.","1":"Pirštinės nėra HSE (darbo saugos tarnybos) nurodyta priemonė; naudokite labai žemos įtampos įrankius, o kur reikia – su srovės nuotėkio jungikliu (RCD).","3":"Stovėti ant medžio nėra HSE (darbo saugos tarnybos) nurodyta atsargumo priemonė; naudokite labai žemos įtampos įrangą."}},"high-risk-b2-17":{"question":"Prieš jūsų komandai lendant į uždarą erdvę (confined space), darbų vadovas išduoda darbų leidimą (permit to work). Kam jis skirtas?","options":["Jis leidžia praleisti oro patikrinimą, jei darbas trumpas","Tai oficialus patikrinimas, kad visos saugaus darbo būdo dalys yra įgyvendintos, prieš kam nors įeinant","Tai tik įrašas, kas tą dieną buvo statybvietėje","Jis reiškia, kad vienas žmogus gali įeiti vienas, be nieko lauke"],"explanation":"HSE (darbo saugos tarnyba) sako, kad darbų leidimas (permit to work) užtikrina, jog atliekamas oficialus patikrinimas, kad visos saugios darbo sistemos (safe system of work) dalys būtų įgyvendintos, prieš žmonėms įeinant ar dirbant uždaroje erdvėje. Tai taip pat būdas vadovams, darbų vadovams ir darbą atliekantiems žmonėms keistis informacija. Jis neatstoja jokių saugos priemonių.","why_not":{"0":"Darbų leidimas (permit to work) niekada neleidžia praleisti oro patikrinimo ar bet kokio kito saugos veiksmo.","2":"Tai daugiau nei vardų sąrašas; jis patikrina, ar įgyvendinta visa saugi darbo sistema (safe system of work).","3":"Darbų leidimas (permit to work) neatstoja saugos priemonių, pvz., žmogaus, kuris stebi lauke."}},"high-risk-b2-18":{"question":"Didelis plieninis rezervuaras ilgai buvo uždarytas, ir viduje susidarė rūdžių. Kodėl oras viduje gali būti pavojingas?","options":["Kai susidaro rūdys, jos gali sunaudoti deguonį, todėl kvėpuoti jo gali neužtekti","Rūdys skleidžia stiprų kvapą, kuris jus įspės, todėl tai nepavojinga","Rūdys kenkia tik metalui, todėl oras tinkamas","Dėl rūdžių oras tampa per drėgnas, kad pro jį matytųsi"],"explanation":"HSE (darbo saugos tarnyba) sako, kad plieniniuose rezervuaruose ir induose gali pritrūkti deguonies, kai susidaro rūdys. Rūdys neįspėja kvapu. Tai viena iš priežasčių, kodėl orą uždaroje erdvėje (confined space) gali tekti patikrinti – tai daro kompetentingas asmuo (competent person) su dujų detektoriumi, prieš kam nors įeinant.","why_not":{"1":"Negalima pasikliauti kvapu; susidarančios rūdys gali sunaudoti rezervuare esantį deguonį.","2":"Susidarančios rūdys gali sunaudoti ore esantį deguonį, todėl oras gali būti netinkamas.","3":"Pavojus – ne drėgmė; susidarius rūdims, kvėpuoti gali likti per mažai deguonies."}},"high-risk-b2-19":{"question":"Naudojate kėlimo skridinį (gin wheel – paprastas skridinys su virve) kibirams užkelti ant pastolių. Tinkamo kablio nėra, todėl bendradarbis sulenkia armatūros strypą į kablį. Ar galite jį naudoti?","options":["Ne: naudokite tinkamą kablį, pagamintą taip, kad krovinys nenukristų, arba kablį su apsaugine sklende","Taip, jei strypas pakankamai storas","Taip, bet tik lengviems kibirams","Taip, jei kablio galą apvyniojate juosta"],"explanation":"HSE (darbo saugos tarnyba) sako, kad kėlimo skridiniui (gin wheel) reikia tinkamo kablio, suprojektuoto taip, kad krovinys nenukristų, arba kablio su apsaugine sklende, kuri padeda išlaikyti krovinį, jei jis už ko nors užkliūna. Nenaudokite sulenktų armatūros strypų ar kitų savadarbių kablių, kad ir koks būtų krovinys.","why_not":{"1":"Storis nesvarbus; niekada nenaudokite sulenktų strypų ar kitų savadarbių kablių.","2":"Net lengvas krovinys gali nukristi nuo savadarbio kablio; naudokite tinkamą kablį.","3":"Juosta nepadaro jo saugaus; naudokite tinkamą kablį arba kablį su apsaugine sklende."}},"high-risk-b2-20":{"question":"Netrukus bus keliamas krovinys, kurio svoris pasiskirstęs netolygiai. Jo svorio centras jau surastas. Ką HSE (darbo saugos tarnyba) sako daryti toliau?","options":["Greitai pakelti jį iki galo, kad greičiau baigtumėte","Paprašyti, kad kas nors atsistotų ant lengvesnio galo jam atsverti","Kelti jį ir prilaikyti iš apačios rankomis","Pakelti jį keliais coliais (a few inches) nuo žemės ir stabtelėti"],"explanation":"HSE (darbo saugos tarnyba) sako, kad prieš keliant nesubalansuotą krovinį reikia surasti jo svorio centrą, tada pakelti jį keliais coliais (a few inches) nuo žemės ir stabtelėti. Jei jis paslysta ar pakrypsta, nukritęs iš tokio aukščio jis padaro mažai žalos.","why_not":{"0":"Greitai pakėlus iki galo, krovinys paslydęs gali nukristi iš didelio aukščio; pirmiausia stabtelėkite.","1":"Taip žmogus atsidurtų ant judančio krovinio; HSE (darbo saugos tarnyba) sako pakelti jį keliais coliais (a few inches) ir stabtelėti.","2":"Jei krovinys nukristų, po juo esančias rankas galėtų prispausti; pakelkite jį truputį ir stabtelėkite."}},"high-risk-b2-22":{"question":"Statybvietės krovininis keltuvas (goods hoist) kiekviename aukšte turi vartelius. Kada šie aukštų varteliai turi būti atidaryti?","options":["Visą dieną, kad būtų greičiau krauti","Tik kol keltuvas tame aukšte kraunamas ar iškraunamas","Kai keltuvo platforma yra žemės lygyje","Kai kas nors tame aukšte laukia keltuvo"],"explanation":"HSE (darbo saugos tarnyba) sako, kad žmonės neįkristų į keltuvo šachtą, aukštų varteliai turi būti uždaryti, išskyrus pakrovimo ir iškrovimo metu. Varteliai taip pat turi būti tvirti ir negali atsidaryti į keltuvo šachtą.","why_not":{"0":"Jei varteliai visą dieną atidaryti, žmonės gali įkristi į keltuvo šachtą.","2":"Varteliai lieka uždaryti, išskyrus tada, kai tame aukšte kraunama ar iškraunama.","3":"Laukti – ne krauti; laikykite vartelius uždarytus, kad niekas neįkristų į keltuvo šachtą."}},"high-risk-b2-23":{"question":"Per vidaus išardymo darbus (strip-out) statybinės atliekos kraunamos viršutiniame aukšte, kol bus išvežtos. Kodėl tai reikia kontroliuoti?","options":["Nereikia: grindys pastatytos atlaikyti bet kokį svorį","Tik todėl, kad atrodo netvarkingai","Susikaupusios nuolaužos padidina apkrovą, o konstrukcijos niekada negalima perkrauti, nes grindys gali sugriūti","Tik todėl, kad atliekos gali sušlapti"],"explanation":"HSE (darbo saugos tarnyba) sako, kad konstrukcijų niekada negalima perkrauti. Griovimo metu susikaupusios nuolaužos padidina grindų apkrovą, o tokią papildomą apkrovą laikančiai konstrukcijai gali prireikti laikinų sutvirtinimų ar atramų (props). Grindys nepastatytos atlaikyti bet kokį svorį.","why_not":{"0":"Grindys nepastatytos atlaikyti bet kokį svorį; sukrautos nuolaužos padidina apkrovą ir gali jas perkrauti.","1":"Tvarka – ne pagrindinė priežastis; papildomas svoris gali perkrauti grindis.","3":"Šlapios ar sausos, susikaupusios nuolaužos padidina grindų apkrovą."}},"high-risk-b2-24":{"question":"Laikinų atramų (props) eilė laiko perdangą, kol po ja išimama siena. Bendradarbis nori pririšti prie vienos atramos skridinį medžiagoms kelti. Ką sako įstatymas?","options":["Laikina atrama gali būti naudojama tik tam darbui, kuriam ji suprojektuota ir pastatyta","Galima, jei medžiagos lengvos","Galima, jei vietoj vienos atramos naudojamos dvi","Galima, jei atramos buvo patikrintos šį rytą"],"explanation":"Statybos (projektavimo ir valdymo) taisyklės (CDM Regulations 2015) sako, kad bet kokia laikina atrama turi būti suprojektuota ir prižiūrima taip, kad atlaikytų galimas apkrovas, ir gali būti naudojama tik tam tikslui, kuriam ji suprojektuota ir pastatyta. Pakabinus skridinį ant atramos, atsiranda apkrovų, kurioms ji nesuprojektuota, net su lengvomis medžiagomis.","why_not":{"1":"Net lengvi kroviniai – netinkama; laikina atrama gali atlikti tik tą darbą, kuriam ji suprojektuota.","2":"Dvi atramos (props) vis tiek gautų apkrovas, kurioms jos nesuprojektuotos.","3":"Rytinis patikrinimas nekeičia to, kam atrama (prop) suprojektuota."}},"high-risk-b3-01":{"question":"Jūsų kopėčios šiek tiek per trumpos, kad pasiektumėte lataką. Bendradarbis siūlo kopėčių kojeles (feet) pastatyti ant apačioje stovinčio furgono stogo. Ką turėtumėte daryti?","options":["Taip ir padaryti, jei furgono rankinis stabdys įjungtas","Vietoj to pastatyti kopėčias ant padėklo, nes jis žemesnis","Taip ir padaryti, jei kas nors sėdės furgone, kad jis nejudėtų","Gauti ilgesnes kopėčias ar kitą įrangą: niekada nestatykite kopėčių ant to, kas gali pajudėti, pvz., ant furgono"],"explanation":"HSE (darbo saugos tarnyba) sako nestatyti kopėčių ant to, kas gali pajudėti, ir mini furgonus bei padėklus. Rankinis stabdys ar furgone sėdintis žmogus nepaverčia furgono stogo saugiu, tvirtu pagrindu. Gaukite pakankamai ilgas kopėčias arba naudokite kitą įrangą.","why_not":{"0":"Rankinis stabdys nepaverčia furgono saugiu pagrindu; niekada nestatykite kopėčių ant furgono.","1":"HSE (darbo saugos tarnyba) mini ir padėklus; niekada nestatykite kopėčių ant to, kas gali pajudėti.","2":"Furgone sėdintis žmogus nepadaro jo tvirto; niekada nestatykite kopėčių ant furgono."}},"high-risk-b3-02":{"question":"Elektrikui reikia kopėčių, kad pasiektų šviestuvą, prie kurio dirba. Kokias kopėčias jis turėtų naudoti?","options":["Metalines kopėčias, jei jų kojelės stovi ant sauso grindų paviršiaus","Stiklo pluošto (fibreglass) ar medines kopėčias, nes jos nepraleidžia elektros","Aliuminines kopėčias, nes jas lengviausia nešti","Bet kokias kopėčias, jei jis avi batus guminiais padais"],"explanation":"HSE (darbo saugos tarnyba) sako bet kokiam elektros darbui naudoti kopėčias, kurios nepraleidžia elektros, pvz., stiklo pluošto (fibreglass) ar medines. Metalinės kopėčios, pvz., aliumininės, praleidžia elektrą. Batai ar sausos grindys nepakeičia to, iš ko pagamintos kopėčios.","why_not":{"0":"Metalinės kopėčios praleidžia elektrą; sausos grindys to nekeičia.","2":"Aliuminis praleidžia elektrą; elektros darbams naudokite stiklo pluošto (fibreglass) ar medines kopėčias.","3":"Batai nekeičia to, iš ko pagamintos kopėčios; naudokite elektros nepraleidžiančias kopėčias."}},"high-risk-b3-05":{"question":"Stovite ant sustatomųjų kopėčių (stepladder) ir tvirtinate dūmų detektorių prie lubų. Trumpam jums reikia abiejų rankų. Kaip vis tiek išlaikyti „tris atramos taškus“ (three points of contact)?","options":["Viena koja ant kopėčių, o abi rankos prie detektoriaus","Negalite: turite laikyti viena ranka kopėčias, todėl šio darbo daryti negalima","Abi kojos ant kopėčių, o kūnas (keliai ar krūtinė) atremtas į kopėčias","Stovėti ant vienos kojos, o kita koja apsikabinti kopėčias"],"explanation":"HSE (darbo saugos tarnyba) sako, kad trys atramos taškai (three points of contact) ne visada reiškia dvi kojas ir vieną ranką. Kai trumpam reikia abiejų laisvų rankų, tai gali būti dvi kojos ir kūnas – keliai ar krūtinė, atremti į sustatomąsias kopėčias. Įsitikinkite, kad prieš tai ir po to turite už ko laikytis.","why_not":{"0":"Vienos kojos neužtenka; abi kojos ant kopėčių, o kūnas atremtas į kopėčias.","1":"Galite: abi kojos ir į kopėčias atremtas kūnas skaičiuojami kaip trys atramos taškai (three points of contact).","3":"Stovėti ant vienos kojos nesaugu; abi kojos turi būti ant kopėčių, o kūnas – atremtas į jas."}},"high-risk-b3-07":{"question":"Jūsų komanda planuoja darbą aukštyje. Kažkas sako, kad gelbėjimo planas paprastas: „Jei kas nors įstrigs ar nukris, skambinsime 999.“ Ką sako HSE (darbo saugos tarnyba)?","options":["Planas neturi remtis tik pagalbos tarnybomis: komanda turi turėti savo nustatytą žmonių gelbėjimo būdą","Sudaryti planą pradėjus darbą, kai pamatysite, kas gali nutikti","To užtenka, nes gelbėti žmones leidžiama tik ugniagesiams","Jei darbas trumpas, gelbėjimo plano nereikia"],"explanation":"HSE (darbo saugos tarnyba) sako planuoti avarines situacijas ir gelbėjimą, susitarti dėl nustatytos tvarkos ir užtikrinti, kad darbuotojai ją žinotų. Ji taip pat sako, kad gelbėjimo plane nereikia visiškai pasikliauti pagalbos tarnybomis.","why_not":{"1":"Gelbėjimo planas turi būti sudarytas prieš pradedant darbą, kad visi jį žinotų.","2":"Netiesa; HSE (darbo saugos tarnyba) sako nepasikliauti vien pagalbos tarnybomis gelbėjant žmones.","3":"Net trumpiems darbams reikia avarinių situacijų ir gelbėjimo plano."}},"high-risk-b3-09":{"question":"Kad ilgą siją būtų galima užkelti ant pastolių platformos, pastolių montuotojas turi nuimti dalį apsauginio turėklo (guard-rail). Ką sako įstatymas?","options":["Nuimti jį tik tiek laiko, kiek reikia, taikyti kitas saugos priemones, kol jo nėra, ir kuo greičiau jį grąžinti","Dirbti su atvira anga: nieko daugiau nereikia, jei visi atsargūs","Nuimti visą turėklo ilgį, kad būtų daug vietos","Palikti jį nuimtą iki savaitės pabaigos, nes atveš daugiau sijų"],"explanation":"Įstatymas sako, kad apsauginius turėklus ir panašią apsaugą galima nuimti tik tokiam laikui ir tiek, kiek reikia, ir kad juos reikia grąžinti, kai tik tai įmanoma. Kol jie nuimti, dirbti negalima, nebent taikomos kitos veiksmingos saugos priemonės.","why_not":{"1":"Neužtenka būti atsargiems; kol apsauginio turėklo (guard-rail) nėra, reikia kitų saugos priemonių.","2":"Nuimkite tik tiek, kiek reikia, ir kuo trumpesniam laikui.","3":"Jį reikia grąžinti kuo greičiau, o ne palikti nuimtą kelioms dienoms."}},"high-risk-b3-10":{"question":"Pastolių inkaras (scaffold tie – tvirtinimas, laikantis pastolius prie pastato) trukdo langui, kurį montuojate. Kas turėtų būti daroma?","options":["Išimti jį patiems, nes vienas inkaras nieko nereiškia","Šiek tiek jį atlaisvinti, kad galėtumėte dirbti aplink jį","Išimti jį ir dienos pabaigoje vėl įdėti","Pakviesti kompetentingą pastolių montuotoją: jei inkaras perkeliamas, netoliese turi būti įrengtas lygiavertis inkaras"],"explanation":"Inkarai palaiko pastolių stabilumą. Pastolius keisti gali tik kompetentingi žmonės. HSE (darbo saugos tarnyba) sako, kad jei inkaras išimamas, kad būtų galima dirbti, netoliese turi būti įrengtas lygiavertis inkaras, kad pastoliai liktų stabilūs. Jei jį išimsite patys, net vienai dienai, pastoliai gali tapti nesaugūs.","why_not":{"0":"Svarbus kiekvienas inkaras; pastolius keisti gali tik kompetentingas asmuo.","1":"Atlaisvinus inkarą (scaffold tie), pastoliai gali tapti nestabilūs; keisti juos gali tik kompetentingi žmonės.","2":"Net vienai dienai pastoliai gali tapti nesaugūs; netoliese turi būti įrengtas lygiavertis inkaras."}},"high-risk-b3-11":{"question":"Atvykstate prie pastolių, kurių pastolių montuotojai dar nebaigė. Ant jų yra įspėjamieji ženklai, o kopėčias užtveria užtvara. Jums reikia užlipti tik 5 minutėms. Ką darote?","options":["Atsargiai užlipate, laikydamiesi atokiau nuo nebaigto galo","Užlipate, jei pastolių montuotojas vis dar ant jų dirba","Nelipate: jais naudotis negalima, kol jie nebaigti ir paruošti naudoti","Patraukiate užtvarą, užlipate, o paskui užtvarą grąžinate"],"explanation":"HSE (darbo saugos tarnyba) sako, kad pastoliai, kurie nėra paruošti naudoti, taip pat tada, kai jie statomi, ardomi ar keičiami, turi turėti įspėjamuosius ženklus ir fizinę užtvarą, kad žmonės negalėtų patekti į pavojingą vietą. Ženklai ir užtvara reiškia „nelipti“, kad ir koks trumpas būtų darbas.","why_not":{"0":"Niekas neturėtų naudotis nebaigtais pastoliais, net laikydamasis atokiau nuo nebaigto galo.","1":"Tai, kad ant jų dirba pastolių montuotojai, nereiškia, kad jie paruošti; nelipkite, kol jie nebaigti.","3":"Užtvara skirta neleisti jums lipti; niekada jos nepatraukite, kad ir koks trumpas būtų darbas."}},"high-risk-b3-12":{"question":"Dirbsite iš mobiliosios keliamosios darbo platformos (MEWP) krepšio prie gilios upės. Rizikos vertinime (risk assessment) parašyta, kad didžiausias pavojus – nuskęsti, jei platforma įkristų į vandenį. Ką turėtumėte dėvėti?","options":["Nieko papildomo, nes krepšys turi apsauginius turėklus","Saugos diržus (harness), prisegtus prie krepšio, o ant jų gelbėjimosi liemenę","Saugos diržus (harness), prisegtus prie krepšio, kaip ir bet kurioje platformoje","Gelbėjimosi liemenę, o ne saugos diržus"],"explanation":"HSE (darbo saugos tarnyba) sako, kad darbą prie vandens ar virš jo reikia įvertinti ir nuspręsti, kuri rizika didesnė: iškristi iš krepšio ar nuskęsti, jei platforma (MEWP) įkristų į vandenį. Kur yra rizika nuskęsti, dėvėkite gelbėjimosi liemenę, o ne saugos diržus.","why_not":{"0":"Turėklai nepadės, jei platforma (MEWP) įkris į vandenį; dėvėkite gelbėjimosi liemenę.","1":"Saugos diržai (harness) gali jus laikyti prie skęstančios platformos (MEWP); kur gresia nuskęsti, saugos diržų nedėvėkite.","2":"Čia didžiausias pavojus – nuskęsti, todėl HSE (darbo saugos tarnyba) sako dėvėti gelbėjimosi liemenę, o ne saugos diržus (harness)."}},"high-risk-b3-13":{"question":"Esate mobiliojoje keliamojoje darbo platformoje (MEWP) ir tvirtinate ilgus vamzdžius. Jie netelpa į krepšį, todėl bendradarbis siūlo juos padėti skersai ant apsauginių turėklų. Ką sako HSE (darbo saugos tarnyba)?","options":["Viskas gerai, jei laikote juos ant turėklo viena ranka","Viskas gerai, jei vamzdžiai trumpi, iki 3 metrų","Niekada nedėkite medžiagų ant turėklų: joms tvarkyti naudokite kitą įrangą, pvz., kraną ar teleskopinį krautuvą (telehandler)","Viskas gerai, jei vamzdžiai prilipdyti juosta prie turėklų"],"explanation":"HSE (darbo saugos tarnyba) sako, kad medžiagų niekada negalima balansuoti ant platformos (MEWP) turėklų. Vietoj to pagalvokite apie kitą techniką medžiagoms tvarkyti, pvz., antrą platformą, žirklinę keltuvo platformą (scissor lift), kraną ar teleskopinį krautuvą (telehandler). Taip sumažėja rizika, kad platforma apvirs, ir rizika susižeisti nešant.","why_not":{"0":"Laikymas rankoje nepadaro to saugaus; niekada nebalansuokite medžiagų ant turėklų.","1":"Trumpi vamzdžiai – ne išimtis; niekada nebalansuokite medžiagų ant platformos (MEWP) turėklų.","3":"Prilipdyti juosta, jie vis tiek balansuoja ant turėklų; jiems perkelti naudokite kitą įrangą."}},"high-risk-b3-14":{"question":"Jūsų mobiliosios keliamosios darbo platformos (MEWP) perkrovos signalas vis įsijungia, kai į krepšį sudedate įrankius ir blokelius. Bendradarbis sako žinantis, kaip signalą išjungti. Ką turėtumėte daryti?","options":["Niekada jo neišjungti: sumažinti svorį, nes į apkrovą įskaičiuojami žmonės, įrankiai ir medžiagos","Dirbti toliau: signalas tik priminimas","Išjungti jį tik šiam vienam darbui","Išjungti jį, nes jis skaičiuoja tik žmonių svorį"],"explanation":"Viskas, kas yra krepšyje, įskaičiuojama į platformos leistiną darbo apkrovą (safe working load): žmonės, įrankiai, medžiagos ir bet kokie kėlimo įtaisai. HSE (darbo saugos tarnyba) sako niekada neišjungti perkrovos sistemos. Jei ji įsijungia, nedelsdami pašalinkite perteklinį svorį, jei galite.","why_not":{"1":"Signalas įspėja apie perkrovą; perteklinį svorį pašalinkite iš karto.","2":"Niekada neišjunkite perkrovos sistemos, net vienam darbui.","3":"Neteisingai: į apkrovą įskaičiuojami ne tik žmonės, bet ir įrankiai bei medžiagos."}},"high-risk-b3-16":{"question":"Kaip turėtumėte patikrinti savo juostinį apsaugos nuo kritimo saugos lyną (lanyard) prieš jį naudodami?","options":["Apžiūrėti jį pro maišelį: jei atrodo švarus, viskas gerai","Lėtai praleisti visą lyną per rankas gerai apšviestoje vietoje, čiuopiant ir ieškant pažeidimų","Staigiai jį truktelėti ir pažiūrėti, ar atlaikys","Pažiūrėti datą etiketėje: jei galioja, viskas gerai"],"explanation":"HSE (darbo saugos tarnyba) sako, kad patikrinimas prieš naudojimą (pre-use check) daromas čiuopiant ir žiūrint. Lėtai praleiskite visą saugos lyną per rankas, kad rastumėte mažas įpjovas kraštuose, suminkštėjusius ar sukietėjusius pluoštus, nešvarumus ar chemines medžiagas. Apžiūrėkite jį gerai apšviestoje vietoje. Paprastai tai užtrunka kelias minutes.","why_not":{"0":"Žiūrint pro maišelį, mažų įpjovų nepastebėsite; praleiskite visą saugos lyną (lanyard) per rankas.","2":"Truktelėjus nerasite mažų įpjovų ar pažeistų pluoštų; tikrinkite čiuopdami ir žiūrėdami.","3":"Galiojanti data nerodo pažeidimų; patikrinkite visą saugos lyną (lanyard) rankomis ir akimis."}},"high-risk-b3-17":{"question":"Tranšėjai reikės tranšėjos skydų (trench sheets) ir atramų (props). Ekskavatorius paruoštas, bet skydus atveš tik rytoj. Kas turėtų būti daroma?","options":["Kasti šiandien, o skydus įrengti rytoj","Kasti šiandien, bet į tranšėją leisti žmones tik trumpiems darbams","Laukti: tvirtinimo įranga turi būti statybvietėje prieš pradedant kasti","Kasti šiandien, jei gruntas atrodo tvirtas"],"explanation":"HSE (darbo saugos tarnyba) sako prieš kasant nuspręsti, kokio tvirtinimo reikia tranšėjai, ir užtikrinti, kad įranga, pvz., tranšėjos skydai (trench sheets) ir atramos (props), būtų statybvietėje prieš pradedant darbą.","why_not":{"0":"Tvirtinimo įranga turi būti statybvietėje prieš pradedant kasti, o ne kitą dieną.","1":"Net trumpi darbai nesutvirtintoje tranšėjoje pavojingi; palaukite tvirtinimo įrangos.","3":"Tvirtai atrodantis gruntas vis tiek gali nugriūti; tvirtinimo įranga turi būti čia iš anksto."}},"high-risk-b3-18":{"question":"Vietoj atramų iškasos šlaitai daromi nuožulnūs (battered). Gruntas šlapias. Ką HSE (darbo saugos tarnyba) sako apie šlaito nuolydį?","options":["Jis gali būti statesnis, nes šlapias gruntas sukimba","Jis turi būti daug lėkštesnis (ne toks status), nei būtų sausame grunte","Vanduo nieko nekeičia: svarbu tik gylis","Jis gali būti toks pat kaip sausame grunte"],"explanation":"Iškasos šlaitai, padaryti saugaus kampo nuožulnumu, gali padaryti iškasą saugesnę. HSE (darbo saugos tarnyba) sako, kad šlapiame grunte reikia daug lėkštesnio šlaito.","why_not":{"0":"Atvirkščiai; šlapiame grunte reikia daug lėkštesnio šlaito, o ne statesnio.","2":"Vanduo svarbus; HSE (darbo saugos tarnyba) sako, kad šlapiame grunte reikia daug lėkštesnio šlaito.","3":"Šlapiame grunte reikia daug lėkštesnio šlaito nei sausame."}},"high-risk-b3-20":{"question":"Tranšėja kasama šalia didelio medžio, ir ekskavatorius kerta storas jo šaknis. Kodėl tai saugos problema, o ne tik žala medžiui?","options":["Medžio šaknys gali praleisti elektrą","Tai ne saugos problema: tai kenkia tik medžiui","Nukirstos šaknys išskiria nuodingas dujas","Nukirtus ar pažeidus šaknis medis gali nuvirsti"],"explanation":"HSE (darbo saugos tarnyba) įspėja, kad kasant pažeisti medžiai, taip pat nukirtus ar pažeidus jų šaknis, gali nuvirsti ir ką nors sužeisti.","why_not":{"0":"Šaknys nepraleidžia elektros; pavojus – kad medis nuvirs.","1":"Tai saugos problema; nukirtus šaknis, medis gali nuvirsti ant žmonių.","2":"Šaknys neišskiria nuodingų dujų; pavojus – kad medis nuvirs."}},"high-risk-b3-21":{"question":"Kasate gilią duobę buvusios dujų gamyklos teritorijoje. Kodėl HSE (darbo saugos tarnyba) įspėja dėl duobių ir tranšėjų tokiame grunte?","options":["Nugriovus senus pastatus papildomo pavojaus nebėra","Vienintelis pavojus – išsitepti drabužius","Gruntas visada per kietas, kad būtų galima kasti rankomis","Į jas iš užteršto grunto gali prasiskverbti nuodingų dujų"],"explanation":"HSE (darbo saugos tarnyba) sako, kad į tranšėjas ir duobes užterštoje žemėje, pvz., senuose sąvartynuose ir buvusiose dujų gamyklose, gali prasiskverbti nuodingų dujų, dūmų ar garų.","why_not":{"0":"Nugriovus pastatus, pats gruntas vis tiek gali būti užterštas.","1":"Tikrasis pavojus – į duobę prasiskverbiančios nuodingos dujos.","2":"HSE (darbo saugos tarnyba) įspėja ne dėl kieto grunto; čia į duobes gali prasiskverbti nuodingų dujų."}},"high-risk-b3-22":{"question":"Bendradarbis sako: „Šios patalpos nėra jokiame uždarų erdvių sąraše, todėl ji niekada negali būti uždara erdvė.“ Ar jis teisus?","options":["Ne, bet tik jei patalpa visai neturi durų","Ne: vieta gali tapti uždara erdve (confined space) dėl joje atliekamo darbo arba tada, kai ji statoma ar keičiama","Taip: skaičiuojamos tik oficialiame sąraše esančios vietos","Taip: uždaros erdvės gali būti tik po žeme"],"explanation":"HSE (darbo saugos tarnyba) sako, kad neįmanoma pateikti viso uždarų erdvių (confined spaces) sąrašo. Kai kurios vietos tampa uždaromis erdvėmis, kai jose dirbama arba kai jos statomos ar keičiamos. Svarbu, ar yra mirties ar sunkios traumos rizika dėl tokių dalykų kaip dujos, dūmai ar deguonies trūkumas.","why_not":{"0":"Patalpa gali būti uždara erdvė (confined space) ir su durimis; tai priklauso nuo rizikos.","2":"Viso sąrašo nėra; vietos gali tapti uždaromis erdvėmis (confined spaces) dėl atliekamo darbo.","3":"Uždaros erdvės (confined spaces) gali būti ir virš žemės, pvz., talpos ir prastai vėdinamos patalpos."}},"high-risk-b3-24":{"question":"Darbas bus atliekamas kameroje, kurioje tikėtini degūs garai. Kokie įrankiai ir šviestuvai, pasak HSE (darbo saugos tarnybos), būtini?","options":["Kibirkščių nesukeliantys įrankiai ir specialiai apsaugoti šviestuvai","Įprasti darbo šviestuvai, jei jie LED ir neįkaista","Bet kokie įrankiai, jei kameros dangtis paliktas atidarytas","Įprasti įrankiai, jei jie veikia su akumuliatoriumi"],"explanation":"Kur tikėtina degi ar sprogi aplinka, įrankio ar šviestuvo kibirkštis gali ją uždegti. HSE (darbo saugos tarnyba) sako, kad tokiose vietose būtini kibirkščių nesukeliantys įrankiai ir specialiai apsaugoti šviestuvai.","why_not":{"1":"Įprasti šviestuvai vis tiek gali sukelti kibirkštį; būtini specialiai apsaugoti šviestuvai.","2":"Atidarytas dangtis neapsaugo nuo to, kad kibirkštis uždegtų garus; naudokite kibirkščių nesukeliančius įrankius.","3":"Akumuliatoriniai įrankiai vis tiek gali sukelti kibirkštį; kur tikėtini garai, naudokite kibirkščių nesukeliančius įrankius."}},"high-risk-b3-25":{"question":"Dirbate kanalizacijos kolektoriuje, kurio dugnu teka tik nedaug vandens. Ar vis tiek gali grėsti pavojus nuskęsti?","options":["Ne: vandenyje, kuris žemiau kelių, nuskęsti negalima","Tik jei nemokate plaukti","Taip: vanduo gali įtekėti, o žmonės gali nuskęsti net nedideliame skysčio gylyje","Ne: kolektoriai niekada neprisipildo vandens"],"explanation":"HSE (darbo saugos tarnyba) sako, kad į uždarą erdvę (confined space), pvz., kanalizacijos kolektorių, gali įtekėti skysčio, ir žmogus gali nuskęsti. Ji taip pat įspėja, kad nuskęsti galima net nedideliame skysčio gylyje.","why_not":{"0":"Nuskęsti galima net nedideliame skysčio gylyje, be to, gali įtekėti daugiau.","1":"Mokėjimas plaukti nuo to neapsaugo; žmonės nuskęsta net nedideliame skysčio gylyje.","3":"Į kanalizacijos kolektorius gali įtekėti skysčio, ir galima nuskęsti."}},"high-risk-b3-26":{"question":"Jūsų prašo įlįsti į didelį bunkerį (hopper), iki pusės pripildytą sauso smėlio, ir pašalinti užsikimšimą. Dėl kokio paslėpto pavojaus įspėja HSE (darbo saugos tarnyba)?","options":["Pavojaus nėra, nes smėlis nėra cheminė medžiaga","Sausas smėlis gali savaime užsidegti","Smėlis gali pajudėti ir jus užpilti, todėl negalėsite kvėpuoti","Vienintelis pavojus – smėlis prisipils į batus"],"explanation":"HSE (darbo saugos tarnyba) sako, kad laisvai byrančios medžiagos, pvz., smėlis, grūdai ir miltai, gali užpilti žmogų, ir jis negalės kvėpuoti. Uždaroje erdvėje (confined space) pavojus didesnis, nes medžiagai nėra kur kitur byrėti.","why_not":{"0":"Tai neturi būti cheminė medžiaga; byrantis smėlis gali jus užpilti.","1":"Įspėjama ne dėl gaisro; smėlis gali jus užpilti, ir negalėsite kvėpuoti.","3":"Tikrasis pavojus – būti užpiltam byrančio smėlio ir negalėti kvėpuoti."}},"high-risk-b3-27":{"question":"Drenažo kameroje aplink vamzdžius prigrūsta šlapios kalkakmenio skaldos. Kodėl oras viduje gali būti nesaugus kvėpuoti?","options":["Šlapias kalkakmenis išskiria papildomo deguonies, todėl tikėtinas gaisras","Akmens skalda negali pakeisti oro patalpoje","Kalkakmenis svarbus tik tada, kai jis sausas ir dulkėtas","Šlapia kalkakmenio skalda gali padidinti anglies dioksido kiekį, todėl gali trūkti deguonies"],"explanation":"HSE (darbo saugos tarnyba) nurodo drenažo darbuose naudojamą šlapią kalkakmenio skaldą kaip vieną iš deguonies trūkumo priežasčių, nes sušlapusi ji padidina anglies dioksido kiekį.","why_not":{"0":"Šlapias kalkakmenis neišskiria deguonies; jis padidina anglies dioksido kiekį, ir deguonies lieka mažiau.","1":"Šlapia kalkakmenio skalda gali pakeisti orą, nes padidina anglies dioksido kiekį.","2":"Anglies dioksido kiekį kalkakmenis padidina būtent tada, kai sušlampa."}},"high-risk-b3-28":{"question":"Jūsų bendradarbis yra šulinyje (manhole). Visai prie angos pastatytas savivartis (dumper) su veikiančiu varikliu. Kodėl tai pavojinga?","options":["Tai tik triukšmo problema","Savivarčio išmetamosios dujos gali patekti į šulinį ir užnuodyti orą","Išmetamosios dujos visada kyla aukštyn, todėl į šulinį patekti negali","Tai pavojinga tik tada, jei savivartis varomas benzinu"],"explanation":"HSE (darbo saugos tarnyba) sako, kad kenksmingi dūmai gali patekti į uždarą erdvę (confined space) dėl to, kas vyksta už jos ribų, taip pat ir statybvietės judančios technikos išmetamosios dujos.","why_not":{"0":"Tai ne tik triukšmas; išmetamosios dujos gali patekti į šulinį.","2":"Neteisingai; lauke dirbančios technikos išmetamosios dujos gali patekti į uždaras erdves (confined spaces).","3":"Patekti gali bet kokios judančios technikos išmetamosios dujos, ne tik benzininių variklių."}},"high-risk-b3-29":{"question":"Statybvietės kranas kelia tik medžiagas, niekada žmonių. Patikrinimo plano (examination scheme) jam nėra. Bent kaip dažnai jį turi nuodugniai patikrinti (thorough examination) kompetentingas asmuo (competent person)?","options":["Tik vieną kartą, kai jis pirmą kartą pastatomas","Bent kartą per 12 mėnesių","Bent kartą per 7 dienas","Bent kartą per 5 metus"],"explanation":"Kėlimo operacijų ir kėlimo įrangos taisyklės (LOLER) nustato naudojamos įrangos nuodugnių patikrinimų intervalus: bent kas 6 mėnesius kėlimo priedams (lifting accessories) ir įrangai, kuria keliami žmonės, ir bent kas metus visai kitai kėlimo įrangai, nebent kompetentingas asmuo (competent person) yra parengęs patikrinimo planą (examination scheme).","why_not":{"0":"Vieno patikrinimo, kai jis naujas, neužtenka; nuodugniai patikrinti (thorough examination) jį reikia bent kartą per metus.","2":"7 dienos nėra įstatymo nustatytas nuodugnaus patikrinimo (thorough examination) intervalas; tai bent kas 12 mėnesių.","3":"5 metai – gerokai per ilgai; jį reikia patikrinti bent kas 12 mėnesių."}},"high-risk-b3-30":{"question":"Statybvietės keltuvas (hoist) daug mėnesių nebuvo naudojamas, kol statybvietė buvo uždaryta. Paskutinis nuodugnus patikrinimas buvo atliktas neilgai prieš uždarant statybvietę. Kas turėtų būti padaryta, prieš vėl juo naudojantis?","options":["Nieko: paskutinis patikrinimas dar galioja","Operatorius tik vieną kartą pakelia ir nuleidžia jį, kad pamatytų, ar veikia","Sutepti judančias dalis ir vėl pradėti naudoti","Jį reikia vėl nuodugniai patikrinti, nes ilgas nenaudojimas laikomas išskirtinėmis aplinkybėmis (exceptional circumstances)"],"explanation":"HSE (darbo saugos tarnyba) sako, kad kėlimo įrangą visada reikia nuodugniai patikrinti po „išskirtinių aplinkybių“ (exceptional circumstances), ir kaip pavyzdį nurodo ilgą nenaudojimą, taip pat pažeidimą ar gedimą. Tai taikoma net tada, kai paskutinis patikrinimas dar galioja.","why_not":{"0":"Ilgas nenaudojimas laikomas išskirtinėmis aplinkybėmis (exceptional circumstances), todėl jį vis tiek reikia patikrinti iš naujo.","1":"Trumpas bandymas nėra kompetentingo asmens (competent person) atliekamas nuodugnus patikrinimas.","2":"Sutepimas nėra patikrinimas; pirmiausia jį reikia nuodugniai patikrinti."}},"high-risk-b3-31":{"question":"Tuoj bus keliamas plieno ryšulys. Niekas tiksliai nežino, kiek jis sveria, ir jis gali būti per sunkus kėlimo įrangai. Kas turėtų būti daroma?","options":["Nekelti, kol nebūsite tikri dėl jo svorio ir kad įranga jį atlaikys","Kelti, bet visiems laikytis toli","Kelti lėtai ir žiūrėti, ar stropas atlaikys","Įvertinti svorį iš akies pagal dydį ir kelti"],"explanation":"HSE (darbo saugos tarnyba) sąraše, ko nedaryti, yra krovinio kėlimas, jei abejojate jo svoriu ar tuo, ar įranga tinkama. Pirmiausia sužinokite svorį ir niekada neviršykite mašinos ar priedų, pvz., stropų, leistinos darbo apkrovos (safe working load).","why_not":{"1":"Laikymasis toli neapsaugo nuo įrangos gedimo; nekelkite, jei abejojate svoriu.","2":"Tikrinant keliant, stropas gali neatlaikyti; pirmiausia sužinokite svorį.","3":"Spėjant galima perkrauti įrangą; niekada nekelkite, jei abejojate svoriu."}},"high-risk-b3-32":{"question":"Kranui keliant krovinį, sustiprėja vėjas, ir krovinys pradeda siūbuoti. Kas turėtų turėti teisę sustabdyti kėlimą?","options":["Niekas: pradėtą kėlimą reikia užbaigti","Tik užsakovas, kuriam priklauso pastatas","Tik krano nuomos įmonės biuras","Kėlimo vadovas (crane supervisor), kuris vadovauja kėlimui ir gali jį sustabdyti, jei jis tampa pavojingas"],"explanation":"HSE (darbo saugos tarnyba) sako, kad kėlimo vadovas (crane supervisor) vadovauja kėlimui ir jį prižiūri. Jis turi būti kompetentingas ir turėti teisę sustabdyti kėlimo darbą, jei manoma, kad tęsti pavojinga.","why_not":{"0":"Pavojingą kėlimą reikia sustabdyti; kėlimo vadovas (crane supervisor) turi teisę jį sustabdyti.","1":"Kėlimui vadovauja ne užsakovas; sustabdyti jį gali kėlimo vadovas (crane supervisor).","2":"Nuomos įmonės biuras kėlimo nemato; jį sustabdyti gali statybvietėje esantis kėlimo vadovas (crane supervisor)."}},"high-risk-b3-33":{"question":"Kaip turėtų būti įrengti statybvietės krovininio keltuvo (goods hoist) valdikliai?","options":["Su iškvietimo mygtukais kiekviename aukšte, kad bet kas galėtų jį pakelti","Bet kur, jei keltuvas turi įspėjamąjį garso signalą","Taip, kad jį būtų galima valdyti tik iš vienos vietos, iš kurios operatorius mato visas aukštų aikšteles","Su valdikliais ant platformos, kad žmogus galėtų važiuoti juo aukštyn ir jį valdyti"],"explanation":"HSE (darbo saugos tarnyba) sako, kad krovininiai keltuvai (goods hoists) turi būti įrengti taip, kad juos būtų galima valdyti tik iš vienos vietos, pvz., nuo žemės lygio, iš kurios operatorius mato visas aukštų aikšteles.","why_not":{"0":"Krovininiai keltuvai (goods hoists) turėtų būti valdomi tik iš vienos vietos, o ne iš kiekvieno aukšto.","1":"Garso signalo neužtenka; operatorius turi valdyti keltuvą iš vienos vietos, iš kurios mato visas aukštų aikšteles.","3":"Žmonės niekada negali važiuoti krovininiu keltuvu (goods hoist); jis valdomas iš vienos vietos."}},"high-risk-b3-35":{"question":"Pastatas judriame miesto centre griaunamas aukštas po aukšto iš viršaus, naudojant mažas mašinas. Kodėl dažnai pasirenkamas šis „iš viršaus žemyn“ (top-down) būdas?","options":["Taip geriau kontroliuojama, kiek pastatas išlieka stabilus ir kur krenta nuolaužos","Tada nereikia draudžiamosios zonos (exclusion zone)","Tai visada greičiausias būdas","Tada pastato nereikia iš anksto tirti"],"explanation":"HSE (darbo saugos tarnyba) sako, kad griaunant iš viršaus žemyn (top-down), kai pastatas ardomas aukštas po aukšto mažąja technika, galima kontroliuoti konstrukcijos stabilumą ir nuolaužų kaupimąsi bei plitimą. Todėl miesto centro statybvietėse šis būdas dažnai pasirenkamas.","why_not":{"1":"Griaunant iš viršaus žemyn (top-down), draudžiamosios zonos (exclusion zone) vis tiek reikia; šis būdas leidžia geriau kontroliuoti nuolaužas.","2":"Priežastis – ne greitis; šis būdas leidžia kontroliuoti stabilumą ir nuolaužas.","3":"Tyrimo vis tiek reikia; būdas iš viršaus žemyn (top-down) pasirenkamas dėl kontrolės, o ne tam, kad būtų galima praleisti patikrinimus."}},"high-risk-b3-36":{"question":"Kokia tvarka griaunant paprastai reikia ardyti konstrukcijos dalis?","options":["Pirmiausia ardoma pagrindinė standi šerdis, kad netrukdytų","Pirmiausia ardomas apatinis aukštas, kad visa kita nukristų žemyn","Tai, ką lengviausia pasiekti, bet kokia tvarka","Pirmiausia ardomos dalys, kurios nereikalingos, kad konstrukcija stovėtų, palaipsniui pereinant prie standžių dalių, kurios ją laiko"],"explanation":"HSE (darbo saugos tarnyba) sako, kad darbų tvarka turi atmesti nekontroliuojamo sugriuvimo galimybę. Pavyzdžiui, pirmiausia ardomos dalys, kurios nėra svarbios bendram stabilumui, o paskui pereinama prie standžių dalių, pvz., sutvirtintų šerdžių, kurios laiko konstrukciją.","why_not":{"0":"Pirmiausia nugriovus standžią šerdį, pastatas gali nekontroliuojamai sugriūti; ji ardoma paskutinė.","1":"Pirmiausia nugriovus apatinį aukštą, visas pastatas gali sugriūti nekontroliuojamai.","2":"Ardant bet kokia tvarka, pastatas gali nekontroliuojamai sugriūti; laikykitės suplanuotos tvarkos."}},"high-risk-b3-37":{"question":"Draudžiamoji zona (exclusion zone) aplink griovimo darbus buvo pažymėta pirmą dieną. Dabar darbas perėjo į kitą etapą. Ką sako HSE (darbo saugos tarnyba)?","options":["Pažymėtos draudžiamosios zonos niekada negalima keisti","Keičiantis darbui draudžiamąsias zonas gali reikėti keisti, o jei kas nors sugriūva, nuolaužos turi likti zonos viduje","Nesvarbu, jei mažos nuolaužos nukrenta už zonos ribų","Draudžiamosios zonos svarbios tik pirmą dieną"],"explanation":"HSE (darbo saugos tarnyba) sako, kad vykstant darbams draudžiamąsias zonas (exclusion zones) gali reikėti keisti, todėl plane tai turi būti numatyta. Jei kas nors sugriūva, tyčia ar netyčia, nuolaužos turi likti zonos viduje.","why_not":{"0":"Keičiantis darbui, draudžiamąsias zonas (exclusion zones) gali reikėti keisti.","2":"Jei kas nors sugriūva, visos nuolaužos turi likti zonos viduje, net ir mažos.","3":"Draudžiamosios zonos (exclusion zones) svarbios viso darbo metu, ne tik pirmą dieną."}},"high-risk-b3-38":{"question":"Uždengti pastoliai pritvirtinti prie pastato, kuris griaunamas iš viršaus. Pastatas dabar žemesnis už pastolių viršų. Koks pavojus?","options":["Pavojaus nėra: uždengimas pastolius sustiprina","Virš pastato kyšantys uždengti pastoliai gaudo vėją kaip burė, todėl juos reikia žeminti, kai pastatas žemėja","Jokio, jei inkarai nuimami, kad pastoliai galėtų judėti su vėju","Vienintelė problema – gali išpūsti dulkes"],"explanation":"Uždengimas padidina vėjo jėgą, spaudžiančią pastolius, o ta apkrova per inkarus perduodama pastatui. HSE (darbo saugos tarnyba) sako, kad uždengti pastoliai, kurie laikosi ant inkarų, turi būti žeminami griaunant pastatą ir negali veikti kaip didelė burė virš iš dalies nugriautos konstrukcijos.","why_not":{"0":"Uždengus pastolius, vėjas juos spaudžia stipriau; uždengimas jų nesustiprina.","2":"Pastoliai laikosi ant inkarų; juos reikia žeminti, kai pastatas žemėja.","3":"Didesnis pavojus – vėjo apkrova uždengtiems pastoliams, o ne tik dulkės."}},"high-risk-b3-40":{"question":"Dirbate griovimo darbuose. Manote, kad žinote greitesnį būdą nugriauti sieną nei tas, kuris nurodytas plane. Ką turėtumėte daryti?","options":["Laikytis jums duoto plano ir nurodymų, o savo idėją aptarti su atsakingu asmeniu","Daryti savaip, bet pasakyti bendradarbiams pasitraukti","Laikytis plano tik tada, kai darbų vadovas mato","Daryti savaip, nes taip greičiau"],"explanation":"HSE (darbo saugos tarnyba) sako, kad subrangovai ir statybvietės darbuotojai turi laikytis jiems duotų nurodymų ir planų ir užtikrinti, kad jų bendradarbiai darytų tą patį. Jei turite geresnę idėją, pasakykite atsakingam asmeniui, o ne keiskite darbo būdą patys.","why_not":{"1":"Nekeiskite darbo būdo patys; laikykitės jums duoto plano.","2":"Plano reikia laikytis visada, ne tik tada, kai kas nors mato.","3":"Greičiau nereiškia saugiau; laikykitės plano, o savo idėją pasakykite atsakingam asmeniui."}},"occupational-health-b1-01":{"question":"Jūsų striukė peršlapo nuo lietaus. Džiovykloje (drying room) yra šildytuvas. Kaip turėtumėte išdžiovinti striukę?","options":["Pakabinti ją džiovykloje, bet ne ant šildytuvo","Užmesti ją ant šildytuvo, kad greičiau išdžiūtų","Uždėti ją ant šildytuvo ir šildytuvą įjungti stipriai","Šlapią susukti ir palikti spintelėje"],"explanation":"Statybvietėje turi būti vieta šlapiems drabužiams džiovinti. Bet HSE (darbo saugos tarnyba) sako, kad drabužių negalima dėti tiesiai ant šildytuvų, nes jie gali užsidegti. Vietoj to pakabinkite striukę džiovykloje. Šlapia susukta striukė visai neišdžiūsta.","why_not":{"1":"HSE (darbo saugos tarnyba) sako, kad drabužių negalima dėti tiesiai ant šildytuvų, nes jie gali užsidegti.","2":"Ant šildytuvo uždėti drabužiai gali sukelti gaisrą, o įjungus šildytuvą stipriai, pavojus dar didesnis.","3":"Šlapia susukta striukė visai neišdžiūsta. Pakabinkite ją džiovykloje (drying room)."}},"occupational-health-b1-04":{"question":"Bendradarbis sako: „Įstatymas sako, kad bet kokį krovinį iki 25 kg kelti saugu.“ Ar jis teisus?","options":["Ne. Įstatymas nenustato jokios svorio ribos, o HSE (darbo saugos tarnybos) rekomenduojami svoriai nėra saugios ribos","Taip. Bet koks krovinys iki 25 kg visada saugus","Taip, bet tik vyrams","Ne. Įstatyme nustatyta riba – 20 kg"],"explanation":"Krovinių rankinio tvarkymo taisyklės (Manual Handling Operations Regulations) nenustato jokių svorio ribų. HSE (darbo saugos tarnyba) pateikia rekomenduojamus svorius (guideline weights), kad darbdaviams būtų lengviau rasti mažos rizikos kėlimus, bet HSE sako, kad tai nėra „saugios ribos“ (safe limits). Ir lengvesnis krovinys gali jus sužaloti, pvz., jei keldami pasisukate ar laikote jį toli nuo kūno. Galvokite apie visą darbą, ne tik apie svorį.","why_not":{"1":"Įstatymas nenustato jokios svorio ribos, o HSE (darbo saugos tarnyba) sako, kad jos rekomenduojami svoriai (guideline weights) nėra saugios ribos.","2":"Įstatymas nenustato svorio ribos niekam – nei vyrams, nei moterims.","3":"Įstatyme nėra 20 kg ribos. Įstatymas apskritai nenustato jokių svorio ribų."}},"occupational-health-b1-05":{"question":"Darbdavys davė jūsų brigadai vežimėlį blokeliams vežti mūrininkams. Nešti juos rankomis būtų greičiau. Ką turėtumėte daryti?","options":["Naudoti vežimėlį, kaip nustatė darbdavys","Nešti juos rankomis, kad sutaupytumėte laiko","Naudoti vežimėlį tik tada, kai žiūri darbų vadovas","Nešti po du blokelius, kad reikėtų mažiau kartų eiti"],"explanation":"Įstatymas sako, kad turite pilnai ir tinkamai naudotis saugiu darbo būdu, kurį darbdavys nustatė traumų rizikai sumažinti. Vežimėlis skirtas jūsų nugarai apsaugoti. Nešdami blokelius rankomis, kad sutaupytumėte laiko, šios apsaugos atsisakote.","why_not":{"1":"Turite pilnai ir tinkamai naudotis saugiu darbo būdu, kurį nustatė darbdavys.","2":"Vežimėliu turite naudotis visada, ne tik tada, kai kas nors žiūri.","3":"Nešant po du blokelius, apkrova jums didesnė. Naudokite darbdavio duotą vežimėlį."}},"occupational-health-b1-06":{"question":"Kuriai iš šių medžiagų NETAIKOMOS pavojingų sveikatai medžiagų kontrolės taisyklės (COSHH), nes jai yra atskiras įstatymas?","options":["Asbestui","Cemento dulkėms","Tirpiklinių dažų garams","Žiurkių šlapime esantiems mikrobams, kurie sukelia Weil'io ligą (Weil's disease)"],"explanation":"Pavojingų sveikatai medžiagų kontrolės taisyklės (COSHH) taikomos daugumai darbe naudojamų medžiagų, galinčių pakenkti sveikatai, pvz., dulkėms, garams, chemikalams ir mikrobams. HSE (darbo saugos tarnyba) sako, kad COSHH netaikomos švinui, asbestui ir radioaktyviosioms medžiagoms, nes kiekvienai iš jų yra atskiros taisyklės. Cemento dulkėms, dažų garams ir mikrobams, sukeliantiems Weil'io ligą (Weil's disease, leptospirozę), COSHH taikomos.","why_not":{"1":"Cemento dulkėms COSHH taikomos. Atskiri įstatymai yra tik švinui, asbestui ir radioaktyviosioms medžiagoms.","2":"Dažų garams COSHH taikomos. Atskiri įstatymai yra tik švinui, asbestui ir radioaktyviosioms medžiagoms.","3":"Darbe sutinkamiems mikrobams, pvz., sukeliantiems Weil'io ligą (Weil's disease), COSHH taikomos."}},"occupational-health-b1-07":{"question":"Jūsų pjūklo dulkių nutraukimo žarna (dust extraction hose) įplyšo. Ką, pagal pavojingų sveikatai medžiagų kontrolės taisykles (COSHH), privalote daryti?","options":["Iš karto pranešti darbdaviui","Apvynioti lipnia juosta ir dirbti toliau niekam nesakant","Toliau naudoti iki darbo pabaigos","Nuimti žarną ir pjauti be dulkių nutraukimo"],"explanation":"Pagal COSHH turite pilnai ir tinkamai naudotis jums duotomis kontrolės priemonėmis, pvz., dulkių nutraukimu (dust extraction), ir apie bet kokį gedimą iš karto pranešti darbdaviui. Pro įplyšusią žarną išeina dulkės, todėl ji gali jūsų nebeapsaugoti. Pjauti visai be dulkių nutraukimo – dar blogiau.","why_not":{"1":"COSHH sako, kad apie gedimą turite iš karto pranešti darbdaviui, o ne jį slėpti.","2":"Pro įplyšusią žarną išeina dulkės. Iš karto praneškite apie gedimą, o ne naudokite toliau.","3":"Pjauti visai be dulkių nutraukimo (dust extraction) – dar blogiau. Iš karto praneškite darbdaviui apie gedimą."}},"occupational-health-b1-08":{"question":"Valote seną pastatą, kuriame gyveno žiurkės. Kodėl turite užklijuoti visas rankų žaizdeles neperšlampamais pleistrais?","options":["Mikrobai iš žiurkių šlapimo gali patekti į kūną pro žaizdeles ir sukelti Weil'io ligą (Weil's disease)","Pleistrai neleidžia žiurkėms jūsų įkąsti","Po pleistrais žaizdos greičiau gyja, todėl prarandate mažiau darbo laiko","Tik tam, kad kraujas nepatektų ant medžiagų"],"explanation":"Weil'io liga (Weil's disease, viena iš leptospirozės rūšių) plinta per užkrėstų žiurkių šlapimą. Mikrobai patenka į kūną pro įpjovimus ir įbrėžimus arba per burną, gerklę ir akis. Ji prasideda kaip gripas ir gali tapti labai rimta. Užklijuokite žaizdeles, mūvėkite pirštines, dažnai plaukite rankas, o valgykite ir gerkite atokiau nuo darbo vietos.","why_not":{"1":"Pleistrai nuo įkandimų neapsaugo. Jie neleidžia žiurkių šlapimo mikrobams patekti pro žaizdeles.","2":"Priežastis – ne gijimo laikas. Pro žaizdeles gali patekti žiurkių šlapimo mikrobai, sukeliantys Weil'io ligą (Weil's disease).","3":"Priežastis – ne tai, kad kraujas nepatektų ant daiktų. Pro žaizdeles gali patekti žiurkių šlapimo mikrobai."}},"occupational-health-b1-09":{"question":"Pjaunate grindinio plyteles pjūklu (cut-off saw) su vandens priedu. Kaip turėtumėte naudoti vandenį?","options":["Ant disko visą pjovimo laiką turi tekėti pakankamai vandens","Pirmiausia sušlapinti žemę, o tada pjauti sausai","Vandenį įjungti tik ilgiems pjūviams","Išjungti vandenį, kai dulkių debesis sumažėja"],"explanation":"Vanduo neleidžia silicio dioksido dulkėms (silica dust) pakilti į orą, bet tik tada, kai jis naudojamas tinkamai: pakankamai vandens visą darbo laiką. Vien sušlapinti žemę prieš pjaunant neveikia. Net su vandeniu vis tiek reikia tinkamos kaukės, nes vanduo sulaiko ne visas dulkes.","why_not":{"1":"HSE (darbo saugos tarnyba) sako, kad vien sušlapinti žemę prieš pjaunant neveikia. Vandens reikia visą laiką.","2":"Vandenį reikia naudoti visą pjovimo laiką – ir trumpiems, ir ilgiems pjūviams.","3":"Vanduo turi tekėti visą pjovimo laiką, kitaip dulkės vėl pakils į orą."}},"occupational-health-b1-11":{"question":"Pjausite betoninius blokelius pjūklu (cut-off saw), ant disko tekant vandeniui. Jums taip pat reikia kaukės. Kokio tipo vienkartinę kaukę šiam darbui pataria HSE (darbo saugos tarnyba)?","options":["FFP3","FFP1","Paprastą dulkių kaukę be FFP klasės","Medžiaginę veido kaukę"],"explanation":"Pjaunant betoną susidaro silicio dioksido dulkės (silica dust), o vanduo sulaiko ne visas. HSE (darbo saugos tarnyba) nurodo FFP2 ir FFP3 kaip du tipus, kurių reikia prašyti dirbant su statybinėmis dulkėmis, ir sako, kad FFP3 geriausia darbui, kai susidaro daug dulkių arba kai yra silicio dioksido ar medienos dulkių. Sandariai kaukei (tight-fitting mask) taip pat reikia priglundimo patikrinimo (face-fit test), o kad ji sandariai priglustų, turite būti švariai nusiskutę.","why_not":{"1":"HSE (darbo saugos tarnyba) statybinėms dulkėms nurodo FFP2 ir FFP3, o silicio dioksidui (silica) geriausia FFP3. FFP1 – silpnesnė.","2":"HSE (darbo saugos tarnyba) sako prašyti FFP2 ar FFP3 kaukių, o silicio dioksidui (silica) – FFP3. Kaukė be klasės nėra nei viena, nei kita.","3":"Medžiaginė veido kaukė nėra dulkių kaukė. Silicio dioksido dulkėms (silica dust) HSE (darbo saugos tarnyba) pataria FFP3 kaukę."}},"occupational-health-b1-13":{"question":"Esate klausos apsaugos zonoje (hearing protection zone) šalia skaldymo plaktuko (breaker). Kelioms minutėms pakeliate vieną apsauginę ausinę (ear defender), kad pasikalbėtumėte su bendradarbiu. Ką apie tai sako HSE (darbo saugos tarnyba)?","options":["Nusiėmus ją net trumpam, apsauga labai sumažėja","Kelios minutės be jos nesvarbu","Tai gerai, jei kita ausis uždengta","Tai svarbu tik tada, jei skaldymo plaktukas veikia visą dieną"],"explanation":"Klausos apsaugos priemones dėvėkite visą laiką, kol dirbate triukšmingą darbą ar esate klausos apsaugos zonoje (hearing protection zone). HSE (darbo saugos tarnyba) sako, kad nusiėmus jas net trumpam, bendra apsauga labai sumažėja, todėl klausa vis tiek gali būti pažeista.","why_not":{"1":"HSE (darbo saugos tarnyba) sako, kad nusiėmus ją net trumpam, gaunama apsauga labai sumažėja.","2":"Neuždengta ausis vis tiek pažeidžiama. Klausos apsaugos zonoje (hearing protection zone) klausos apsaugos priemones dėvėkite visą laiką.","3":"Net trumpa pertrauka be apsaugos sumažina bendrą gaunamą apsaugą, kad ir kiek laiko veiktų skaldymo plaktukas (breaker)."}},"occupational-health-b1-15":{"question":"Kokia yra dienos poveikio ribinė vertė (daily exposure limit value) rankų vibracijai pagal Vibracijos darbe kontrolės taisykles (Control of Vibration at Work Regulations 2005)?","options":["5 m/s² A(8)","2,5 m/s² A(8)","1,15 m/s² A(8)","10 m/s² A(8)"],"explanation":"Dienos poveikio ribinė vertė (daily exposure limit value) rankų vibracijai yra 5 m/s² A(8), skaičiuojant vidurkį per 8 valandų darbo dieną. Darbdavys turi užtikrinti, kad jūsų poveikis jos neviršytų. 2,5 m/s² A(8) yra poveikio veiksmų vertė (exposure action value): jei ji tikriausiai bus pasiekta, darbdavys turi sumažinti poveikį tiek, kiek pagrįstai įmanoma (reasonably practicable). 1,15 m/s² A(8) yra riba viso kūno vibracijai, ne rankų.","why_not":{"1":"2,5 m/s² A(8) yra poveikio veiksmų vertė (exposure action value), o ne ribinė vertė.","2":"1,15 m/s² A(8) yra riba viso kūno vibracijai, o ne rankų vibracijai.","3":"10 m/s² A(8) taisyklėse nėra. Rankų vibracijos riba – 5 m/s² A(8)."}},"occupational-health-b1-17":{"question":"Po kelių savaičių darbo skaldymo plaktuku (breaker) jūsų pirštai dažnai dilgčioja ir tirpsta. Ką turėtumėte daryti?","options":["Iš karto pranešti darbdaviui arba žmogui, kuris atlieka jūsų sveikatos patikrinimus","Palaukti ir pažiūrėti, ar tai praeis savaime","Mūvėti storesnes pirštines ir nieko nesakyti","Tylėti, kad jūsų neperkeltų į kitą darbą"],"explanation":"Dilgčiojimas ir tirpimas gali būti ankstyvi rankų vibracijos sindromo (hand-arm vibration syndrome, HAVS) požymiai. HSE (darbo saugos tarnyba) sako apie rankų problemas nedelsiant pranešti darbdaviui arba žmogui, kuris atlieka jūsų sveikatos patikrinimus. HAVS padaryta žala lieka visam laikui, todėl svarbu tai pastebėti anksti. Storos pirštinės šildo rankas, bet vibracijos nesustabdo.","why_not":{"1":"HSE (darbo saugos tarnyba) sako apie rankų problemas pranešti nedelsiant. HAVS padaryta žala lieka visam laikui, todėl laukiant gali pablogėti.","2":"Storos pirštinės vibracijos nesustabdo. Iš karto praneškite apie problemą darbdaviui.","3":"Tylint žala gali didėti. HSE (darbo saugos tarnyba) sako apie rankų problemas pranešti nedelsiant."}},"occupational-health-b1-18":{"question":"Ar vien vanduo gali pakenkti jūsų rankų odai darbe?","options":["Taip. Jei rankos ilgai šlapios, pvz., daugiau nei 2 valandas per pamainą, gali atsirasti dermatitas (dermatitis)","Ne. Odai gali pakenkti tik chemikalai","Ne. Vanduo odai visada naudingas","Tik jei vanduo labai karštas"],"explanation":"Dažnas sąlytis su vandeniu, ypač su muilu, gali sukelti dermatitą (dermatitis). HSE (darbo saugos tarnyba) pateikia pavyzdžių: rankos šlapios daugiau nei 2 valandas per pamainą arba daugiau nei 20 rankų plovimų. Dirbdami šlapią darbą mūvėkite neperšlampamas pirštines, gerai nusausinkite rankas ir naudokite drėkinamąjį kremą.","why_not":{"1":"Vanduo irgi gali pakenkti odai. Jei rankos šlapios daugiau nei 2 valandas per pamainą, gali atsirasti dermatitas (dermatitis).","2":"Dažnas sąlytis su vandeniu, ypač su muilu, gali sukelti dermatitą (dermatitis).","3":"Vanduo neturi būti karštas. Jei rankos ilgai šlapios, gali atsirasti dermatitas (dermatitis)."}},"occupational-health-b1-19":{"question":"Nuo tada, kai pradėjote maišyti skiedinį, jūsų rankų oda tapo sausa, niežti ir parausta. Ką turėtumėte daryti?","options":["Pranešti darbdaviui","Nekreipti dėmesio, nes statybininkams tai įprasta","Šveisti rankas stipriu tirpikliu, kad jos būtų švaresnės","Nebemūvėti pirštinių, kad oda galėtų kvėpuoti"],"explanation":"Sausa, niežtinti, parausta oda gali būti ankstyvas dermatito (dermatitis) požymis. Jei nieko nedaroma, oda gali pradėti luptis, trūkinėti, tinti ir pūslėti. HSE (darbo saugos tarnyba) sako pranešti darbdaviui, kuris gali jus nusiųsti pas darbo medicinos (occupational health) gydytoją ar slaugytoją. Nevalykite odos tirpikliais ir toliau mūvėkite tinkamas pirštines.","why_not":{"1":"Sausa, niežtinti, parausta oda gali būti ankstyvas dermatito (dermatitis) požymis. HSE (darbo saugos tarnyba) sako pranešti darbdaviui.","2":"HSE (darbo saugos tarnyba) sako nevalyti odos tirpikliais. Vietoj to praneškite apie bėrimą.","3":"Toliau mūvėkite tinkamas pirštines. Jas nusiėmus, ant odos patenka dar daugiau skiedinio."}},"occupational-health-b1-20":{"question":"Visą vasarą dirbate lauke, ir jūsų oda paruduoja. Ką, pasak HSE (darbo saugos tarnybos), reiškia įdegis?","options":["Jūsų odą pažeidė saulės UV spinduliai","Jūsų oda dabar apsaugota nuo saulės","Jums nebereikia prisidengti","Tai svarbu tik tada, jei oda pūslėja"],"explanation":"HSE (darbo saugos tarnyba) sako, kad įdegis yra ženklas, jog odą pažeidė saulės šviesos ultravioletiniai (UV) spinduliai. Net nedidelis paraudimas yra pažeidimo ženklas, o per daug saulės didina odos vėžio riziką. Nenusivilkite marškinėlių, dėvėkite kepurę, dengiančią ausis ir kaklą, naudokite kremą nuo saulės su didele apsaugos faktoriaus verte, darykite pertraukas pavėsyje ir tikrinkite, ar nesikeičia apgamai.","why_not":{"1":"Įdegis jūsų neapsaugo. HSE (darbo saugos tarnyba) sako, kad tai ženklas, jog oda jau pažeista.","2":"Prisidengti vis tiek reikia. Įdegis yra saulės padarytos žalos ženklas, o ne apsauga.","3":"Net įdegis ar nedidelis paraudimas yra pažeidimo ženklas, todėl tai svarbu dar prieš atsirandant pūslėms."}},"occupational-health-b1-21":{"question":"Bendradarbis pasako darbų vadovui (supervisor), kad turi problemų su alkoholiu, ir prašo pagalbos. Ko, pasak HSE (darbo saugos tarnybos), turėtų siekti gera narkotikų ir alkoholio politika?","options":["Padėti jam ir jį palaikyti, o ne atleisti iš darbo","Iš karto jį atleisti","Papasakoti apie jo problemą visai brigadai","Nekreipti dėmesio, nes tai jo asmeninis gyvenimas"],"explanation":"HSE (darbo saugos tarnyba) sako: kai darbuotojas pasako darbdaviui apie problemą su narkotikais ar alkoholiu, gera politika turėtų siekti jam padėti ir jį palaikyti, o ne baigtis atleidimu. Jei jo darbas svarbus saugai (safety-critical), pvz., vairavimas ar darbas su mašinomis, jį gali tekti kuriam laikui perkelti į kitą darbą. Politikoje taip pat turi būti aiškiai parašyta, kada bus taikomos drausminės priemonės.","why_not":{"1":"HSE (darbo saugos tarnyba) sako, kad gera politika turėtų siekti jam padėti ir jį palaikyti, o ne baigtis jo atleidimu.","2":"Papasakojus brigadai, jam nepadėsite. HSE (darbo saugos tarnyba) sako, kad tikslas – jam padėti ir jį palaikyti.","3":"Tai ne tik jo asmeninis reikalas. HSE (darbo saugos tarnyba) sako, kad gera politika turėtų siekti jam padėti ir jį palaikyti."}},"occupational-health-b1-22":{"question":"Jūsų įmonė tikrina dėl narkotikų ir alkoholio. Darbdavys turi rimtų priežasčių jus patikrinti, bet jūs atsisakote. Ką sako HSE (darbo saugos tarnyba)?","options":["Jūsų negali priversti atlikti testo, bet jums gali būti taikomos drausminės priemonės","Jus galima priversti atlikti testą jėga","Jei atsisakysite, jums nieko negali nutikti","Tik policija gali paprašyti jus atlikti testą darbe"],"explanation":"HSE (darbo saugos tarnyba) sako, kad darbuotojas turi sutikti (consent) su narkotikų ar alkoholio testu, todėl jūsų negalima priversti jo atlikti. Bet jei atsisakote, kai darbdavys turi rimtą pagrindą tikrinti, jums gali būti taikomos drausminės priemonės. Dažniausiai tikrinama darbuose, svarbiuose saugai (safety-critical), pvz., vairuojant ar valdant mašinas.","why_not":{"1":"HSE (darbo saugos tarnyba) sako, kad su testu turite sutikti (consent). Niekas negali jūsų priversti jo atlikti.","2":"Jei darbdavys turi rimtų priežasčių tikrinti, atsisakius jums gali būti taikomos drausminės priemonės.","3":"Darbdaviai gali tikrinti, jei jūs sutinkate. Paprašyti gali ne tik policija."}},"occupational-health-b1-23":{"question":"Jau kelias savaites blogai miegate, jaučiatės nervingi ir darbe sunku susikaupti. Ką pataria HSE (darbo saugos tarnyba)?","options":["Kuo greičiau su kuo nors pasikalbėti, pvz., su savo vadovu","Laikyti tai savyje, nes stresas yra silpnumo ženklas","Po darbo išgerti kelias taures, kad būtų lengviau","Palaukti, kol pasidarys labai blogai, ir tik tada ką nors sakyti"],"explanation":"Tai gali būti streso požymiai. HSE (darbo saugos tarnyba) sako, kad svarbu kuo greičiau su kuo nors pasikalbėti, pvz., su savo vadovu, kad jis galėtų padėti ir neleistų padėčiai pablogėti. Jei problema yra pats vadovas, galite pasikalbėti su profesinės sąjungos ar darbuotojų atstovu, personalo skyriumi (HR), konsultavimo tarnyba ar savo šeimos gydytoju (GP). Stresas nėra silpnumas, ir jis gali ištikti bet ką.","why_not":{"1":"Stresas nėra silpnumas. HSE (darbo saugos tarnyba) sako kuo greičiau su kuo nors pasikalbėti, pvz., su savo vadovu.","2":"Gėrimas streso neišsprendžia. HSE (darbo saugos tarnyba) sako kuo greičiau su kuo nors pasikalbėti, pvz., su savo vadovu.","3":"Laukiant padėtis gali pablogėti. HSE (darbo saugos tarnyba) sako kuo greičiau su kuo nors pasikalbėti."}},"occupational-health-b1-24":{"question":"Visą savaitę dirbote ilgas pamainas ir esate labai pavargę. Kaip šis nuovargis (fatigue) gali paveikti jus darbe?","options":["Reaguojate lėčiau ir galite nepastebėti, kaip kas nors pavojinga","Dėl jo tampate atsargesni, todėl esate saugesni","Jis svarbus tik biure dirbantiems žmonėms","Jis svarbus tik tada, jei vairuojate viešaisiais keliais"],"explanation":"Nuovargis (fatigue) reiškia, kad kūnas ir protas veikia prasčiau dėl ilgų darbo valandų, miego trūkumo ar blogai suplanuotų pamainų. HSE (darbo saugos tarnyba) sako, kad dėl jo lėčiau reaguojama, kas nors pamirštama, sunku sutelkti dėmesį ir rizika atrodo mažesnė, nei yra, o tai gali baigtis klaidomis ir nelaimingais atsitikimais. Jis dažnai būna pagrindinė didelių nelaimių priežastis.","why_not":{"1":"Nuovargis (fatigue) nepadaro jūsų saugesnių. Dėl jo lėčiau reaguojate ir neteisingai vertinate riziką.","2":"Nuovargis (fatigue) paveikia bet kokį darbą dirbančius žmones, taip pat ir statybvietėje, ne tik biure.","3":"Nuovargis (fatigue) svarbus bet kokiame darbe, ne tik vairuojant keliais. Statybvietėje jis gali sukelti klaidų ir nelaimingų atsitikimų."}},"occupational-health-b1-25":{"question":"Darbuotojas mielai dirba papildomas naktines pamainas, be savo įprastų valandų. Kas turi teisinę pareigą valdyti riziką, kad jis taps pavojingai pavargęs?","options":["Jo darbdavys, net jei jis pats nori papildomų valandų","Tik darbuotojas, nes jis pats taip pasirinko","Niekas, jei jam mokama už viršvalandžius","Užsakovas, kuriam priklauso statybvietė"],"explanation":"HSE (darbo saugos tarnyba) sako, kad teisinė pareiga valdyti nuovargio (fatigue) riziką tenka darbdaviui, kad ir kaip darbuotojas pats norėtų dirbti papildomas valandas. Vien laikytis Darbo laiko taisyklių (Working Time Regulations) neužtenka. Darbdavys turėtų nustatyti darbo valandų, viršvalandžių ir keitimosi pamainomis ribas. Naktį dirbantiems darbuotojams rizika didesnė, nes miegas dieną dažnai būna seklesnis ir trumpesnis.","why_not":{"1":"HSE (darbo saugos tarnyba) sako, kad teisinė pareiga tenka darbdaviui, net jei darbuotojas pats nori papildomų valandų.","2":"Apmokėjimas už viršvalandžius pareigos nepanaikina. Darbdavys turi valdyti nuovargio (fatigue) riziką.","3":"HSE (darbo saugos tarnyba) teisinę pareigą priskiria jo darbdaviui, o ne užsakovui."}},"occupational-health-b2-01":{"question":"Jūsų statybvietėje dirbanti moteris yra nėščia. Ką, pagal Statybos (projektavimo ir valdymo) taisykles (CDM 2015), turi apimti poilsio patalpos, kur to reikia?","options":["Tinkamą vietą, kur ji galėtų atsigulti pailsėti","Nieko papildomo. Ji naudojasi tomis pačiomis kėdėmis kaip ir visi","Vietą jos pačios automobilyje, kur ji galėtų pailsėti","Nieko. Jei jai reikia pailsėti, ji turi eiti namo"],"explanation":"Buitinių sąlygų taisyklės Statybos (projektavimo ir valdymo) taisyklėse (CDM 2015) sako, kad poilsio patalpose ar poilsio vietose, kur reikia, turi būti tinkamos sąlygos nėščiai ar krūtimi maitinančiai moteriai pailsėti gulint. Siųsti ją į automobilį ar namo – šio reikalavimo neatitinka.","why_not":{"1":"Paprastų kėdžių neužtenka. Kur reikia, jai turi būti tinkama vieta pailsėti gulint.","2":"Automobilis nėra poilsio patalpa. CDM 2015 sako, kad jai reikia tinkamos vietos atsigulti.","3":"Jai neturėtų tekti eiti namo. Statybvietėje jai turi būti vieta pailsėti gulint."}},"occupational-health-b2-03":{"question":"Pakėlėte nuo grindų plytelių dėžę. Ją reikia padėti ant darbastalio šone. Kaip turėtumėte pasisukti?","options":["Žingsniuodami kojomis pasukti visą kūną","Laikyti kojas vietoje ir pasisukti per liemenį","Pasilenkti į šoną ir numesti ją ant darbastalio","Greitai pasisukti, kad svorį laikytumėte trumpiau"],"explanation":"HSE (darbo saugos tarnyba) sako vengti sukti nugarą ar lenktis į šoną, ypač kai nugara sulenkta. Pečiai turi būti atsukti ta pačia kryptimi kaip klubai. Geriau pasisukti žingsniuojant kojomis, nei sukti liemenį keliant.","why_not":{"1":"HSE (darbo saugos tarnyba) sako vengti sukti nugarą. Vietoj to pasisukite žingsniuodami kojomis.","2":"HSE (darbo saugos tarnyba) sako vengti lenktis į šoną, ypač kai nugara sulenkta.","3":"Greitai sukant, nugara vis tiek apkraunama. Pasisukite žingsniuodami kojomis."}},"occupational-health-b2-04":{"question":"Nešate sunkią plokštę, kuri turi būti padėta tiksliai į vietą. Koks, pasak HSE (darbo saugos tarnybos), saugus būdas ją ten padėti?","options":["Pirmiausia ją padėti, tada pastumti į reikiamą vietą","Laikyti ją pakeltą ir kraipyti, kol bus reikiamoje vietoje","Numesti ją nuo juosmens aukščio ir koja įspirti į vietą","Laikyti ją ištiestomis rankomis, kad geriau matytumėte vietą"],"explanation":"HSE (darbo saugos tarnyba) pataria: pirma padėkite, tada pataisykite. Jei krovinys turi būti tiksliai tam tikroje vietoje, pirmiausia jį padėkite, tada pastumkite į vietą. Laikant sunkų krovinį ir jį judinant, nugara papildomai apkraunama.","why_not":{"1":"Laikant sunkų krovinį ir jį kraipant, apkraunama nugara. Pirmiausia padėkite, tada pataisykite.","2":"Numesti ir įspirti nesaugu. HSE (darbo saugos tarnyba) sako pirmiausia padėti, tada pastumti į vietą.","3":"Laikant krovinį ištiestomis rankomis, apkrova didesnė. Pirmiausia padėkite, tada pastumkite į vietą."}},"occupational-health-b2-06":{"question":"Dvi valymo priemonės atlieka tą patį darbą. Viena daug mažiau kenkia sveikatai nei kita. Ką, pagal pavojingų sveikatai medžiagų kontrolės taisykles (COSHH), darbdavys turėtų rinktis?","options":["Naudoti mažiau kenksmingą priemonę, jei tai pagrįstai įmanoma (reasonably practicable)","Naudoti stipresnę priemonę ir visiems duoti kaukes","Leisti kiekvienam darbuotojui rinktis, kurią nori","Naudoti pigesnę priemonę"],"explanation":"Pavojingų sveikatai medžiagų kontrolės taisyklės (COSHH) sako, kad pirmiausia reikia stengtis, kad žmonės visai nebūtų veikiami. Pakeisti kenksmingą medžiagą saugesne – tai vadinama pakeitimu (substitution) – yra pageidaujamas būdas tai padaryti, kai tai pagrįstai įmanoma (reasonably practicable). Kaukės ir kitos asmeninės apsaugos priemonės (PPE) yra paskutinė, o ne pirma priemonė.","why_not":{"1":"COSHH teikia pirmenybę saugesnei priemonei. Kaukės – paskutinė, o ne pirma priemonė.","2":"COSHH sako, kad darbdavys turėtų rinktis mažiau kenksmingą priemonę, o ne palikti tai kiekvienam darbuotojui.","3":"Kaina nėra taisyklė. COSHH teikia pirmenybę mažiau kenksmingai priemonei, kai tai pagrįstai įmanoma (reasonably practicable)."}},"occupational-health-b2-07":{"question":"Dėl medžiagų, su kuriomis dirbate, darbdavys liepia jums eiti sveikatos patikrinimų (health surveillance). Ką apie tai sako pavojingų sveikatai medžiagų kontrolės taisyklės (COSHH)?","options":["Turite eiti. Tai vyksta darbo laiku, ir moka darbdavys","Tai jūsų reikalas. Galite atsisakyti","Turite eiti, bet savo laisvu laiku","Turite eiti ir patys už tai sumokėti"],"explanation":"Pagal pavojingų sveikatai medžiagų kontrolės taisykles (COSHH) darbuotojas, kuriam reikia sveikatos patikrinimų (health surveillance), turi juose dalyvauti, kai darbdavys paprašo. Jie vyksta darbo laiku, ir už juos moka darbdavys. Šie patikrinimai gali aptikti ankstyvus žalos požymius, kol ji dar nepasunkėjo.","why_not":{"1":"COSHH sako, kad turite eiti, kai darbdavys paprašo. Tai ne jūsų pasirinkimas.","2":"Patikrinimai vyksta darbo laiku, o ne jūsų laisvu laiku.","3":"Už patikrinimus moka darbdavys, o ne jūs."}},"occupational-health-b2-08":{"question":"Jūsų brigada nori rūsyje paleisti benzininį generatorių šviestuvams maitinti. Kodėl, pasak HSE (darbo saugos tarnybos), tai taip pavojinga?","options":["Vos per kelias minutes jis gali pagaminti tiek anglies monoksido (carbon monoxide), kad užtektų užmušti","Tai pavojinga tik tada, jei užuodžiate išmetamąsias dujas","Pirmą valandą saugu, paskui išmetamosios dujos susikaupia","Vienintelis pavojus – kad jis per garsus"],"explanation":"Benzininiai varikliai išskiria anglies monoksidą (carbon monoxide) – nuodingas dujas, kurių negalima pamatyti, užuosti ar paragauti. HSE (darbo saugos tarnyba) sako, kad naudojant benzinines mašinas, pvz., generatorius ar pjovimo pjūklus, patalpose, uždarose erdvėse ar tranšėjose, pavojingas kiekis gali susidaryti net po kelių minučių. Generatorius laikykite lauke, kur išmetamąsias dujas gali išpūsti vėjas.","why_not":{"1":"Anglies monoksidas (carbon monoxide) neturi kvapo, todėl negalima pasikliauti uosle.","2":"Valandą tai nėra saugu. HSE (darbo saugos tarnyba) sako, kad mirtinas kiekis gali susidaryti net per kelias minutes.","3":"Triukšmas – ne vienintelis pavojus. Variklis išskiria anglies monoksidą (carbon monoxide), kuris gali užmušti."}},"occupational-health-b2-09":{"question":"Gręžiate betoną. Ore nematote jokių dulkių. Ar tai reiškia, kad nėra silicio dioksido dulkių (silica dust), kurių galėtumėte įkvėpti?","options":["Ne. Smulkiausių silicio dioksido dulkių įprastoje šviesoje nematyti","Taip. Jei dulkių nematote, oras švarus","Taip, jei grąžtas naujas","Ne, bet smulkios dulkės negali patekti į plaučius"],"explanation":"HSE (darbo saugos tarnyba) sako, kad smulkios silicio dioksido dulkės, kurios patenka giliai į plaučius (vadinamos respirable crystalline silica – įkvepiamasis kristalinis silicio dioksidas), yra per smulkios, kad jas matytumėte įprastoje šviesoje. Todėl švariai atrodantis oras neįrodo, kad saugu. Toliau naudokite dulkių kontrolės priemones.","why_not":{"1":"Švariai atrodantis oras nieko neįrodo. Smulkiausių silicio dioksido dulkių (silica dust) įprastoje šviesoje nematyti.","2":"Naujas grąžtas vis tiek sukelia silicio dioksido dulkių (silica dust), o smulkiausių jų nematyti.","3":"Būtent tokios smulkios silicio dioksido dulkės (silica dust) patenka giliai į plaučius."}},"occupational-health-b2-10":{"question":"Lauke, atvirame ore, pjaunate blokelius pjovimo pjūklu (cut-off saw). Bendradarbis sako, kad lauke dulkių kontrolės nereikia. Ką sako HSE (darbo saugos tarnyba)?","options":["Nemanykite, kad lauke dirbant galingais įrankiais dulkių mažai","Jis teisus. Lauke vėjas visada išpučia dulkes","Jis teisus, jei stovite prieš vėją","Dulkių kontrolės reikia tik patalpose be langų"],"explanation":"Uždarose erdvėse dulkių susikaupia daugiau, bet HSE (darbo saugos tarnyba) įspėja nemanyti, kad dulkių bus mažai dirbant lauke galingais įrankiais, pvz., pjovimo pjūklais (cut-off saws). Šie įrankiai labai greitai sukelia daug dulkių, todėl vis tiek reikia kontrolės priemonių, pvz., vandens ar dulkių nutraukimo (dust extraction).","why_not":{"1":"HSE (darbo saugos tarnyba) įspėja nemanyti, kad lauke, dirbant galingais įrankiais, dulkių mažai.","2":"Stovėti prieš vėją neužtenka. Galingi įrankiai greitai sukelia daug dulkių, todėl naudokite kontrolės priemones.","3":"Dirbant galingais įrankiais, pvz., pjovimo pjūklais (cut-off saws), dulkių kontrolės reikia ir lauke."}},"occupational-health-b2-11":{"question":"Jūsų įrankio dulkių nutraukimo (dust extraction) įrenginio atliekų maišas pilnas. Ką turėtumėte su juo daryti?","options":["Užsandarinti jį ir įmesti į tinkamą atliekų konteinerį","Ištuštinti jį į konteinerį ir įdėti tą patį maišą atgal","Iškratyti jį lauke, kad būtų galima vėl naudoti","Palikti jį įrenginyje iki darbų pabaigos"],"explanation":"HSE (darbo saugos tarnyba) sako reguliariai tuštinti dulkių nutraukimo įrenginį, naudojant tinkamus vienkartinius atliekų maišus. Užsandarinkite maišą ir įmeskite į tinkamą atliekų konteinerį. Netuštinkite maišų, kad naudotumėte juos vėl, nes taip dulkės vėl patenka į orą.","why_not":{"1":"HSE (darbo saugos tarnyba) sako netuštinti maišų, kad juos naudotumėte vėl. Užsandarinkite maišą ir tinkamai išmeskite.","2":"Iškračius maišą, dulkės vėl patenka į orą. HSE (darbo saugos tarnyba) sako šių maišų nenaudoti pakartotinai.","3":"HSE (darbo saugos tarnyba) sako įrenginį tuštinti reguliariai. Pilną maišą reikia užsandarinti ir įmesti į tinkamą konteinerį."}},"occupational-health-b2-12":{"question":"Triukšmingoje vietoje bendradarbis nešioja ausų kamštukus (earplugs), o ant jų – labai stiprias apsaugines ausines (ear defenders), todėl beveik nieko negirdi. Kokia čia problema?","options":["Per didelė apsauga gali trukdyti jam išgirsti įspėjimus ir kalbėtis su kitais","Jokios problemos. Daugiau apsaugos visada geriau","Vienintelė problema – kad tai atrodo juokingai","Tai problema tik tada, jei jis yra darbų vadovas"],"explanation":"HSE (darbo saugos tarnyba) sako, kad klausos apsaugos priemonės neturėtų sumažinti triukšmo prie ausies žemiau 70 dB. Per didelė apsauga gali trukdyti kalbėtis ir girdėti įspėjamuosius signalus, todėl žmonės gali atsiriboti nuo to, kas vyksta aplink. Jie taip pat gali nusiimti apsaugą ir rizikuoti savo klausa.","why_not":{"1":"Daugiau ne visada geriau. Dėl per didelės apsaugos jis gali neišgirsti įspėjimų.","2":"Problema – sauga, o ne išvaizda. Jis gali neišgirsti įspėjimų ar negalėti kalbėtis su kitais.","3":"Per didelė apsauga – problema bet kam, nes žmogus gali neišgirsti įspėjamųjų signalų."}},"occupational-health-b2-13":{"question":"Garsus triukšmas darbe pažeidė darbuotojo klausą. Ką HSE (darbo saugos tarnyba) sako apie tokį pažeidimą?","options":["Jis nuolatinis. Vaistų nėra, ir klausos aparatai negali visiškai jo kompensuoti","Klausa sugrįš po kelių savaičių be triukšmo","Su klausos aparatu jis girdės kaip naujas","Jį galima išgydyti ausų lašais"],"explanation":"HSE (darbo saugos tarnyba) sako, kad praradus klausą, ji nebesugrįžta, ir išgydyti neįmanoma. Klausos aparatai negali visiškai pakeisti natūralios klausos. Todėl klausą turite saugoti, kol ji dar nepažeista.","why_not":{"1":"HSE (darbo saugos tarnyba) sako, kad praradus klausą, ji nebesugrįžta.","2":"HSE (darbo saugos tarnyba) sako, kad klausos aparatai negali visiškai kompensuoti prarastos natūralios klausos.","3":"HSE (darbo saugos tarnyba) sako, kad dėl triukšmo prarastos klausos išgydyti neįmanoma."}},"occupational-health-b2-14":{"question":"Dažnai naudojate smūginį skaldymo plaktuką (hammer-action breaker) apie 2 valandas per dieną. Pagal paprastą HSE (darbo saugos tarnybos) vadovą, kokia jūsų rankų vibracijos rizika greičiausiai yra?","options":["Didelė rizika, greičiausiai viršijama poveikio ribinė vertė (exposure limit value)","Maža rizika, nes 2 valandos yra mažiau nei pusė pamainos","Jokios rizikos, jei mūvite storas pirštines","Vidutinė rizika, nes smūginiai įrankiai didelę riziką kelia tik po 4 valandų"],"explanation":"Paprastas HSE (darbo saugos tarnybos) vadovas sako, kad žmonėms gresia didelė rizika, viršijanti poveikio ribinę vertę (exposure limit value), jei jie reguliariai naudoja smūginius įrankius ilgiau nei maždaug valandą per dieną. Vidutinė rizika prasideda nuo maždaug 15 minučių per dieną. 4 valandų skaičius taikomas kai kuriems sukamiesiems ir kitiems įrankiams, ne smūginiams.","why_not":{"1":"HSE (darbo saugos tarnyba) sako, kad daugiau nei maždaug valanda per dieną su smūginiais įrankiais – didelė, o ne maža rizika.","2":"Pirštinės nuo vibracijos neapsaugo, todėl šios rizikos nesumažina.","3":"4 valandų skaičius taikomas kai kuriems sukamiesiems įrankiams. Smūginiai įrankiai kelia didelę riziką jau po maždaug valandos."}},"occupational-health-b2-15":{"question":"Jūsų pjovimo įrankio diskas nusidėvėjęs ir atšipęs, bet vis dar lėtai pjauna. Kodėl turėtumėte jį pakeisti?","options":["Atšipę įrankiai labiau vibruoja ir darbas užtrunka ilgiau, todėl gaunate daugiau vibracijos","Atšipęs diskas vibruoja mažiau, todėl iš tikrųjų yra saugesnis","Nesvarbu, jei tik įrankis dar veikia","Tik todėl, kad naujas diskas atrodo profesionaliau"],"explanation":"HSE (darbo saugos tarnyba) sako, kad atšipę, pažeisti ar prastai veikiantys įrankiai labiau vibruoja. Su jais darbas taip pat užtrunka ilgiau, todėl vibracija jus veikia ilgiau. Laikant pjovimo įrankius aštrius ir tvarkingus, rizika sumažėja.","why_not":{"1":"Yra atvirkščiai. HSE (darbo saugos tarnyba) sako, kad atšipę įrankiai vibruoja labiau, o ne mažiau.","2":"Atšipęs diskas labiau vibruoja ir darbas užtrunka ilgiau, todėl gaunate daugiau vibracijos.","3":"Tai ne išvaizdos reikalas. Atšipę įrankiai labiau vibruoja, ir darbas užtrunka ilgiau."}},"occupational-health-b2-17":{"question":"Bendradarbis sako: „Bet kokios storos guminės pirštinės apsaugos nuo bet kokios cheminės medžiagos, kiek ilgai tik nori.“ Ką sako HSE (darbo saugos tarnyba)?","options":["Jokios pirštinės neapsaugo nuo visų medžiagų, ir jokios pirštinės neapsaugo nuo medžiagos amžinai","Jis teisus. Storos pirštinės sulaiko visas chemines medžiagas","Jis teisus, jei pirštinės kas savaitę naujos","Pirštinių reikia tik stipriai kvepiančioms cheminėms medžiagoms"],"explanation":"HSE (darbo saugos tarnyba) sako, kad pirštinės skiriasi medžiaga ir storiu. Jokia pirštinių medžiaga neapsaugo nuo visų medžiagų, ir jokios pirštinės neapsaugo nuo tam tikros medžiagos amžinai. Tinkamos pirštinės priklauso nuo medžiagos, ir pirštines reikia laiku keisti.","why_not":{"1":"HSE (darbo saugos tarnyba) sako, kad jokia pirštinių medžiaga neapsaugo nuo visų medžiagų.","2":"Naujos pirštinės kas savaitę – ne taisyklė. Jokios pirštinės neapsaugo nuo medžiagos amžinai.","3":"Kvapas – ne matas. Tinkamos pirštinės priklauso nuo medžiagos, ir jokios neapsaugo amžinai."}},"occupational-health-b2-18":{"question":"Dėl darbo jūsų rankos išsausėja. Kada, pasak HSE (darbo saugos tarnybos), ypač naudinga naudoti drėkinamąjį kremą?","options":["Darbo dienos pabaigoje","Tik kartą per mėnesį","Tik kai oda jau suskilinėjusi ir kraujuoja","Niekada, nes kremas susilpnina odą"],"explanation":"HSE (darbo saugos tarnyba) pataria drėkinti odą kuo dažniau, ypač dienos pabaigoje. Tai sugrąžina natūralius riebalus, kurie palaiko odos apsauginį barjerą. Nelaukite, kol oda suskilinės.","why_not":{"1":"Kartą per mėnesį – gerokai per retai. HSE (darbo saugos tarnyba) sako drėkinti kuo dažniau.","2":"Nelaukite, kol oda suskilinės. Dažnai drėkinant, odos apsauginis barjeras veikia geriau.","3":"HSE (darbo saugos tarnyba) sako, kad drėkinti naudinga, nes taip sugrąžinami natūralūs riebalai, kurie saugo odą."}},"occupational-health-b2-19":{"question":"Daug dirbate lauke. Pastebite ant rankos apgamą, kuris didėja ir pradėjo niežėti. Ką pataria HSE (darbo saugos tarnyba)?","options":["Nedelsiant kreiptis į gydytoją","Palaukti metus ir pažiūrėti, ar praeis","Užklijuoti pleistru ir pamiršti","Daugiau jį pakaitinti saulėje, kad išdžiūtų"],"explanation":"Per daug saulės gali sukelti odos vėžį. HSE (darbo saugos tarnyba) sako reguliariai tikrinti odą, ar nėra neįprastų apgamų ar dėmių. Nedelsdami kreipkitės į gydytoją, jei kas nors keičia formą, dydį ar spalvą, niežti ar kraujuoja.","why_not":{"1":"Nelaukite. HSE (darbo saugos tarnyba) sako nedelsiant kreiptis į gydytoją, jei apgamas keičiasi ar niežti.","2":"Užklijavus nepadės. HSE (darbo saugos tarnyba) sako nedelsiant kreiptis į gydytoją dėl besikeičiančio apgamo.","3":"Nuo daugiau saulės bus tik blogiau. Per daug saulės gali sukelti odos vėžį."}},"occupational-health-b2-20":{"question":"Ką HSE (darbo saugos tarnyba) priskiria piktnaudžiavimui narkotikais ir alkoholiu?","options":["Nelegalius narkotikus, taip pat piktnaudžiavimą alkoholiu, vaistais ir medžiagomis, pvz., tirpikliais","Tik nelegalius narkotikus","Tik buvimą girtam darbe","Tik gatvėje perkamus narkotikus"],"explanation":"HSE (darbo saugos tarnyba) sako, kad piktnaudžiavimas narkotikais ir alkoholiu reiškia nelegalių narkotikų vartojimą, taip pat piktnaudžiavimą alkoholiu, vaistais ir medžiagomis, pvz., tirpikliais. Taigi piktnaudžiavimas vaistais ar tirpiklių uostymas irgi skaičiuojami, ne tik nelegalūs narkotikai.","why_not":{"1":"Ne tik nelegalūs narkotikai. Tai apima ir piktnaudžiavimą alkoholiu, vaistais ir tirpikliais.","2":"Ne tik buvimas girtam. Tai apima ir narkotikus, vaistus ir tirpiklius.","3":"Ne tik gatvėje perkami narkotikai. Piktnaudžiavimas vaistais ar tirpikliais irgi skaičiuojamas."}},"occupational-health-b2-21":{"question":"Bendradarbiui pastaruoju metu buvo keli beveik įvykę nelaimingi atsitikimai (near misses), ir jis vis neateina į darbą, nepaaiškindamas kodėl. HSE (darbo saugos tarnyba) sako, kad tai gali būti piktnaudžiavimo narkotikais ar alkoholiu įspėjamieji ženklai. Ką dar sako HSE?","options":["Tai taip pat gali būti kitų dalykų, pvz., streso ar ligos, ženklai","Tai visada įrodo, kad jis vartoja narkotikus","Tai svarbu tik tada, jei jis vairuotojas","Tai normalu, todėl nėra apie ką galvoti"],"explanation":"HSE (darbo saugos tarnyba) tokius dalykus kaip nepaaiškinamas neatvykimas į darbą ir dažnesni nelaimingi atsitikimai ar beveik įvykę nelaimingi atsitikimai (near misses) nurodo kaip galimus piktnaudžiavimo narkotikais ar alkoholiu įspėjamuosius ženklus. Bet ji taip pat sako, kad tai gali būti kitų dalykų, pvz., streso ar ligos, ženklai. Todėl nedarykite skubotų išvadų, bet ir nenumokite ranka.","why_not":{"1":"Jie nieko neįrodo. HSE (darbo saugos tarnyba) sako, kad tai gali būti ir streso ar ligos ženklai.","2":"Šie ženklai svarbūs bet kokiame darbe, ne tik vairuotojams.","3":"HSE (darbo saugos tarnyba) juos nurodo kaip įspėjamuosius ženklus, todėl jų negalima ignoruoti."}},"occupational-health-b2-22":{"question":"Ką HSE (darbo saugos tarnyba) sako apie stresą?","options":["Tai nėra liga, bet jis gali jus susargdinti","Tai liga, kuri paveikia tik silpnus žmones","Jis negali paveikti kūno, tik nuotaiką","Jo niekada nesukelia darbas"],"explanation":"HSE (darbo saugos tarnyba) sako, kad stresas nėra liga, bet jis gali jus susargdinti. Jis gali sukelti simptomų, kurie paveikia, kaip jaučiatės fiziškai ir psichiškai. Darbdaviai turi teisinę pareigą įvertinti su darbu susijusio streso riziką ir imtis veiksmų.","why_not":{"1":"Stresas nėra liga, ir tai nesusiję su silpnumu.","2":"HSE (darbo saugos tarnyba) sako, kad stresas gali paveikti ne tik nuotaiką, bet ir kūną.","3":"Darbas gali sukelti stresą. Darbdaviai turi įvertinti su darbu susijusio streso riziką."}},"occupational-health-b2-25":{"question":"Jūsų pamaina baigiasi 10 val. vakaro. Pagal Darbo laiko taisykles (Working Time Regulations), kiek mažiausiai poilsio turi teisę gauti suaugęs darbuotojas, prieš vėl pradėdamas dirbti?","options":["11 valandų iš eilės, taigi ne anksčiau kaip 9 val. ryto","6 valandas, taigi nuo 4 val. ryto","8 valandas, taigi nuo 6 val. ryto","Įstatyme mažiausias poilsio laikas nenustatytas"],"explanation":"Darbo laiko taisyklės (Working Time Regulations) suteikia suaugusiam darbuotojui teisę į bent 11 valandų nepertraukiamą poilsį per kiekvieną 24 valandų laikotarpį. Baigus 10 val. vakaro, poilsis trunka bent iki 9 val. ryto. Jauni darbuotojai turi teisę į 12 valandų. Įstatyme yra keletas ypatingų atvejų, bet tai yra įprasta taisyklė. Tinkamas poilsis tarp pamainų padeda išvengti pavojingo nuovargio.","why_not":{"1":"6 valandos – per mažai. Įstatymas suteikia bent 11 valandų poilsio iš eilės.","2":"8 valandos – per mažai. Įstatymas suteikia bent 11 valandų poilsio iš eilės.","3":"Mažiausias poilsio laikas nustatytas. Suaugę darbuotojai turi teisę į bent 11 valandų poilsio iš eilės."}},"occupational-health-b3-03":{"question":"Buitinis vagonėlis (welfare cabin) šildomas dujiniu (suskystintų dujų, LPG) šildytuvu. Bendradarbis prikimšo skudurų į vėdinimo angas, kad nepūstų skersvėjis. Ką turėtumėte daryti?","options":["Palikti skudurus, nes šiltas vagonėlis žiemą saugesnis","Ištraukti skudurus. Dėl užkimštų angų gali susikaupti mirtinai pavojingo anglies monoksido (carbon monoxide)","Stipriau įjungti šildytuvą, kad atsvertų skersvėjį","Kartą per valandą atidaryti vagonėlio duris, o angas palikti užkimštas"],"explanation":"HSE (darbo saugos tarnyba) sako, kad dujiniai šildytuvai ir viryklės, negaunantys pakankamai oro, gali išskirti anglies monoksido (carbon monoxide), kuris gali nužudyti. Nuolatinės vėdinimo angos turi būti laisvos net šaltu oru, kai žmonės dažnai jas užkemša skudurais ar laikraščiais. Ištraukite skudurus ir pasakykite darbų vadovui (supervisor). Retkarčiais atidarytos durys neatstoja tinkamo vėdinimo.","why_not":{"0":"Dėl užkimštų angų gali susikaupti anglies monoksido (carbon monoxide), kuris gali nužudyti. Šiluma to neverta.","2":"Stipriau įjungus šildytuvą, kai angos užkimštos, gali susidaryti dar daugiau anglies monoksido (carbon monoxide).","3":"Retkarčiais atidarytos durys nėra tinkamas vėdinimas. Angos turi likti laisvos."}},"occupational-health-b3-05":{"question":"Pakėlėte dėžę tvirtinimo detalių ir tvirtai ją laikote. Kur turėtumėte žiūrėti ją nešdami?","options":["Žemyn į dėžę, kad matytumėte, ar ji vis dar lygiai","Visą laiką į savo kojas","Per petį, kad patikrintumėte, kas už jūsų","Į priekį, pakelta galva"],"explanation":"HSE (darbo saugos tarnyba) sako nešant krovinį laikyti galvą pakeltą. Kai krovinį tvirtai laikote, žiūrėkite į priekį, o ne žemyn į krovinį. Žiūrint žemyn lenkiasi kaklas ir nugara, be to, nematote, kur einate.","why_not":{"0":"HSE (darbo saugos tarnyba) sako, kad tvirtai suėmę krovinį žiūrėtumėte į priekį, o ne žemyn į jį.","1":"Žiūrint žemyn lenkiasi kaklas ir nugara. Laikykite galvą pakeltą ir žiūrėkite į priekį.","2":"Žiūrint per petį, kūnas susisuka. Laikykite galvą pakeltą ir žiūrėkite į priekį."}},"occupational-health-b3-07":{"question":"Blokelių padėklai ir skiedinio maišai palikti lietuje neuždengti. Kodėl HSE (darbo saugos tarnyba) sako, kad medžiagas reikia laikyti sausai?","options":["Šlapios medžiagos gali tapti sunkesnės ir slidžios nešant","Šlapios medžiagos lengvesnės, todėl žmonės neša per daug iš karto","Tai svarbu tik tam, kaip atrodys baigta siena","Lietus krovinių rankiniam tvarkymui (manual handling) neturi jokios įtakos"],"explanation":"HSE (darbo saugos tarnyba) sako medžiagas laikyti sausai, kad jos netaptų sunkesnės ir slidžios, kai jas nešate. Permirkę blokeliai ir maišai sveria daugiau, nei tikitės, o šlapią paviršių sunkiau suimti, todėl lengviau persitempti ar išmesti krovinį.","why_not":{"1":"Yra atvirkščiai. Šlapios medžiagos tampa sunkesnės, o ne lengvesnės.","2":"Tai svarbu ir jūsų kūnui. Šlapios medžiagos tampa sunkesnės ir slidžios nešant.","3":"Lietus turi įtakos. Šlapios medžiagos sunkėja, ir jas sunkiau suimti."}},"occupational-health-b3-09":{"question":"Jūsų darbo kombinezonas (overalls) išteptas pavojinga medžiaga, kurią naudojote. Pietų metas. Ką, pagal pavojingų sveikatai medžiagų kontrolės taisykles (COSHH), su juo reikia daryti?","options":["Vilkėti jį valgykloje, o nusivilkti darbo pabaigoje","Nuvalyti jį šepečiu prie valgyklos ir tada eiti vidun","Parsinešti jį namo ir išskalbti su šeimos skalbiniais","Nusivilkti jį išeinant iš darbo vietos ir laikyti atskirai nuo švarių drabužių"],"explanation":"Pavojingų sveikatai medžiagų kontrolės taisyklės (COSHH) sako, kad apsauginius drabužius, kurie gali būti užteršti, reikia nusivilkti išeinant iš darbo vietos ir laikyti atskirai nuo švarių drabužių. Vilkint juos valgykloje ar parsinešus namo medžiaga patenka ten, kur valgote, ir pas kitus žmones. Darbdavys turi pasirūpinti, kad jie būtų išvalyti arba, jei reikia, išmesti.","why_not":{"0":"Nešvarų kombinezoną reikia nusivilkti išeinant iš darbo vietos, o ne vilkėti valgykloje.","1":"Nuvalyti šepečiu neužtenka. COSHH sako nusivilkti jį išeinant iš darbo vietos.","2":"Parsinešus jį namo, medžiaga patenka pas jūsų šeimą. Laikykite jį atskirai nuo švarių drabužių."}},"occupational-health-b3-10":{"question":"Prie naujo grindų hermetiko pridėtas saugos duomenų lapas (safety data sheet). Bendradarbis sako: „Tas lapas ir yra rizikos vertinimas, todėl daugiau nieko daryti nereikia.“ Ką sako HSE (darbo saugos tarnyba)?","options":["Jis teisus. Saugos duomenų lapas yra rizikos vertinimas","Ne. Saugos duomenų lapas nėra rizikos vertinimas (risk assessment), bet jis padeda jį parengti","Saugos duomenų lapai skirti tik ugniagesiams","Saugos duomenų lapų reikia tik gaminiams, parduodamiems gyventojams"],"explanation":"HSE (darbo saugos tarnyba) sako, kad saugos duomenų lapas (safety data sheet) nėra rizikos vertinimas. Jame nurodyti gaminio pavojai, kaip jį naudoti ir laikyti ir ką daryti avarijos atveju. Ši informacija padeda parengti rizikos vertinimą (risk assessment) konkrečiam darbui, kuriame vertinama, kaip, kur ir kiek laiko gaminys bus naudojamas.","why_not":{"0":"HSE (darbo saugos tarnyba) sako, kad saugos duomenų lapas (safety data sheet) nėra rizikos vertinimas.","2":"Saugos duomenų lapai (safety data sheets) skirti gaminį naudojantiems žmonėms, kad padėtų parengti rizikos vertinimą (risk assessment).","3":"Saugos duomenų lapai (safety data sheets) pridedami prie darbe naudojamų gaminių. Jie padeda parengti rizikos vertinimą (risk assessment)."}},"occupational-health-b3-11":{"question":"Tikrinate, ar ant chemikalų indo etiketės yra pavojaus ženklų. Kaip atrodo GB CLP pavojaus piktogramos (hazard pictograms)?","options":["Rombas su raudonu kraštu ir baltu fonu","Geltonas trikampis su juodu kraštu","Mėlynas apskritimas su baltu paveikslėliu","Žalias kvadratas su baltu paveikslėliu"],"explanation":"HSE (darbo saugos tarnyba) sako, kad GB CLP pavojaus piktogramos (hazard pictograms) yra rombo formos, su raudonu kraštu ir baltu fonu, o viduje – juodas simbolis. Jos įspėja, kad chemikalas gali pakenkti žmonėms ar aplinkai. Ant etiketės gali būti daugiau nei viena piktograma.","why_not":{"1":"CLP pavojaus piktogramos (hazard pictograms) yra rombai su raudonu kraštu ir baltu fonu, o ne geltoni trikampiai.","2":"CLP pavojaus piktogramos (hazard pictograms) yra rombai su raudonu kraštu ir baltu fonu, o ne mėlyni apskritimai.","3":"CLP pavojaus piktogramos (hazard pictograms) yra rombai su raudonu kraštu ir baltu fonu, o ne žali kvadratai."}},"occupational-health-b3-12":{"question":"Purškiate dažus su tirpikliais. Bendradarbis duoda jums dulkių kaukę su dalelių filtru. Ką apie tai sako HSE (darbo saugos tarnyba)?","options":["Viskas gerai, nes bet kokia kaukė sulaiko dažų garus","Viskas gerai, jei purškiate tik trumpai","Dalelių filtras sulaiko purškiamų dažų rūką, bet ne tirpiklių garus. Jums reikia tinkamo dujų ar garų filtro","Viskas gerai, jei purkšdami sulaikote kvėpavimą"],"explanation":"HSE (darbo saugos tarnyba) sako, kad dalelių filtrai apsaugo nuo purškiamų dažų rūko, bet neapsaugo nuo tirpiklių garų. Nuo garų reikia tinkamo dujų ar garų filtro, o filtrą reikia keisti tinkamais intervalais. Sandariai kaukei (tight-fitting mask) taip pat reikia priglundimo patikrinimo (face-fit test).","why_not":{"0":"Ne kiekviena kaukė sulaiko garus. Dalelių filtras tirpiklių garų nesulaiko.","1":"Trumpas laikas nepadeda. Pro dalelių filtrą tirpiklių garai vis tiek praeina.","3":"Sulaikytas kvėpavimas nėra apsauga. Jums reikia tinkamo dujų ar garų filtro."}},"occupational-health-b3-13":{"question":"Mažoje patalpoje uždarytomis durimis naudojote stiprius klijus su tirpikliais. Pradeda svaigti galva ir skauda galvą. Kokia labiausiai tikėtina priežastis ir kodėl tai svarbu?","options":["Esate alkanas, todėl tai neturi nieko bendra su darbu","Įkvėpėte tirpiklio garų. Jie gali jums pakenkti ir padidinti nelaimingo atsitikimo tikimybę","Kvapas nemalonus, bet sveikatai pakenkti negali","Nuovargis nuo ryto, todėl turėtumėte dirbti toliau iki pietų"],"explanation":"HSE (darbo saugos tarnyba) sako, kad net nedidelis tirpiklių kiekis gali sukelti galvos skausmą, pykinimą, galvos svaigimą ar apsvaigimą, o kai kurie iš šių poveikių gali padidinti nelaimingo atsitikimo tikimybę. Sustokite, išeikite į gryną orą ir pasakykite darbų vadovui (supervisor). HSE sako, kad dirbant su tirpikliais visada reikia vėdinimo, pvz., atidarytų durų ir langų, o pavojingesniam darbui – stipresnio vėdinimo.","why_not":{"0":"Galvos svaigimas ir skausmas – žinomas tirpiklių garų įkvėpimo poveikis, todėl greičiausiai kaltas darbas.","2":"HSE (darbo saugos tarnyba) sako, kad tirpiklių garai gali sukelti galvos skausmą ir svaigimą, todėl jie gali pakenkti sveikatai.","3":"Nedirbkite toliau. Dėl tirpiklių poveikio nelaimingas atsitikimas tampa labiau tikėtinas, todėl išeikite į gryną orą."}},"occupational-health-b3-14":{"question":"Per dieną tik retkarčiais supjaunate kelis blokelius, kiekvieną kartą apie minutę. Ar HSE (darbo saugos tarnyba) sako, kad toks trumpas dulkėtas darbas yra saugus?","options":["Taip. Dulkės kenkia tik tada, jei pjaunate valandų valandas be pertraukos","Taip, jei kiekvienas pjūvis trunka mažiau nei penkias minutes","Taip, jei paskui iškosėsite dulkes","Ne. Daug trumpų dulkėtų darbų vis tiek susideda ir ilgainiui gali jums pakenkti"],"explanation":"HSE (darbo saugos tarnyba) sako, kad statybose per dieną dažnai atliekama daug trumpų užduočių, ir jos vis tiek gali sukelti daug dulkių. Ilgainiui šios dulkės gali pakenkti plaučiams. Dulkes kontroliuokite kiekvieną kartą, kad per daugelį metų įkvėptų dulkių bendras kiekis nesikauptų.","why_not":{"0":"HSE (darbo saugos tarnyba) sako, kad trumpi dulkėti darbai per dieną ilgainiui vis tiek gali jums pakenkti.","1":"Trumpi pjūviai vis tiek sukelia daug dulkių, ir jos ilgainiui susideda.","2":"Kosint smulkios dulkės nepasišalina. Kontroliuokite dulkes kiekvieną kartą."}},"occupational-health-b3-17":{"question":"Ruošiatės išfrezuoti griovelį plytų sienoje vagų frezu (wall chaser) su dulkių nutraukimu prie įrankio. Kokį dulkių nutraukimo įrenginį (siurblį), pasak HSE (darbo saugos tarnybos), turėtumėte naudoti?","options":["L (Low, žemos) klasės įrenginį","Buitinį dulkių siurblį","H (High, aukštos) arba M (Medium, vidutinės) klasės įrenginį","Bet kokį siurblį, jei tik jis įjungtas"],"explanation":"HSE (darbo saugos tarnyba) sako statybinėms dulkėms rinktis H (High, aukštos) arba M (Medium, vidutinės) klasės dulkių nutraukimo įrenginį. L (Low, žemos) klasės įrenginys tinka tik mažiau kenksmingoms dulkėms, pvz., gipso kartono gipsui. Plytų dulkėse yra silicio dioksido (silica), todėl L klasės ar buitinio siurblio neužtenka.","why_not":{"0":"L klasės įrenginys tinka tik mažiau kenksmingoms dulkėms, pvz., gipso kartono. Plytų dulkėms reikia H arba M klasės.","1":"Buitinis dulkių siurblys nepagamintas statybinėms dulkėms. HSE (darbo saugos tarnyba) sako naudoti H arba M klasės įrenginį.","3":"Tinka ne bet koks siurblys. HSE (darbo saugos tarnyba) sako statybinėms dulkėms rinktis H arba M klasės įrenginį."}},"occupational-health-b3-18":{"question":"Praėjusiais metais sėkmingai atlikote sandarios kaukės priglundimo patikrinimą (face-fit test). Nuo to laiko labai sulieknėjote. Ką sako HSE (darbo saugos tarnyba)?","options":["Priglundimo patikrinimą reikėtų atlikti iš naujo","Niekas nesikeičia. Priglundimo patikrinimas galioja visam gyvenimui","Tiesiog stipriau priveržkite dirželius","Naujo priglundimo patikrinimo reikia tik pradėjus naują darbą"],"explanation":"HSE (darbo saugos tarnyba) sako, kad priglundimo patikrinimą (face-fit test) reikia atlikti iš naujo kaskart, kai pasikeičia kas nors, kas gali pakeisti, kaip kaukė priglunda prie veido. Vienas iš pavyzdžių – sulieknėjimas ar priaugtas svoris. Kiti – didelis dantų gydymas, veido auskarai ir pasikeitę kiti galvos apdangalai, kuriuos dėvite su kauke. Priveržti dirželiai blogo priglundimo neištaiso.","why_not":{"1":"Priglundimo patikrinimas (face-fit test) negalioja visam gyvenimui. Sulieknėjus ar priaugus svorio, jį reikia atlikti iš naujo.","2":"Priveržti dirželiai blogo priglundimo neištaiso. Jums reikia naujo priglundimo patikrinimo (face-fit test).","3":"Naujo priglundimo patikrinimo (face-fit test) reikia ir tada, kai pasikeičiate patys, pvz., sulieknėjate."}},"occupational-health-b3-19":{"question":"Po dienos šalia skaldymo plaktuko (breaker) girdite prislopintai. Kitą rytą klausa atrodo vėl normali. Ką, pasak HSE (darbo saugos tarnybos), tai reiškia?","options":["Nieko. Jei iki ryto praeina, problemos nėra","Tai reiškia, kad jūsų ausys priprato prie triukšmo","Tai svarbu tik tada, jei taip būna kasdien ištisus metus","Tai ženklas, kad su triukšmu reikia kažką daryti"],"explanation":"HSE (darbo saugos tarnyba) sako, kad prislopinta klausa dienos pabaigoje yra ženklas, kad su triukšmu reikia kažką daryti, net jei kitą rytą klausa atrodo geresnė. Triukšmo žala kaupiasi lėtai, ir galite to nepastebėti, kol bus per vėlu. Pasakykite darbdaviui apie bet kokias ausų ar klausos problemas.","why_not":{"0":"HSE (darbo saugos tarnyba) sako, kad prislopinta klausa yra įspėjamasis ženklas, net jei iki ryto pagerėja.","1":"Ausys prie triukšmo nepripranta. Prislopinta klausa – ženklas, kad yra triukšmo problema.","2":"Nelaukite. Triukšmo žala kaupiasi lėtai, o prislopinta klausa jau dabar yra įspėjimas."}},"occupational-health-b3-20":{"question":"HSE (darbo saugos tarnyba) pateikia paprastų ženklų, kad darbdavys turėtų kažką daryti su triukšmu. Kuris iš šių yra vienas iš jų?","options":["Statybvietės vagonėlyje girdite grojantį radiją","Triukšmingais elektriniais įrankiais ar mašinomis dirbate daugiau nei pusvalandį per dieną","Galite normaliai kalbėtis su šalia stovinčiu žmogumi","Dirbate lauke, o ne pastato viduje"],"explanation":"HSE (darbo saugos tarnyba) sako, kad iš darbdavio būtų tikimasi kažką daryti su triukšmu, jei, pavyzdžiui, triukšmingais elektriniais įrankiais ar mašinomis dirbate daugiau nei pusvalandį per dieną. Darbas lauke nepadaro triukšmo saugaus, o galimybė normaliai kalbėtis su šalia esančiu žmogumi nėra įspėjamasis ženklas.","why_not":{"0":"Girdimas radijas nėra vienas iš HSE (darbo saugos tarnybos) įspėjamųjų ženklų dėl triukšmo.","2":"Galimybė normaliai kalbėtis su šalia esančiu žmogumi nėra įspėjamasis ženklas. Ženklas būtų, jei tektų kelti balsą.","3":"Darbas lauke nepadaro triukšmo saugaus, ir tai nėra vienas iš HSE (darbo saugos tarnybos) įspėjamųjų ženklų."}},"occupational-health-b3-22":{"question":"Jūsų dienos triukšmo poveikis yra tarp apatinio ir viršutinio poveikio veiksmų lygių (exposure action values). Ką, pagal įstatymą, darbdavys turi daryti dėl klausos apsaugos priemonių?","options":["Duoti jums klausos apsaugos priemones, jei jų paprašysite","Nieko, kol triukšmas neviršys viršutinio veiksmų lygio","Liepti jums dėvėti ausų kamštukus ir apsaugines ausines kartu","Perkelti jus į kitą statybvietę"],"explanation":"HSE (darbo saugos tarnyba) sako, kad kai jūsų triukšmo poveikis yra tarp apatinio ir viršutinio poveikio veiksmų lygių (exposure action values), darbdavys turi duoti jums klausos apsaugos priemones, jei jų paprašysite. Viršijus viršutinį veiksmų lygį (upper exposure action value), darbdavys turi jas duoti ir užtikrinti, kad jos būtų tinkamai naudojamos.","why_not":{"1":"Kai poveikis tarp dviejų lygių, darbdavys turi duoti jums klausos apsaugos priemones, jei jų paprašysite.","2":"Įstatymas čia nesako dėvėti abiejų kartu. Klausos apsaugos priemones gaunate, jei jų paprašote.","3":"Įstatymas nesako jus perkelti. Kai poveikis tarp dviejų lygių, klausos apsaugos priemones gaunate, jei jų paprašote."}},"occupational-health-b3-23":{"question":"Po ilgų metų triukšmingo darbo darbuotojui dažnai spengia ausyse, net kai tylu. Ką apie tai sako HSE (darbo saugos tarnyba)?","options":["Tai ženklas, kad jo ausys užsigrūdino","Tai visada praeina po savaitės atostogų","Tai vadinama spengimu ausyse (tinnitus), ir jis gali likti visam laikui","Taip nutinka tik tiems, kurie klausosi garsios muzikos"],"explanation":"HSE (darbo saugos tarnyba) sako, kad stiprus triukšmas gali sukelti spengimą ausyse (tinnitus), kuris gali likti visam laikui. Triukšmo pažeista klausa nepagerėja, ir vaistų nuo to nėra. Saugokite klausą ir pasakykite darbdaviui, jei pastebite spengimą ar prislopintą klausą.","why_not":{"0":"Ausys neužsigrūdina. Spengimas ausyse – tai tinitas (tinnitus), triukšmo padarytos žalos ženklas.","1":"Jis ne visada praeina. HSE (darbo saugos tarnyba) sako, kad spengimas ausyse (tinnitus) gali likti visam laikui.","3":"Spengimą ausyse (tinnitus) gali sukelti ir triukšmas darbe, ne tik garsi muzika."}},"occupational-health-b3-25":{"question":"HSE (darbo saugos tarnyba) pateikia apytikslį orientyrą, kiek laiko galima dirbti smūginiu įrankiu, pvz., skaldymo plaktuku (breaker), kol greičiausiai viršysite poveikio veiksmų vertę (exposure action value). Maždaug kiek laiko per dieną?","options":["Maždaug 4 valandas per dieną","Maždaug 8 valandas per dieną","Laiko orientyro nėra, tik svorio","Maždaug 15 minučių per dieną"],"explanation":"HSE (darbo saugos tarnyba) sako, kad jums ypač gresia pavojus, jei reguliariai dirbate smūginiais įrankiais ilgiau nei maždaug 15 minučių per dieną, nes tada greičiausiai viršijate taisyklėse nustatytą poveikio veiksmų vertę (exposure action value). Kai kuriems sukamiesiems įrankiams orientyras – maždaug valanda per dieną. Viršijus veiksmų vertę, darbdavys turi imtis veiksmų rizikai sumažinti.","why_not":{"0":"4 valandos – gerokai per ilgai. Smūginiams įrankiams HSE (darbo saugos tarnyba) nurodo maždaug 15 minučių per dieną.","1":"8 valandos – gerokai per ilgai. Smūginiams įrankiams HSE (darbo saugos tarnyba) nurodo maždaug 15 minučių per dieną.","2":"HSE (darbo saugos tarnyba) pateikia laiko orientyrą: smūginiams įrankiams – maždaug 15 minučių per dieną."}},"occupational-health-b3-28":{"question":"Patys elektrinio įrankio nelaikote. Vietoj to spaudžiate metalines detales prie pritvirtinto stacionaraus šlifuoklio (pedestal grinder). Ar jums gresia rankų vibracijos pavojus?","options":["Taip. Laikant vibruojančią detalę prie mašinos jums taip pat gresia pavojus","Ne. Pavojus gresia tik tiems, kurie laiko įrankį","Ne, nes šlifuoklis prisuktas varžtais","Tik jei šlifuoklis veikia su akumuliatoriumi"],"explanation":"HSE (darbo saugos tarnyba) sako, kad jums taip pat gresia pavojus, jei laikote detales, kurios vibruoja, kol jas apdoroja elektrinė mašina, pvz., stacionarus šlifuoklis (pedestal grinder). Vibracija vis tiek pereina į jūsų rankas ir dilbius, nors įrankio nelaikote.","why_not":{"1":"HSE (darbo saugos tarnyba) sako, kad laikant vibruojančią detalę prie mašinos jums taip pat gresia pavojus.","2":"Tai, kad šlifuoklis prisuktas varžtais, nepadeda. Vibracija per detalę vis tiek pereina į jūsų rankas.","3":"Akumuliatorius nieko nekeičia. Laikant vibruojančią detalę, jums gresia pavojus."}},"occupational-health-b3-29":{"question":"Ruošiatės užsimauti pirštines darbui su medžiaga, kuri gali pakenkti odai. Ką, pasak HSE (darbo saugos tarnybos), turėtumėte padaryti pirmiausia?","options":["Įtrinti šiek tiek medžiagos į rankas, kad ją išbandytumėte","Užsimauti pirštines ant nešvarių rankų, kad sutaupytumėte laiko","Sušlapinti rankas, kad pirštinės lengviau užsimautų","Nusiplauti rankas"],"explanation":"HSE (darbo saugos tarnyba) sako plauti rankas prieš valgant ir geriant ir prieš užsimaunant pirštines. Užsimovus pirštines ant nešvarių rankų, visi nešvarumai ar chemikalai lieka prie odos, ir pirštinės juos ten laiko. Paskui taip pat gerai nusausinkite rankas.","why_not":{"0":"Niekada netepkite kenksmingos medžiagos ant odos. Prieš užsimaudami pirštines nusiplaukite rankas.","1":"Užsimovus pirštines ant nešvarių rankų, nešvarumai ar chemikalai lieka uždaryti prie odos.","2":"Gerai nusiplaukite ir nusausinkite rankas. HSE (darbo saugos tarnyba) sako jas nusiplauti prieš užsimaunant pirštines."}},"occupational-health-b3-30":{"question":"Dienos pabaigoje ant rankų turite blizgių dažų. Bendradarbis paduoda skiedikliu (thinners) suvilgytą skudurą jiems nuvalyti. Ką sako HSE (darbo saugos tarnyba)?","options":["Naudokite skiediklį. Tai greičiausias būdas nuvalyti dažus nuo odos","Nevalykite odos tirpikliais ar stipriais valikliais","Skiediklis tinka, jei paskui nuplausite rankas šaltu vandeniu","Palikite dažus, kad patys nusitrintų"],"explanation":"HSE (darbo saugos tarnyba) sako nevalyti odos agresyviais valikliais ar tirpikliais. Tirpikliai, pvz., skiediklis (thinners), pašalina natūralius odos riebalus ir gali sukelti dermatitą (dermatitis). Bet kokius nešvarumus nedelsdami nuplaukite tinkamu odos valikliu ir vandeniu, tada gerai nusausinkite rankas.","why_not":{"0":"HSE (darbo saugos tarnyba) sako nevalyti odos tirpikliais. Jie gali sukelti dermatitą (dermatitis).","2":"Nuplovus paskui, saugiau netampa. HSE (darbo saugos tarnyba) sako nenaudoti tirpiklių odai valyti.","3":"Dažus nedelsdami nuplaukite tinkamu odos valikliu ir vandeniu. Nepalikite jų ant odos."}},"occupational-health-b3-31":{"question":"Vasarą dirbate ant stogo. Kokio stiprumo apsaugos nuo saulės kremą, pasak HSE (darbo saugos tarnybos), turėtumėte tepti ant bet kokios neuždengtos odos?","options":["Aukšto apsaugos faktoriaus kremą, bent SPF30","Bet kokį kremą, net SPF5","Jokio, jei jau esate įdegę","Apsaugos nuo saulės kremas reikalingas tik paplūdimyje"],"explanation":"HSE (darbo saugos tarnyba) sako ant bet kokios neuždengtos odos tepti aukšto apsaugos faktoriaus kremą, bent SPF30. Taip pat nenusivilkite marškinėlių, dėvėkite kepurę, dengiančią ausis ir kaklą, o per pertraukas būkite pavėsyje. Įdegis jūsų neapsaugo: tai ženklas, kad oda jau pažeista.","why_not":{"1":"SPF5 – per silpnas. HSE (darbo saugos tarnyba) sako naudoti bent SPF30.","2":"Įdegis jūsų neapsaugo. Tai ženklas, kad oda jau pažeista.","3":"Apsaugos nuo saulės kremo reikia ir darbe. HSE (darbo saugos tarnyba) sako ant neuždengtos odos tepti SPF30 ar stipresnį."}},"occupational-health-b3-34":{"question":"Teleskopinio krautuvo (telehandler) vairuotojas prašo darbdavio pagalbos dėl narkotikų problemos. Kas, pasak HSE (darbo saugos tarnybos), gali būti būtina, kol jis gauna pagalbą?","options":["Jis toliau vairuoja kaip įprasta, kad niekas nesužinotų","Jį reikia atleisti, nes jo darbas svarbus saugai","Jis gali toliau vairuoti, jei bendradarbis jį stebi","Jį gali tekti perkelti į kitą darbą, bent kuriam laikui"],"explanation":"HSE (darbo saugos tarnyba) sako, kad kai darbuotojas, kurio darbas svarbus saugai (safety-critical), pvz., vairuotojas ar kėlimo įrangos operatorius, prašo pagalbos dėl narkotikų ar alkoholio vartojimo, gali tekti jį perkelti į kitą darbą, bent kuriam laikui. Tai apsaugo jį ir visus aplinkinius, kol jis gauna pagalbą.","why_not":{"0":"Vairuodamas kaip įprasta, jis gali kelti pavojų sau ir kitiems. Jį gali tekti kuriam laikui perkelti į kitą darbą.","1":"HSE (darbo saugos tarnyba) nesako, kad jį reikia atleisti. Jį gali tekti kuriam laikui perkelti į kitą darbą.","2":"Stebėjimo neužtenka. HSE (darbo saugos tarnyba) sako, kad jį gali tekti kuriam laikui perkelti į kitą darbą."}},"occupational-health-b3-35":{"question":"Statybvietės vadovas žino, kad kai kurie darbuotojai per pietus statybvietės aikštelėje rūko kanapes. Jis nusprendžia apsimesti, kad nemato. Ką sako įstatymas?","options":["Tai ne jo problema, nes tai jų pertraukos laikas","Tai nusikaltimas tik tada, jei jis pats irgi rūko","Sąmoningai tai leisdamas, jis gali daryti nusikaltimą","Statybvietėje tai leidžiama, bet ne biure"],"explanation":"Pagal Narkotikų piktnaudžiavimo įstatymą (Misuse of Drugs Act 1971), asmuo, valdantis patalpas ar teritoriją, daro nusikaltimą, jei sąmoningai leidžia ten tam tikrą veiklą su narkotikais, pvz., rūkyti kanapes ar platinti narkotikus. Žinoti ir nieko nedaryti gali būti laikoma leidimu. Jis turi tuo pasirūpinti ir laikytis įmonės narkotikų ir alkoholio politikos.","why_not":{"0":"Pertraukos laikas nesvarbus. Sąmoningai tai leisdamas statybvietėje, jis gali daryti nusikaltimą.","1":"Jam pačiam nebūtina rūkyti. Sąmoningai tai leidžiant, galima daryti nusikaltimą.","3":"Tai neleidžiama jokiose patalpose ar teritorijoje. Sąmoningai tai leidžiant, galima daryti nusikaltimą."}},"occupational-health-b3-37":{"question":"Ką, pasak HSE (darbo saugos tarnybos), darbdavys turi daryti dėl streso darbe?","options":["Įvertinti streso darbe keliamą riziką jūsų sveikatai ir supažindinti jus su rezultatais","Nieko. Stresas yra asmeninis reikalas","Imtis veiksmų tik tada, jei turite gydytojo pažymą","Kiekvieną mėnesį visiems duoti laisvą dieną"],"explanation":"HSE (darbo saugos tarnyba) sako, kad darbdavys turi teisinę pareigą įvertinti streso darbe keliamą riziką jūsų sveikatai ir supažindinti jus su rizikos vertinimo (risk assessment) rezultatais. Daug darbdavių naudoja HSE valdymo standartus (Management Standards), kad rastų ir valdytų pagrindines streso priežastis.","why_not":{"1":"Stresas darbe nėra tik asmeninis reikalas. Darbdavys turi teisinę pareigą įvertinti riziką.","2":"Gydytojo pažymos nereikia. Darbdavys bet kokiu atveju turi įvertinti streso darbe riziką.","3":"Laisva diena kas mėnesį nėra pareiga. Darbdavys turi įvertinti riziką ir supažindinti jus su rezultatais."}},"occupational-health-b3-38":{"question":"HSE (darbo saugos tarnyba) tyrė, kada darbe dažniau įvyksta nelaimingi atsitikimai ir traumos. Kurį iš šių teiginių ji pateikia?","options":["Jų daugiau tik pirmą dieną grįžus po atostogų","Jų mažiau, kai pamainos ilgos, nes žmonės įsivažiuoja","Pamainų grafikas nelaimingiems atsitikimams neturi įtakos","Jų daugiau per naktines pamainas ir po kelių pamainų iš eilės"],"explanation":"HSE (darbo saugos tarnyba) sako, kad nelaimingų atsitikimų ir traumų nustatyta daugiau per naktines pamainas, po kelių pamainų iš eilės, kai pamainos ilgos ir kai trūksta pertraukų. Nuovargis (fatigue) kaupiasi, todėl ilgas ar viena po kitos einančias pamainas reikia planuoti atsižvelgiant į poilsį.","why_not":{"0":"HSE (darbo saugos tarnyba) to nesako. Ji sako, kad nelaimingų atsitikimų daugiau per naktines pamainas ir po kelių pamainų iš eilės.","1":"Yra atvirkščiai. HSE (darbo saugos tarnyba) sako, kad kai pamainos ilgos, nelaimingų atsitikimų daugiau.","2":"Pamainų grafikas turi įtakos. Nelaimingų atsitikimų daugiau per naktines pamainas ir po kelių pamainų iš eilės."}},"occupational-health-b3-39":{"question":"Pradedate kelias naktines pamainas iš eilės. Kodėl, pasak HSE (darbo saugos tarnybos), naktį dirbantiems ypač gresia nuovargis (fatigue)?","options":["Naktį darbo visada mažiau, todėl žmonėms nuobodu","Miegas dieną dažnai būna lengvesnis, trumpesnis ir lengviau sutrikdomas","Naktį šalčiau, todėl žmonės pavargsta","Naktį dirbantys visada dirba ilgiau nei dirbantys dieną"],"explanation":"HSE (darbo saugos tarnyba) sako, kad naktį dirbantiems ypač gresia nuovargis (fatigue), nes miegas dieną dažnai būna lengvesnis, trumpesnis ir lengviau sutrikdomas dėl dienos triukšmo ir dėl to, kad kūnas natūraliai nenori miegoti šviesiu paros metu. Ilgainiui susikaupia „miego skola“ (sleep debt). Planuokite tinkamą poilsį tarp pamainų.","why_not":{"0":"HSE (darbo saugos tarnyba) nurodo ne nuobodulį. Miegas dieną dažnai būna lengvesnis, trumpesnis ir lengviau sutrikdomas.","2":"HSE (darbo saugos tarnyba) nurodo ne šaltį. Miegas dieną dažnai būna lengvesnis, trumpesnis ir lengviau sutrikdomas.","3":"HSE (darbo saugos tarnyba) nurodo ne ilgesnes valandas. Miegas dieną dažnai būna lengvesnis, trumpesnis ir lengviau sutrikdomas."}},"occupational-health-b3-40":{"question":"Kokia, pagal Darbo laiko taisykles (Working Time Regulations), yra įprasta suaugusio darbuotojo vidutinio savaitės darbo laiko riba, įskaitant viršvalandžius?","options":["Vidutiniškai 48 valandos per savaitę, nebent raštu sutikote dirbti daugiau","Vidutiniškai 40 valandų per savaitę, be galimybės dirbti daugiau","Vidutiniškai 60 valandų per savaitę","Ribos nėra, jei jums mokama už viršvalandžius"],"explanation":"Darbo laiko taisyklės (Working Time Regulations) sako, kad darbuotojo darbo laikas, įskaitant viršvalandžius, negali viršyti vidutiniškai 48 valandų per kiekvienas 7 dienas, skaičiuojant per nustatytą laikotarpį. Ši riba netaikoma, jei darbdavys iš anksto gavo jūsų rašytinį sutikimą dirbti daugiau.","why_not":{"1":"Riba yra vidutiniškai 48 valandos, o ne 40, ir raštu galite sutikti dirbti daugiau.","2":"60 valandų – per daug. Riba yra vidutiniškai 48 valandos per savaitę.","3":"Apmokėjimas už viršvalandžius ribos nepanaikina. Viršvalandžiai įskaičiuojami į 48 valandų vidurkį."}},"safety-b1-01":{"question":"Rizikos vertinime (risk assessment) parašyta, kad gręžiant reikia dėvėti apsauginius akinius. Jums reikia išgręžti tik dvi skyles, tai užtruks vieną minutę. Ką darote?","options":["Gręžiate be jų: darbas per trumpas, kad tai būtų svarbu","Prieš pradėdami užsidedate apsauginius akinius","Laikote galvą atitraukę, toliau nuo gręžtuvo","Užsidedate juos tik tada, jei pradeda lėkti dulkės"],"explanation":"Jei rizikos vertinime (risk assessment) parašyta, kad darbui reikia asmeninių apsaugos priemonių (PPE), jas dėvite kiekvieną kartą, net jei darbas labai trumpas. Plytos ar metalo skeveldra gali pataikyti į akį greičiau nei per sekundę. Atitraukta galva ar laukimas, ar pradės lėkti dulkės, akių neapsaugo.","why_not":{"0":"Jei rizikos vertinime (risk assessment) parašyta, kad reikia asmeninių apsaugos priemonių (PPE), jas dėvite kiekvieną kartą, net vienos minutės darbui.","2":"Atitraukta galva akių neapsaugo, nes skeveldra vis tiek gali į jas pataikyti.","3":"Skeveldra gali pataikyti į akį greičiau nei per sekundę, todėl akinius užsidėkite prieš pradėdami."}},"safety-b1-03":{"question":"Jums duotas darbo kombinezonas (coveralls) yra gerokai per didelis. Rankovės nukaba ant plaštakų. Ką turėtumėte daryti?","options":["Peiliu patrumpinti rankoves","Atraitoti rankoves ir apvynioti lipnia juosta","Paprašyti jūsų dydžio kombinezono","Dėvėti tokį, koks yra: laisvame vėsiau"],"explanation":"Asmeninės apsaugos priemonės (PPE) turi tikti jas dėvinčiam žmogui. Patiems jas perdaryti, kad tiktų, – ne išeitis. Ilgos, laisvos rankovės gali įsivelti į besisukantį gręžtuvą ar mašiną ir įtraukti ranką. Paprašykite tinkamo dydžio.","why_not":{"0":"Patiems perdaryti asmenines apsaugos priemones (PPE), kad tiktų, – ne išeitis, todėl paprašykite tinkamo dydžio.","1":"Atraitoti ir apvynioti juosta – vis tiek perdaryti patiems, todėl paprašykite jūsų dydžio kombinezono.","3":"Laisvos, ilgos rankovės gali įsivelti į besisukančią mašiną ir įtraukti ranką."}},"safety-b1-05":{"question":"Pagal įstatymą sikhas darbuotojas, dėvintis turbaną, neprivalo dėvėti šalmo (hard hat). O kaip su kitomis asmeninėmis apsaugos priemonėmis (PPE), kurių reikia jo darbui, pvz., apsauginiais batais ir ryškiaspalviais drabužiais (hi-vis)?","options":["Jam nereikia ir jokių kitų PPE","Jų reikia tik tada, jei jis lankytojas","Jis gali pats rinktis, ar jas dėvėti","Jis vis tiek privalo jas dėvėti"],"explanation":"Išimtis galioja tik galvos apsaugai. Turbaną dėvintis sikhas vis tiek privalo dėvėti visas kitas darbui reikalingas asmenines apsaugos priemones (PPE), pvz., apsauginius batus, pirštines, akių apsaugą ir ryškiaspalvius drabužius (hi-vis). Tai galioja vienodai – ar jis dirba statybvietėje, ar ją lanko.","why_not":{"0":"Išimtis galioja tik galvos apsaugai, todėl jis vis tiek privalo dėvėti visas kitas darbui reikalingas asmenines apsaugos priemones (PPE).","1":"Ar jis ten dirba, ar lankosi, kitas asmenines apsaugos priemones (PPE) jis vis tiek privalo dėvėti.","2":"Tai ne jo pasirinkimas: atleidžiama tik nuo šalmo (hard hat), o kitas asmenines apsaugos priemones (PPE) vis tiek reikia dėvėti."}},"safety-b1-06":{"question":"Ruošiatės įjungti elektrinį įrankį į kištukinį srovės nuotėkio jungiklį (RCD). Ką turėtumėte padaryti pirmiausia?","options":["Nieko: jis buvo patikrintas gamykloje","Užklijuoti jo mygtuką lipnia juosta, kad jis netyčia neišsijungtų","Paspausti jo bandymo mygtuką (test) ir patikrinti, ar jis išsijungia","Išimti RCD ir įjungti įrankį tiesiai į sieninį lizdą"],"explanation":"Srovės nuotėkio jungiklis (RCD) gali išgelbėti gyvybę, labai greitai nutraukdamas srovę, kai yra gedimas. Bet ir pats RCD gali būti sugedęs. HSE (darbo saugos tarnyba) sako, kad juo besinaudojantis žmogus prieš naudojimą turi paspausti bandymo mygtuką. Jei jis neišsijungia, jo nenaudokite: jis turi būti pažymėtas kaip sugedęs arba išneštas.","why_not":{"0":"Srovės nuotėkio jungiklis (RCD) irgi gali būti sugedęs, todėl HSE (darbo saugos tarnyba) sako prieš kiekvieną naudojimą paspausti jo bandymo mygtuką.","1":"Užklijavus mygtuką, srovės nuotėkio jungiklis (RCD) negali atlikti savo darbo, todėl paspauskite bandymo mygtuką ir patikrinkite, ar jis išsijungia.","3":"Išėmus srovės nuotėkio jungiklį (RCD), nelieka to, kas jus saugo nuo elektros smūgio, todėl verčiau jį patikrinkite."}},"safety-b1-07":{"question":"Jūsų gręžtuvas pradeda rūkti ir kvepėti degėsiais. Jūs jį išjungiate ir ištraukiate kištuką. Kas turi būti daroma toliau?","options":["Nebenaudoti jo, pažymėti užrašu „DO NOT USE“ (nenaudoti) ir atiduoti patikrinti","Leisti jam atvėsti, tada dirbti toliau","Patiems jį išardyti ir ieškoti gedimo","Padėti atgal į sandėlį, kad naudotų kas nors kitas"],"explanation":"Dūmai ir degėsių kvapas reiškia, kad gręžtuvas sugedęs. Jis gali kam nors trenkti elektra arba sukelti gaisrą. Nebenaudokite jo, pažymėkite užrašu „DO NOT USE“ (nenaudoti) ir laikykite atokiau nuo kitų, kol jį patikrins kompetentingas asmuo (competent person). Nebandykite jo taisyti patys.","why_not":{"1":"Atvėsus gedimas nedingsta, o sugedęs gręžtuvas gali kam nors trenkti elektra ar sukelti gaisrą.","2":"Neieškokite ir netaisykite gedimo patys, nes jį turi patikrinti kompetentingas asmuo (competent person).","3":"Padėjus jį atgal, sugedusiu įrankiu gali pasinaudoti kas nors kitas, todėl pažymėkite jį užrašu „DO NOT USE“ (nenaudoti) ir atiduokite."}},"safety-b1-09":{"question":"HSE (darbo saugos tarnyba) sako, kad prisilietus prie kintamosios srovės (AC) elektros galima susižaloti maždaug nuo kokios įtampos?","options":["Maždaug nuo 50 voltų","Maždaug nuo 230 voltų","Maždaug nuo 400 voltų","Tik virš 1 000 voltų"],"explanation":"Kai kintamosios srovės (AC) įtampa didesnė nei maždaug 50 voltų, elektros smūgis gali pakenkti kvėpavimui ir širdžiai. Dėl jo taip pat galite nebesuvaldyti kūno ir nukristi nuo kopėčių ar paliesti judančią mašiną. Todėl įprastas elektros tinklas (mains) yra gerokai virš lygio, kuris gali jus sužaloti.","why_not":{"1":"Įprastas 230 voltų elektros tinklas (mains) yra gerokai virš lygio, kuris gali jus sužaloti; tas lygis prasideda maždaug nuo 50 voltų.","2":"Susižaloti galima nuo daug mažesnės įtampos – maždaug nuo 50 voltų kintamosios srovės (AC).","3":"Susižaloti galima nuo daug mažesnės įtampos – maždaug nuo 50 voltų kintamosios srovės (AC), todėl jus gali sužaloti ir gerokai mažesnė nei 1 000 voltų įtampa."}},"safety-b1-10":{"question":"Randate statybvietės elektros skydelį (power board) su sudaužytu dangčiu, matosi laidai. Ką turite daryti pirmiausia?","options":["Sukišti laidus atgal ir uždaryti","Toliau juo naudotis, tik atsargiai","Įspėti žmones laikytis atokiau ir, jei galite tai padaryti saugiai, jį išjungti","Uždengti jį lenta ir dirbti toliau"],"explanation":"Pažeista elektros įranga, iš kurios matosi laidai, gali nužudyti. Pirmiausia įspėkite visus laikytis atokiau. Išjunkite ją tik tada, jei galite tai padaryti saugiai. Tada praneškite, kad kompetentingas asmuo (competent person) padarytų ją saugią. Niekada nebandykite jos taisyti patys ir neužtenka jos tiesiog paslėpti.","why_not":{"0":"Matomi laidai gali nužudyti, todėl niekada nebandykite to taisyti patys, o įspėkite žmones ir praneškite.","1":"Pažeista įranga, iš kurios matosi laidai, gali nužudyti, kad ir kaip atsargiai elgtumėtės, todėl įspėkite žmones laikytis atokiau.","3":"Uždengus saugiau netampa, todėl įspėkite žmones, jei saugu – išjunkite ir praneškite."}},"safety-b1-12":{"question":"Įrankių sandėlyje ant pjūklo (cut-off saw) kabo kortelė su užrašu „DANGER - DO NOT USE“ (pavojinga – nenaudoti). Kas gali nuimti kortelę?","options":["Bet kas, kam reikia naudoti pjūklą","Tas, kas ryte atvyksta pirmas","Bet kas, kai kortelė kabo jau savaitę","Tik įgaliotas asmuo, kuris tikras, kad pjūklas dabar saugus"],"explanation":"Pavojaus kortelė reiškia, kad kažkas rado problemą. Pjūklo nenaudokite ir kortelės nenuimkite. Ją nuimti gali tik įgaliotas asmuo (authorised person), kuris įsitikino, kad pjūklas vėl saugus.","why_not":{"0":"Kortelę gali nuimti tik įgaliotas asmuo (authorised person), kuris tikras, kad pjūklas saugus.","1":"Atvykus pirmam, neatsiranda teisė jos nuimti, nes tai gali padaryti tik įgaliotas asmuo (authorised person).","2":"Laikas nepadaro pjūklo saugaus, todėl kortelę nuimti gali tik jį patikrinęs įgaliotas asmuo (authorised person)."}},"safety-b1-14":{"question":"Į darbą atsinešate savo plaktuką ir mentę. Ar darbo įrangos taisyklės (PUWER) taikomos ir jiems?","options":["Ne: taikomos tik įrankiams, kuriuos nupirko darbdavys","Tik jei jie elektriniai","Taip: taikomos ir įrankiams, kuriuos atsinešate darbui","Tik jei jiems mažiau nei vieneri metai"],"explanation":"Darbo įrangos taisyklės (PUWER) taikomos darbe naudojamai įrangai – nuo plaktukų ir peilių iki savivarčių. Jei darbdavys leidžia atsinešti savo įrankius, taisyklės taikomos ir jiems, ir darbdavys turi užtikrinti, kad jie būtų saugūs ir tinkami darbui. Laikykite juos geros būklės ir praneškite apie bet kokį pažeidimą.","why_not":{"0":"Jei darbdavys leidžia atsinešti savo įrankius, darbo įrangos taisyklės (PUWER) taikomos ir jiems.","1":"Darbo įrangos taisyklės (PUWER) taikomos ir paprastiems rankiniams įrankiams, pvz., plaktukams, o ne tik elektriniams.","3":"Įrankio amžius nesvarbus, nes taisyklės taikomos ir įrankiams, kuriuos atsinešate darbui."}},"safety-b1-15":{"question":"Skiedinio maišyklė užstrigo. Ką būtina padaryti, prieš kam nors kišant ranką jos išvalyti?","options":["Palikti ją lėtai veikti, kad kamštis pats iškristų","Išjungti ją ir atjungti nuo energijos šaltinio, kad ji negalėtų įsijungti","Valyti ją kastuvu, kol būgnas dar sukasi","Nieko, jei darote greitai"],"explanation":"Veikianti mašina arba mašina, kuri gali vėl įsijungti, gali pagriebti ranką. Prieš valant kamštį, valant ar reguliuojant mašiną, ją reikia išjungti ir atjungti nuo energijos šaltinio arba užrakinti (locked off), kad niekas negalėtų jos įjungti, kol jūs prie jos dirbate.","why_not":{"0":"Veikianti mašina gali pagriebti ranką, todėl pirmiausia ją reikia išjungti ir atjungti nuo energijos šaltinio.","2":"Niekada nevalykite kamščio, kol būgnas sukasi; pirmiausia mašiną reikia išjungti ir atjungti nuo energijos šaltinio.","3":"Greitumas neapsaugo nuo to, kad mašina jus pagriebtų, todėl ją reikia išjungti ir atjungti nuo energijos šaltinio."}},"safety-b1-16":{"question":"Blokelių padėklai palikti skersai pėsčiųjų tako, todėl žmonės, norėdami praeiti, turi eiti transporto keliu (haul road). Kas turi būti padaryta?","options":["Padėklus reikia patraukti, kad pėsčiųjų takas vėl būtų laisvas","Nieko: žmonės gali akimirkai užlipti ant transporto kelio","Ant padėklų uždėti ryškiaspalvę liemenę (hi-vis), kad vairuotojai juos matytų","Pasakyti tik vairuotojams, kad jie saugotųsi žmonių"],"explanation":"Pėsčiųjų takai laiko pėsčiuosius atokiau nuo transporto priemonių. HSE (darbo saugos tarnyba) sako, kad takai negali būti užstatyti taip, kad žmonėms tektų lipti ant kelio, kuriuo važiuoja transporto priemonės. Praneškite apie tai, kad medžiagos būtų patrauktos ir takas vėl būtų laisvas.","why_not":{"1":"HSE (darbo saugos tarnyba) sako, kad pėsčiųjų takai negali būti užstatyti taip, kad žmonėms tektų lipti ant transporto kelio (haul road).","2":"Pažymėjus padėklus nepadės, nes pėstiesiems vis tiek tenka eiti ten, kur važiuoja transporto priemonės.","3":"Įspėti vairuotojus neužtenka, nes pėsčiųjų taką reikia atlaisvinti, kad žmonės neitų keliu."}},"safety-b1-18":{"question":"Savivarčio (dumper) vairuotojas siūlo jus pavežti per statybvietę, sėdint ant kėbulo (skip) krašto. Ką darote?","options":["Lipate, bet tvirtai laikotės","Lipate, jei vairuotojas važiuos lėtai","Atsisakote: važiuoti galima tik tinkamoje keleiviui skirtoje sėdynėje","Lipate, jei dėvite šalmą"],"explanation":"Įstatymas sako, kad niekas negali važiuoti statybvietės transporto priemone, išskyrus saugioje tam skirtoje vietoje, pvz., keleivio sėdynėje. Sėdėdami ant kėbulo, kaušo ar laiptelio galite lengvai nukristi, ir transporto priemonė gali jus partrenkti. Eikite pėsčiomis ir naudokitės pėsčiųjų taku.","why_not":{"0":"Tvirtas laikymasis nepaverčia kėbulo saugia sėdyne, o jūs galite nukristi ir būti partrenkti.","1":"Lėtas važiavimas nekeičia įstatymo, kuris sako, kad važiuoti galima tik tinkamoje keleiviui skirtoje sėdynėje.","3":"Šalmas (hard hat) neapsaugo nuo nukritimo, todėl važiuoti galima tik tinkamoje keleiviui skirtoje sėdynėje."}},"safety-b1-20":{"question":"Kas dažniausiai žūsta nelaimingų atsitikimų su ekskavatoriais metu?","options":["Ekskavatoriaus vairuotojas","Šalia ekskavatoriaus dirbantys žmonės","Pro statybvietę einantys praeiviai","Krovinių vairuotojai, sėdintys savo sunkvežimiuose"],"explanation":"HSE (darbo saugos tarnyba) sako, kad dažniausiai su ekskavatoriais žūsta šalia mašinos dirbantys žmonės, o ne vairuotojas. Juos partrenkia mašinai judant, prispaudžia jai sukantis (slewing) arba užgauna kaušas. Todėl užtvaros laiko žmones atokiau nuo vietos, kur dirba ekskavatorius.","why_not":{"0":"HSE (darbo saugos tarnyba) sako, kad dažniausiai su ekskavatoriais žūsta šalia mašinos dirbantys žmonės, o ne vairuotojas.","2":"HSE (darbo saugos tarnyba) sako, kad dažniausiai su ekskavatoriais žūsta statybvietėje šalia mašinos dirbantys žmonės, o ne praeiviai.","3":"HSE (darbo saugos tarnyba) sako, kad dažniausiai su ekskavatoriais žūsta šalia mašinos dirbantys žmonės, o ne sunkvežimiuose sėdintys vairuotojai."}},"safety-b1-21":{"question":"Ekskavatorius sukasi (slewing) šalia sienos. Kokį tarpą, pasak HSE (darbo saugos tarnybos), reikia palikti tarp bet kurios mašinos dalies, ypač sunkios atsvaros gale, ir sienos?","options":["Bent 10 cm","Bent 25 cm","Daugiau nei 0,5 m (50 cm)","Tarpo nereikia, jei vairuotojas atsargus"],"explanation":"Kai ekskavatorius sukasi, jo galas apsisuka ratu. Jei tarpas iki sienos ar transporto priemonės per mažas, ten stovintį žmogų gali prispausti. HSE sako palikti daugiau nei 0,5 m tarpą, o ankštoms vietoms rinktis mašiną su trumpu galu (short tail swing).","why_not":{"0":"10 cm – gerokai per mažai, ir žmogų gali prispausti, todėl HSE (darbo saugos tarnyba) sako palikti daugiau nei 0,5 m.","1":"25 cm – vis dar per mažai, ir žmogų gali prispausti, todėl HSE (darbo saugos tarnyba) sako palikti daugiau nei 0,5 m.","3":"Vien atsargumo neužtenka, nes HSE (darbo saugos tarnyba) sako, kad reikia palikti daugiau nei 0,5 m tarpą."}},"safety-b1-23":{"question":"Ant pėsčiųjų tako palikta senos medienos su kyšančiomis vinimis. Kas turi būti padaryta?","options":["Palikti: visi avi apsauginius batus","Ištraukti vinis arba patraukti medieną","Nuspirti ją į tako kraštą","Sukrauti į krūvą ir palikti iki darbo pabaigos"],"explanation":"Įstatymas sako, kad mediena su kyšančiomis vinimis negali būti palikta ten, kur ji gali ką nors sužaloti. Vinis gali įsmigti į pėdą arba į ranką, kai keliate medieną. Apsauginiai batai padeda, bet tai ne priežastis ją ten palikti.","why_not":{"0":"Batai padeda, bet įstatymas sako, kad mediena su kyšančiomis vinimis negali būti palikta ten, kur ji gali ką nors sužaloti.","2":"Nuspyrus ją į šoną, vinys lieka ten, kur kas nors gali ant jų užlipti ar už jų nusitverti.","3":"Jos apskritai negalima palikti besimėtančios, todėl ištraukite vinis arba patraukite medieną dabar."}},"safety-b1-25":{"question":"Mūrininkas sako, kad atliekas savo darbo vietoje tvarkyti – tik pagalbinio darbininko darbas. Ką sako HSE (darbo saugos tarnyba)?","options":["Jis teisus: atliekas tvarko tik pagalbiniai darbininkai","Atliekų tvarkymas turi būti kiekvienos specialybės prioritetas","Atliekos gali palaukti iki darbo pabaigos","Atliekomis rūpinasi tik statybvietės vadovas"],"explanation":"Aplink besimėtančios atliekos sukelia suklupimų ir gali įsiplieskti gaisrui. HSE sako, kad kiekviena specialybė turi savo atliekų tvarkymą laikyti prioritetu ir darbo vietas tvarkyti visą darbo laiką, o ne tik pabaigoje.","why_not":{"0":"HSE (darbo saugos tarnyba) sako, kad atliekų tvarkymas turi būti visų specialybių, o ne tik pagalbinių darbininkų prioritetas.","2":"Besimėtančios atliekos sukelia suklupimų, todėl darbo vietą tvarkykite visą darbo laiką, o ne tik pabaigoje.","3":"HSE (darbo saugos tarnyba) sako, kad atliekų tvarkymas yra kiekvienos specialybės prioritetas, o ne statybvietės vadovui paliekamas darbas."}},"safety-b2-02":{"question":"Labai karšta diena. Norite mūvėti šortus, bet statybvietės taisyklės šortų neleidžia. Ką darote?","options":["Mūviu ilgas kelnes: statybvietės taisyklės reikia laikytis","Mūviu šortus: karštis yra didesnis pavojus","Mūviu šortus, jei batai siekia aukštai","Mūviu šortus, bet vengiu statybvietės vadovo"],"explanation":"Jei statybvietėje šortų mūvėti neleidžiama, turite laikytis šios taisyklės. Kelnės padeda apsaugoti kojas nuo įpjovimų, nubrozdinimų ir rakščių. Statybvietėje net mažas odos įpjovimas gali užsikrėsti. Aukšti batai uždengia tik dalį kojų.","why_not":{"1":"Statybvietės taisyklės turite laikytis, o kelnės saugo kojas nuo įpjovimų, kurie gali užsikrėsti.","2":"Aukšti batai uždengia tik dalį kojų, o statybvietės taisyklė šortų neleidžia.","3":"Slapstantis nuo vadovo, taisyklė vis tiek pažeidžiama, o jos tikimasi, kad laikysitės."}},"safety-b2-03":{"question":"Jūsų statybvietėje neleidžiami „rigger“ batai (rigger boots – aukšti apsauginiai batai be raištelių, kurie užsimaunami). Kokią priežastį HSE (darbo saugos tarnyba) nurodo, kodėl kai kuriose statybvietėse jie draudžiami?","options":["Jie laisvesni, todėl juos avintys žmonės dažniau išsisuka ar patempia kulkšnį","Lyjant į juos patenka vandens","Jie kainuoja daugiau nei batai su raišteliais","Jie per sunkūs, kad juos būtų galima avėti visą dieną"],"explanation":"Kai kurios įmonės pastebėjo, kad žmonės, avintys „rigger“ batus (rigger boots), daug dažniau išsisuka ar patempia kulkšnį. Šie batai laisvesni, todėl ant nelygaus paviršiaus pėda lengviau pakrypsta į šoną. HSE (darbo saugos tarnyba) sako, kad tai pagrįsta priežastis tokiai statybvietės taisyklei, ir jos reikia laikytis.","why_not":{"1":"HSE (darbo saugos tarnyba) nurodo ne lietų, o tai, kad laisvesni batai dažniau baigiasi išsisukusiomis ar patemptomis kulkšnimis.","2":"HSE (darbo saugos tarnyba) nurodo ne kainą, o tai, kad laisvesni batai dažniau baigiasi išsisukusiomis ar patemptomis kulkšnimis.","3":"HSE (darbo saugos tarnyba) nurodo ne svorį, o tai, kad avint laisvesnius batus lengviau išsisukti kulkšnį."}},"safety-b2-06":{"question":"Savivartis sunkvežimis (tipper lorry) verčia krovinį netoli elektros linijos virš galvos (overhead power line). Vairuotojas sako: „Viskas gerai, jei tik kėbulas nepaliečia laidų.“ Kas yra tiesa?","options":["Jis teisus: pavojus tik tada, jei paliečia","Užtenka priartėti per arti: elektra gali peršokti per tarpą","Saugu, jei variklis išjungtas","Saugu, nes sunkvežimio padangos yra guminės"],"explanation":"Kad būtumėte pavojuje, nebūtina paliesti elektros linijos. Jei savivarčio kėbulas ar bet kokia technika priartėja prie laidų, elektra gali peršokti per tarpą. Tai vadinama elektros išlydžiu (flashover). Išjungtas variklis ar guminės padangos to nesustabdo. Laikykitės gerokai atokiau nuo linijų.","why_not":{"0":"Laidų liesti nebūtina: užtenka priartėti, ir elektra gali peršokti per tarpą.","2":"Išjungtas variklis nesustabdo elektros, peršokančios nuo laidų per tarpą.","3":"Guminės padangos nesustabdo nuo laidų peršokančios elektros, todėl laikykitės gerokai atokiau nuo linijų."}},"safety-b2-09":{"question":"Jūsų 230 V įrankis prijungtas per srovės nuotėkio jungiklį (RCD). Bendradarbis sako: „Su RCD elektra tavęs nesužeis.“ Kas yra tiesa?","options":["Jis teisus: RCD apsaugo nuo bet kokio elektros smūgio","RCD sumažina sužeidimo tikimybę, bet elektros smūgis vis tiek gali sunkiai sužeisti ar užmušti","RCD veikia tik patalpose","Su RCD įrankio niekada nereikia tikrinti"],"explanation":"Srovės nuotėkio jungiklis (RCD) labai greitai išjungia elektrą, kai aptinka kai kuriuos gedimus, todėl sužeidimas mažiau tikėtinas. Bet HSE (darbo saugos tarnyba) sako, kad elektros smūgis vis tiek gali sukelti labai sunkių ar mirtinų sužeidimų. Taigi RCD yra tik papildoma apsauga. Vis tiek reikia saugių įrankių ir geros būklės laidų.","why_not":{"0":"Srovės nuotėkio jungiklis (RCD) sumažina sužeidimo tikimybę, bet HSE (darbo saugos tarnyba) sako, kad elektros smūgis vis tiek gali sunkiai sužeisti ar užmušti.","2":"Srovės nuotėkio jungiklis (RCD) veikia ir lauke, bet tai tik papildoma apsauga, todėl elektros smūgis vis tiek gali jus sunkiai sužeisti.","3":"Srovės nuotėkio jungiklis (RCD) – tik papildoma apsauga, todėl vis tiek reikia saugių įrankių ir patikrintų laidų."}},"safety-b2-10":{"question":"Ruošiatės uždėti naują diską ant kampinio šlifuoklio (angle grinder). Kas turi būti tiesa apie ant disko pažymėtą greitį?","options":["Šlifuoklis niekada negali sukti disko greičiau, nei ant jo pažymėta","Nieko: tinka bet koks diskas, kuris telpa ant šlifuoklio","Diską reikia sukti greičiau, nei pažymėta, kad greičiau pjautų","Greičio žymėjimai svarbūs tik stacionariems šlifuokliams, ne rankiniams"],"explanation":"Ant kiekvieno disko pažymėtas didžiausias greitis, kurį jis saugiai atlaiko. Sukimas greičiau yra viena pagrindinių priežasčių, kodėl diskai subyra. Sprogusio disko gabalai lekia labai greitai – maždaug 80 mph (mylių per valandą) ar greičiau. Patikrinkite, kad šlifuoklio greitis nebūtų didesnis už greitį ant disko.","why_not":{"1":"Neužtenka, kad diskas telpa: šlifuoklis negali sukti disko greičiau, nei ant jo pažymėta.","2":"Per greitas disko sukimas yra viena pagrindinių priežasčių, kodėl jis subyra.","3":"Greičio žymėjimas svarbus kiekvienam abrazyviniam diskui, taip pat ir rankiniams šlifuokliams."}},"safety-b2-11":{"question":"Norite naudoti didesnį diską, nei telpa po jūsų kampinio šlifuoklio (angle grinder) apsauginiu gaubtu (guard). Bendradarbis sako: „Nuimk gaubtą, ir tilps.“ Ką darote?","options":["Nedarau to: gaubtą palieku ir naudoju tik tam šlifuokliui skirtus diskus","Nuimu gaubtą, bet užsidedu veido skydelį","Nuimu gaubtą, bet tik vienam greitam pjūviui","Nuimu gaubtą ir spaudžiu švelniau"],"explanation":"HSE (darbo saugos tarnyba) sako, kad įvyko sunkių, dažnai mirtinų nelaimingų atsitikimų, kai gaubtas (guard) buvo nuimtas, kad tilptų didesnis diskas. Tada didesnis diskas sukasi greičiau, nei jam skirta, ir gali sprogti, o tarp jūsų ir gabalų nėra jokio gaubto. Veido skydelis ar greitas pjūvis to nepadaro saugiu.","why_not":{"1":"Veido skydelio neužtenka, nes didesnis diskas gali suktis per greitai ir sprogti, o gaubto (guard) nebus.","2":"Diskui sprogti užtenka vieno greito pjūvio, todėl niekada nenuimkite gaubto (guard).","3":"Švelnesnis spaudimas neapsaugo nuo to, kad per didelis diskas suktųsi per greitai ir sprogtų."}},"safety-b2-12":{"question":"Prieš uždėdami pjovimo diską pastebite, kad jis šiek tiek išlinkęs (warped). Ką turėtumėte daryti?","options":["Jo nenaudoti: paimti naują diską","Naudoti jį, bet spausti stipriau, kad laikytųsi tiesiai","Naudoti jį tik mažiems pjūviams","Pirmiausia ištiesinti jį plaktuku"],"explanation":"Prieš uždėdami pjovimo diskus patikrinkite, ar jie neišlinkę ir nepažeisti. HSE (darbo saugos tarnyba) sako, kad išlinkusio (warped) disko naudoti negalima. Jis gali drebėti, trintis į pjūvio kraštus, įkaisti ir besisukdamas subyrėti. Daužymas plaktuku ar stipresnis spaudimas tik pablogina padėtį.","why_not":{"1":"Stipriau spaudžiant tik blogiau, nes išlinkęs (warped) diskas gali drebėti, įkaisti ir subyrėti.","2":"HSE (darbo saugos tarnyba) sako, kad išlinkusio (warped) disko negalima naudoti visai, net mažiems pjūviams.","3":"Daužant plaktuku saugiau netampa, nes HSE (darbo saugos tarnyba) sako, kad išlinkusio (warped) disko naudoti negalima."}},"safety-b2-13":{"question":"Žmogus, kuris dirba su statybvietės stacionariu pjūklu (bench saw), išėjo pertraukai. Naujokas, kuriam niekas nerodė, kaip juo naudotis, siūlosi užbaigti darbą. Kas turėtų būti daroma?","options":["Jis turi palaukti: pjūklu gali naudotis tik apmokyti ir tam įgalioti žmonės","Jis gali juo naudotis, jei dirbs lėtai","Jis gali juo naudotis, nes darbas beveik baigtas","Jis gali juo naudotis, jei mūvės pirštines"],"explanation":"HSE (darbo saugos tarnyba) sako neleisti niekam naudotis mašinomis, jei jis nėra apmokytas ar įgaliotas. Naujokams gresia didesnis pavojus, ir jiems pirmiausia reikia instruktažo, mokymų ir priežiūros. Lėtas darbas, pirštinės ar beveik baigtas darbas neatstoja žinojimo, kaip saugiai naudotis pjūklu.","why_not":{"1":"Lėtas darbas neatstoja žinojimo, kaip saugiai naudotis pjūklu.","2":"Beveik baigtas darbas nepadaro to saugaus, nes pjūklu gali naudotis tik apmokyti ir įgalioti žmonės.","3":"Pirštinės neatstoja mokymų, todėl jis pjūklu naudotis negali."}},"safety-b2-14":{"question":"Dirbate šalia didelės mašinos. Ji įjungia garso signalą, ir pradeda mirksėti lemputė. Ką šis įspėjimas greičiausiai jums sako?","options":["Mašina tuoj įsijungs: pasitraukite į saugią vietą","Laikas pertraukai","Mašina sugedo, ir prie jos prieiti saugu","Operatorius nori, kad prieitumėte arčiau"],"explanation":"Darbo įrangos įstatymas sako, kad kur reikia, prieš įsijungiant mašinai turi būti duodamas girdimas ar matomas įspėjimas. Jis taip pat sako, kad pavojuje esantys žmonės turi turėti pakankamai laiko ir galimybę pasitraukti. Todėl išgirdę ar pamatę įspėjimą, iš karto pasitraukite nuo mašinos.","why_not":{"1":"Garso signalas ir mirksinti lemputė įspėja, kad mašina tuoj įsijungs, o ne kad laikas pertraukai.","2":"Įspėjimas reiškia, kad mašina tuoj įsijungs, todėl prieiti prie jos nesaugu.","3":"Įspėjimas liepia pasitraukti, o ne prieiti arčiau."}},"safety-b2-15":{"question":"Bendradarbis pjauna bortelį pjovimo pjūklu (cut-off saw). Jums reikia jo kai ko paklausti. Ką turėtumėte daryti?","options":["Palaukti, kol jis baigs pjūvį ir sustabdys pjūklą","Paliesti jam petį, kol jis pjauna","Prieiti iš už nugaros ir šaukti per triukšmą","Mesti netoli jo akmenuką, kad atkreiptumėte dėmesį"],"explanation":"HSE (darbo saugos tarnyba) sąraše, ko negalima daryti prie mašinų, yra ir dirbančiųjų su jomis blaškymas. Jei jis išsigąs, kol pjūklas pjauna, gali nesuvaldyti pjūklo ir sužeisti save ar jus. Palaukite, kol pjūklas sustos ir jis jus matys.","why_not":{"1":"Palietę jį, kol jis pjauna, galite jį išgąsdinti, ir jis gali nesuvaldyti pjūklo.","2":"Šaukdami iš už nugaros galite jį išgąsdinti, o HSE (darbo saugos tarnyba) sako neblaškyti dirbančiųjų su mašinomis.","3":"Mėtydami daiktus jį blaškote, ir jis gali nesuvaldyti pjūklo."}},"safety-b2-17":{"question":"Pėsčiųjų takas jūsų statybvietėje turi kirsti kelią, kuriuo važinėja statybvietės transportas. Kokia, pasak HSE (darbo saugos tarnybos), turi būti perėja?","options":["Aiškiai pažymėta ženklais ir apšviesta, kur vairuotojai ir pėstieji gerai mato vieni kitus","Ties nepermatomu posūkiu, kur transportas turi sulėtinti greitį","Už sukrautų medžiagų, kur nepučia vėjas","Bet kur, kur žmonėms patinka, jei tik jie perbėga"],"explanation":"Kur pėsčiųjų takas kerta transporto kelią, HSE (darbo saugos tarnyba) sako, kad turi būti aiškiai ženklais pažymėta ir apšviesta perėja. Vairuotojai ir pėstieji turi gerai matyti vieni kitus. Ties nepermatomu posūkiu ar už sukrautų medžiagų niekas nemato, kas ateina.","why_not":{"1":"Ties nepermatomu posūkiu vairuotojai ir pėstieji nemato vieni kitų.","2":"Už sukrautų medžiagų vairuotojai ir pėstieji nemato, kas ateina.","3":"Žmonės turi eiti per aiškiai ženklais pažymėtą ir apšviestą perėją, o ne kur nori."}},"safety-b2-19":{"question":"Statybvietės savivartis (dumper) pastatytas, ir niekas juo nesinaudoja. Kartą ūkyje vairavote traktorių. Ar galite savivarčiu pervežti smėlio?","options":["Ne: tą savivartį gali vairuoti tik apmokyti, kompetentingi ir tam įgalioti vairuotojai","Taip, jei važiuosite lėtai","Taip, nes esate vairavęs traktorių","Taip, jei jame paliktas raktelis"],"explanation":"HSE (darbo saugos tarnyba) sako, kad savivarčių (dumper) vairuotojai turi būti apmokyti, kompetentingi ir įgalioti vairuoti tą savivartį. Savivarčiai lengvai apvirsta, ir dauguma su jais susijusių mirčių įvyksta, kai savivartis apvirsta arba partrenkia pėsčiąjį. Kartą vairuotas traktorius nesiskaito, o paliktas raktelis nėra leidimas.","why_not":{"1":"Lėtas važiavimas to neleidžia, nes juo naudotis gali tik apmokyti, kompetentingi ir įgalioti vairuotojai.","2":"Traktorius nėra tas savivartis (dumper), o jūs turite būti apmokyti ir įgalioti vairuoti būtent jį.","3":"Paliktas raktelis nėra leidimas, nes vairuoti galite tik būdami apmokyti ir įgalioti."}},"safety-b2-22":{"question":"Savivarčio (dumper) kėbulas pripiltas grunto, sukrauto gerokai aukščiau jo viršutinio krašto. Vairuotojas nemato per jį. Kas turėtų būti daroma?","options":["Nuimti dalį grunto: krovinys neturi būti aukščiau kėbulo krašto ar užstoti vairuotojui vaizdo","Nieko, jei vairuotojas važiuos lėtai","Nieko, nes tai tik trumpas pervažiavimas","Nieko, jei gruntas sausas"],"explanation":"HSE (darbo saugos tarnyba) sako, kad savivarčio (dumper) krovinys turi būti paskirstytas tolygiai ir neturi būti aukščiau kėbulo viršutinio krašto. Krovinys neturi užstoti vairuotojui vaizdo. Vairuotojas, kuris nemato priekyje, gali ką nors partrenkti, net važiuodamas lėtai ar trumpai.","why_not":{"1":"Lėtas važiavimas nepadeda vairuotojui, kuris nemato priekyje, nes jis vis tiek gali ką nors partrenkti.","2":"Net trumpas pervažiavimas pavojingas, jei vairuotojas nemato, todėl nuimkite dalį grunto.","3":"Sausas ar šlapias, krovinys neturi būti aukščiau kėbulo viršutinio krašto ar užstoti vairuotojui vaizdo."}},"safety-b2-23":{"question":"Kelio ženklai prie statybvietės transporto kelio (haul road) aplipę purvu, ir juos sunku perskaityti. Kas turėtų būti daroma?","options":["Juos reikia nuvalyti, kad būtų matomi ir atliktų savo paskirtį","Nieko: vairuotojai jau žino taisykles","Juos nuimti, nes nešvarūs ženklai nenaudingi","Palikti juos iki darbų pabaigos"],"explanation":"HSE (darbo saugos tarnyba) sako, kad ženklus reikia valyti ir prižiūrėti, kad jie išliktų gerai matomi ir atliktų savo paskirtį. Ženklas, kurio niekas negali perskaityti, niekieno neįspėja, o nauji vairuotojai ir lankytojai statybvietės taisyklių nežino. Nuėmus ženklus, bus dar blogiau.","why_not":{"1":"Nauji vairuotojai ir lankytojai taisyklių nežino, todėl ženklai turi būti švarūs ir gerai matomi.","2":"Nuėmus ženklus, bus dar blogiau, todėl juos nuvalykite, kad jie atliktų savo paskirtį.","3":"Ženklas, kurio niekas negali perskaityti, niekieno neįspėja, todėl juos nuvalykite dabar, o ne darbų pabaigoje."}},"safety-b2-24":{"question":"Tvarkote skaldytus blokelius antrame aukšte. Bendradarbis sako: „Tiesiog išmesk juos pro langą į konteinerį.“ Kas teisinga?","options":["Nemesti jų: saugiai nuleisti žemyn, pvz., atliekų lataku ar dėžėje","Mesti, jei prieš tai garsiai įspėji","Mesti, jei atrodo, kad apačioje nieko nėra","Mesti, bet tik mažus gabalus"],"explanation":"Įstatymas sako, kad medžiagų negalima mesti ar versti iš aukščio, jei jos gali ką nors sužeisti. Net mažas blokelio gabalas gali sunkiai sužeisti apačioje esantį žmogų, o jūs ne visada matote, kas ten yra. Naudokite tinkamą būdą nuleisti žemyn, pvz., uždarą atliekų lataką ar dėžę.","why_not":{"1":"Garsus įspėjimas nepadaro to saugaus, nes įstatymas sako nemesti iš aukščio daiktų, kurie gali ką nors sužeisti.","2":"Ne visada matote, kas yra apačioje, todėl verčiau saugiai nuleiskite blokelius žemyn.","3":"Net mažas blokelio gabalas gali sunkiai sužeisti apačioje esantį žmogų, todėl nieko nemeskite."}},"safety-b2-25":{"question":"Jums reikia nutiesti ilgintuvą per pėsčiųjų taką, kad pasiektumėte savo darbo vietą. Ką turėtumėte daryti su laidu?","options":["Nutiesti jį ten, kur žmonės už jo neužklius ir kur mažesnė tikimybė jį pažeisti","Nutiesti jį skersai tako vidurio, kur žmonės jį matys","Palikti jį laisvomis kilpomis ant grindų, kad būtų pakankamai atsargos","Pravesti jį pro durų angą ir uždaryti duris ant jo"],"explanation":"HSE (darbo saugos tarnyba) sako, kad laidus reikia tiesti ten, kur už jų nebus užkliūnama ir kur mažesnė tikimybė juos pažeisti. Laidas skersai tako gali parversti žmones, o į laisvas kilpas lengva įkišti koją. Uždarytos durys gali suspausti laidą ir pažeisti jo izoliaciją, o tai gali sukelti elektros smūgį.","why_not":{"1":"Laidas skersai tako vidurio gali parversti žmones, net jei jie jį mato.","2":"Į laisvas kilpas ant grindų lengva įkišti koją ir užkliūti.","3":"Uždarytos durys gali suspausti laidą ir pažeisti jo izoliaciją, o tai gali sukelti elektros smūgį."}},"safety-b3-02":{"question":"Jūsų ryškiaspalvė (hi-vis) striukė aplipusi purvu, o jos šviesą atspindinčios juostos sunkiai matomos. Kas turėtų būti daroma?","options":["Ją išvalyti arba pakeisti švaria, kad juostos vėl būtų matomos","Nieko: oranžinė spalva vis tiek matosi","Vilkėti ją išverstą iki darbo pabaigos","Palikti ją iki darbo pabaigos, o paskui išskalbti"],"explanation":"HSE (darbo saugos tarnyba) sako, kad ryškiaspalvės (hi-vis) striukės, kelnės ir kombinezonai turi būti reguliariai valomi, kad šviesą atspindinčios juostos būtų gerai matomos. Nešvarūs tokie drabužiai veikia daug prasčiau. Jei purvas uždengia juostas, vairuotojai gali jūsų nepamatyti.","why_not":{"1":"Šviesą atspindinčios juostos irgi svarbios, todėl HSE (darbo saugos tarnyba) sako ryškiaspalvius (hi-vis) drabužius laikyti švarius, kad juostos būtų gerai matomos.","2":"Išverstos juostos visai nesimato, todėl striukę išvalykite arba pakeiskite švaria.","3":"Vairuotojai gali jūsų nepamatyti jau šiandien, o HSE (darbo saugos tarnyba) sako ryškiaspalvius (hi-vis) drabužius valyti reguliariai, ne tik darbo pabaigoje."}},"safety-b3-03":{"question":"Vyras statybvietės automobilių stovėjimo aikštelėje iš savo furgono pardavinėja labai pigius šalmus. Etikečių ant jų nėra. Kodėl, pasak HSE (darbo saugos tarnybos), tokio šalmo naudoti nereikėtų?","options":["Jie gali būti netinkamos spalvos jūsų specialybei","Parduodama padirbtų šalmų: galvos apsaugos priemones reikia pirkti tik iš patikimo tiekėjo","Galite dėvėti tik šalmą su savo įmonės pavadinimu","Šalmas tinka tik tada, jei sumokėjote visą kainą"],"explanation":"HSE (darbo saugos tarnyba) įspėja, kad rinkoje yra padirbtų šalmų (hard hats). Padirbtas šalmas gali atrodyti tinkamai, bet neapsaugoti galvos. Galvos apsaugos priemonės turi būti tik iš patikimo tiekėjo, todėl paprašykite darbdavio tinkamo šalmo.","why_not":{"0":"Problema – ne spalva: padirbtas šalmas (hard hat) gali atrodyti tinkamai, bet neapsaugoti galvos.","2":"HSE (darbo saugos tarnyba) nereikalauja ant šalmo jūsų įmonės pavadinimo, tik kad jis būtų iš patikimo tiekėjo.","3":"Kaina neįrodo, kad šalmas (hard hat) tikras, todėl galvos apsaugos priemones pirkite iš patikimo tiekėjo."}},"safety-b3-04":{"question":"Šiam darbui reikia pirštinių rankoms apsaugoti. Bendradarbis sako, kad vietoj jų užteks įsitrinti rankas apsauginiu kremu (barrier cream). Kas teisinga?","options":["Apsauginis kremas neatstoja tinkamų asmeninių apsaugos priemonių (PPE): mūvėkite pirštines","Apsauginis kremas tinka, jei užtepsite storą sluoksnį","Ryte naudoti apsauginį kremą, o po pietų – pirštines","Apsauginis kremas geresnis, nes jaučiate, ką darote"],"explanation":"HSE (darbo saugos tarnyba) sako, kad apsauginiai kremai (barrier creams) neatstoja tinkamų asmeninių apsaugos priemonių (PPE). Jei darbui reikia pirštinių, mūvėkite pirštines. Daugiau kremo to nepakeičia.","why_not":{"1":"Storesnis sluoksnis nepadeda, nes HSE (darbo saugos tarnyba) sako, kad apsauginis kremas (barrier cream) neatstoja tinkamų asmeninių apsaugos priemonių (PPE).","2":"Darbui reikia pirštinių, todėl mūvėkite jas visą laiką, nes kremas neatstoja asmeninių apsaugos priemonių (PPE).","3":"Tai, kad jaučiate, ką darote, rankų neapsaugo, o apsauginis kremas (barrier cream) neatstoja pirštinių."}},"safety-b3-05":{"question":"Palikote ausų kamštukus (ear plugs) namie. Bendradarbis siūlo jums daugkartinius kamštukus, kuriuos jis nešiojo vakar. Ką turėtumėte daryti?","options":["Perplauti juos po čiaupu ir naudoti","Naudoti juos: dalytis galima, jei jis nesirgo","Paprašyti savo porelės: tokios asmeninės apsaugos priemonės (PPE) turi būti skirtos tik vienam žmogui, kad būtų švarios","Vieną dieną dirbti be klausos apsaugos priemonių"],"explanation":"Įstatymas sako, kad kai to reikia, kad asmeninės apsaugos priemonės (PPE) būtų švarios ir nekeltų pavojaus sveikatai, jos turi būti duodamos vienam žmogui tik jo paties naudojimui. Ausų kamštukai dedami į ausis, todėl jais nesidalykite. Prieš pradėdami darbą paprašykite savo porelės ir nedirbkite be klausos apsaugos priemonių, kai jų darbui reikia.","why_not":{"0":"Perplauti jie netampa jūsų, o ausų kamštukai (ear plugs) dedami į ausis, todėl jais nesidalykite.","1":"Kad būtų švarūs, ausų kamštukai (ear plugs) turi būti skirti tik vienam žmogui, net jei jis nesirgo.","3":"Nedirbkite be klausos apsaugos priemonių, kai jų darbui reikia, todėl paprašykite savo porelės."}},"safety-b3-06":{"question":"Šiai dienai baigėte naudotis apsauginiais akiniais. Darbdavys davė jums spintelę asmeninėms apsaugos priemonėms (PPE) laikyti. Ką turėtumėte su jais daryti?","options":["Palikti juos ant darbastalio, kad ryte būtų po ranka","Padėti juos atgal į jums skirtą spintelę","Pakabinti juos ant maišyklės, kad rastumėte","Palikti juos ant furgono prietaisų skydelio"],"explanation":"Įstatymas sako, kad darbuotojai, gavę asmeninių apsaugos priemonių (PPE), po naudojimo turi imtis pagrįstų veiksmų ir padėti jas į tam skirtą vietą. Ten jos lieka švarios, apsaugotos nuo pažeidimų ir paruoštos kitam kartui.","why_not":{"0":"Įstatymas sako, kad po naudojimo asmenines apsaugos priemones (PPE) turite padėti į tam skirtą vietą.","2":"Ant maišyklės jie gali išsitepti ar būti pažeisti, todėl padėkite juos atgal į jums skirtą spintelę.","3":"Furgone jie gali išsitepti ar būti pažeisti, todėl padėkite juos atgal į jums skirtą spintelę."}},"safety-b3-07":{"question":"Jūsų saugos diržų (harness) sagtis vis stringa. Bendradarbis siūlo ją sutvarkyti replėmis ir trupučiu alyvos. Kas turėtų būti daroma?","options":["Pranešti apie tai: diržus gali tekti grąžinti gamintojui, kad juos suremontuotų","Leisti jam sutvarkyti, jei jis atsargus","Naudoti juos tokius, kokie yra, ir sutvarkyti savaitgalį","Pakeisti sagtį kita, paimta nuo seno krepšio"],"explanation":"Kai kurias paprastas priežiūros užduotis galite atlikti patys, pvz., įverti naują batų raištelį. Bet HSE (darbo saugos tarnyba) sako, kad specialias asmenines apsaugos priemones (PPE), pvz., saugos diržus darbui aukštyje, gali tekti grąžinti gamintojui, jei jas reikia remontuoti. Savadarbis remontas gali neatlaikyti tada, kai jo labiausiai reikia, todėl praneškite apie tai.","why_not":{"1":"Savadarbis remontas gali neatlaikyti tada, kai jo labiausiai reikia, o saugos diržus (harness) gali tekti grąžinti gamintojui.","2":"Strigianti sagtis gali neatlaikyti tada, kai jos reikia, todėl praneškite apie tai dabar, o ne naudokite.","3":"Sagtis nuo krepšio nepagaminta saugos diržams (harness) ir gali neatlaikyti, todėl verčiau praneškite."}},"safety-b3-09":{"question":"Prieš naudodami kampinį šlifuoklį (angle grinder) pastebite ant jo kištuko rudų apdegimo žymių. Ką šios žymės greičiausiai reiškia?","options":["Tai tik statybvietės nešvarumai","Kištukas naujas ir dar „įsidirba“","Saugiklis tinkamai atlieka savo darbą","Jis perkaista: neleiskite juo naudotis ir duokite jį patikrinti"],"explanation":"HSE (darbo saugos tarnyba) nurodytas paprastas apžiūros patikrinimas apima apdegimo žymių ar dėmių paieškas, nes jos rodo, kad įranga perkaista. Jei dėl įrankio kyla abejonių, neleiskite juo naudotis ir paprašykite kompetentingo asmens (competent person) jį tinkamai patikrinti.","why_not":{"0":"Apdegimo žymės nėra nešvarumai, nes HSE (darbo saugos tarnyba) sako, kad jos rodo, jog įrankis perkaista.","1":"Ant naujų kištukų apdegimo žymių neatsiranda dėl „įsidirbimo“, nes HSE (darbo saugos tarnyba) sako, kad apdegimo žymės rodo perkaitimą.","2":"Apdegimo žymės nereiškia, kad saugiklis veikia, nes jos rodo, kad įrankis perkaista."}},"safety-b3-10":{"question":"Prie kokios srovės, pasak HSE (darbo saugos tarnybos), turi išsijungti srovės nuotėkio jungiklis (RCD), skirtas apsaugoti žmones nuo elektros smūgio?","options":["Bent 100 miliamperų (mA)","Ne daugiau kaip 30 miliamperų (mA)","13 amperų, tiek pat kaip saugiklis","Prie bet kokios, jei tik jis turi bandymo mygtuką"],"explanation":"Kad apsaugotų žmones, srovės nuotėkio jungiklio (RCD) suveikimo srovė turi būti ne didesnė kaip 30 mA. Srovės nuotėkio jungikliai, kurie suveikia prie didesnės srovės, naudojami apsaugai nuo gaisro, o ne žmonėms apsaugoti nuo elektros smūgio. 13 amperų saugiklis – visai kitas dalykas.","why_not":{"0":"100 mA – per daug žmonėms apsaugoti, nes srovės nuotėkio jungikliai (RCD), kurie suveikia prie didesnės srovės, skirti apsaugai nuo gaisro.","2":"13 amperų saugiklis – visai kitas dalykas, o žmonėms apsaugoti skirtas srovės nuotėkio jungiklis (RCD) turi suveikti prie 30 mA ar mažesnės srovės.","3":"Nustatymas svarbus, nes žmonėms apsaugoti srovės nuotėkio jungiklis (RCD) turi suveikti prie ne didesnės kaip 30 mA srovės."}},"safety-b3-11":{"question":"Statybvietės elektriniai įrankiai veikia 110 V įtampa iš transformatoriaus, kurio vidurio taškas įžemintas (centre tapped to earth). Ką tai duoda?","options":["Tada įrankių niekada nereikia tikrinti","Tada laidai tampa nepralaidūs vandeniui","Įtampa tarp fazinio laido ir žemės sumažėja perpus","Įrankių galia padidėja dvigubai"],"explanation":"HSE (darbo saugos tarnyba) sako, kad transformatorius, kurio išėjimo vidurio taškas įžemintas (centre tapped to earth), perpus sumažina įtampą tarp fazinio laido ir žemės. Mažesnė įtampa reiškia mažesnę sunkaus elektros smūgio riziką, todėl toks maitinimas naudojamas statybvietėse. Įrankius ir laidus vis tiek reikia tikrinti.","why_not":{"0":"Įrankius ir laidus vis tiek reikia tikrinti, net jei įtampa mažesnė.","1":"Tai nepadaro laidų nepralaidžių vandeniui; tai perpus sumažina įtampą tarp fazinio laido ir žemės.","3":"Tai nepadvigubina galios; tai perpus sumažina įtampą tarp fazinio laido ir žemės."}},"safety-b3-12":{"question":"Statybvietės vagonėlyje trūksta elektros lizdų, todėl kažkas į vieną lizdą įjungė kelis adapterius virduliui, šildytuvui ir telefonų įkrovikliams. Koks pavojus?","options":["Perkrovus lizdą adapteriais gali kilti gaisras","Įkrovikliai kraus per lėtai","Jokio, jei virdulys ir šildytuvas neįjungti tuo pačiu metu","Tai svarbu tik tada, jei adapteriai skirtingų gamintojų"],"explanation":"HSE (darbo saugos tarnyba) sako, kad perkrovus elektros lizdus adapteriais gali kilti gaisras. Lizdų turi būti pakankamai, kad žmonėms nereikėtų jungti adapterių vieno į kitą. Jei tai pamatysite, pasakykite darbų vadovui (supervisor).","why_not":{"1":"Tikrasis pavojus – gaisras, o ne lėtas krovimas, nes perkrovus lizdą adapteriais gali kilti gaisras.","2":"Adapteriai, sujungti vienas į kitą viename lizde, vis tiek kelia gaisro pavojų, todėl turi būti pakankamai lizdų.","3":"Gamintojai nesvarbūs, nes perkrovus vieną lizdą adapteriais gali kilti gaisras."}},"safety-b3-13":{"question":"Ruošiatės įjungti 110 V pjūklą į ilgintuvą. Ką, pasak HSE (darbo saugos tarnybos), kur įmanoma, turėtumėte padaryti pirmiausia?","options":["Laikyti nuspaustą jungiklį, kad iš karto žinotumėte, jog jis veikia","Greitai įkišti kištuką, kad nebūtų kibirkšties","Įsitikinti, kad pjūklas išjungtas, ir išjungti lizdą","Nieko: išjungti reikia tik prieš ištraukiant kištuką"],"explanation":"Kur įmanoma, prieš įkišant ar ištraukiant kištuką ir įrankis, ir lizdas turi būti išjungti. Jei įrankis įjungtas, kai į jį paduodama srovė, jis gali netikėtai pasileisti.","why_not":{"0":"Jei įrankis įjungtas, kai į jį paduodama srovė, jis gali netikėtai pasileisti, todėl pirmiausia jį išjunkite.","1":"Greitis nepadeda, todėl prieš įkišdami kištuką išjunkite pjūklą ir lizdą.","3":"Išjunkite ir prieš įkišdami kištuką, ne tik prieš jį ištraukdami, kitaip įrankis gali staiga pasileisti."}},"safety-b3-14":{"question":"Jūsų prašo išmontuoti seną šviestuvą. Darbų vadovas sako: „Elektrikas man sakė, kad ta grandinė išjungta.“ Ką sako HSE (darbo saugos tarnyba)?","options":["Užtenka, kad jums pasakė, jog ji išjungta","Spustelėkite šviesos jungiklį: jei šviesa neužsidega, laiduose įtampos nėra","Prieš pradedant darbą žmogus, kuris išmano šį darbą, turi tinkama bandymo įranga įrodyti, kad įtampos nėra","Greitai palieskite laidus plaštakos nugarėle, kad patikrintumėte"],"explanation":"HSE (darbo saugos tarnyba) sako, kad vien to, jog jums pasakė, kad elektros įrangoje nėra įtampos, niekada negana. Atjungus įrangą, prieš pradedant darbą reikia įrodyti, kad įtampos nėra, ir tai turi daryti žmogus, kuris supranta, ką daro, ir naudoja tinkamą bandymo įrangą. Tai, kad šviesa neužsidega, neįrodo, kad laiduose nėra įtampos.","why_not":{"0":"HSE (darbo saugos tarnyba) sako, kad vien to, jog jums pasakė, kad įtampos nėra, niekada negana, todėl tai reikia įrodyti bandymo įranga.","1":"Tai, kad šviesa neužsidega, neįrodo, kad laiduose nėra įtampos, todėl reikia naudoti tinkamą bandymo įrangą.","3":"Niekada nelieskite laidų, kad patikrintumėte, nes kompetentingas žmogus turi tinkama bandymo įranga įrodyti, kad įtampos nėra."}},"safety-b3-15":{"question":"Laikinasis elektros kabelis turi kirsti transporto kelią (haul road), kuriuo važinėja savivarčiai ir sunkvežimiai. Ką, pasak HSE (darbo saugos tarnybos), reikėtų padaryti?","options":["Patiesti jį plokščiai ant kelio, kad ratai per jį pervažiuotų","Uždengti jį faneros lakštu","Priklijuoti jį prie kelio įspėjamąja juosta","Įdėti jį į kabelių kanalą bent 0,5 m po paviršiumi, su kabelio žymekliu kiekviename gale"],"explanation":"Kabelius reikia tiesti ten, kur jie greičiausiai nebus pažeisti. HSE (darbo saugos tarnyba) sako, kad kelią kertantis kabelis turi būti kabelių kanale su kabelio žymekliu kiekviename gale, o jei keliu važinėja transportas, kanalas turi būti bent 0,5 m po paviršiumi. Ant kelio gulintį kabelį, net po lenta ar juosta, ratai gali sutraiškyti.","why_not":{"0":"Per kabelį važiuojantys ratai gali jį sutraiškyti, todėl HSE (darbo saugos tarnyba) sako jį įdėti į kabelių kanalą po keliu.","1":"Lenta ant kelio neapsaugo kabelio nuo ratų, todėl naudokite kabelių kanalą bent 0,5 m gylyje.","2":"Juosta neapsaugo kabelio nuo ratų, todėl jis turi būti kabelių kanale bent 0,5 m gylyje."}},"safety-b3-16":{"question":"Stovite ant sustatomųjų kopėčių (stepladder) ir dirbate tinklo įtampos grąžtu, kuris turi gedimą. Kodėl čia net nedidelis elektros smūgis gali būti labai pavojingas?","options":["Galite nukristi nuo sustatomųjų kopėčių","Nedideli elektros smūgiai niekam negali pakenkti","Sustatomosios kopėčios iki dienos pabaigos bus su įtampa","Perdegs saugiklis statybvietės vagonėlyje"],"explanation":"HSE (darbo saugos tarnyba) sako, kad net nemirtini elektros smūgiai gali sukelti sunkių ir ilgalaikių traumų. Sugedusios įrangos elektros smūgis gali numesti jus nuo kopėčių, pastolių ar kitos platformos. Sugedusiais įrankiais naudotis negalima.","why_not":{"1":"Net nedideli elektros smūgiai gali sukelti sunkių ir ilgalaikių traumų, be to, dėl jų galite nukristi.","2":"Pavojus – kad dėl elektros smūgio galite nukristi, o ne kad sustatomosios kopėčios liks su įtampa.","3":"Tikrasis pavojus jums – nukristi nuo sustatomųjų kopėčių, o ne perdegęs saugiklis."}},"safety-b3-17":{"question":"Statybvietės mašina turi blokuojamą apsauginį gaubtą (interlocked guard). Ką tai reiškia?","options":["Gaubtas prisuktas varžtais ir niekada neatsidaro","Mašina negali pasileisti, kol gaubtas neuždarytas, o gaubto negalima atidaryti, kol mašina dar juda","Gaubtą galima atsegti, kai jis trukdo","Gaubtas naktį užrakina mašiną sandėlyje"],"explanation":"Blokuotė (interlock) susieja apsauginį gaubtą su mašina. HSE (darbo saugos tarnyba) paaiškina, kad mašina negali pasileisti, kol gaubtas neuždarytas, o gaubto negalima atidaryti, kol mašina dar juda. Niekada nebandykite apeiti blokuotės.","why_not":{"0":"Tai stacionarus gaubtas, o blokuojamą gaubtą (interlocked guard) galima atidaryti, kai mašina sustoja.","2":"Niekada neapeikite gaubto, nes blokuotė (interlock) neleidžia mašinai veikti, kol gaubtas atidarytas.","3":"Blokuotė (interlock) neturi nieko bendra su laikymu sandėlyje: ji susieja gaubtą su mašinos paleidimu."}},"safety-b3-18":{"question":"Stacionariu pjūklu (saw bench) pjaunate ploną medžio juostelę. Kad prastumtumėte paskutinę dalį, pirštai turėtų priartėti prie disko. Ką turėtumėte naudoti?","options":["Nykštį, laikydami jį plokščiai ant medžio","Storą pirštinę, kad diskas nuslystų","Nieko: tiesiog stumkite greičiau, kad ranka būtų prie disko trumpiau","Stumtuvą (push stick)"],"explanation":"Kur apsauginis gaubtas negali visiškai apsaugoti, HSE (darbo saugos tarnyba) sako naudoti tokias priemones kaip šablonai, laikikliai ir stumtuvai (push sticks). Stumtuvas laiko ranką atokiau nuo disko. Greitesnis stūmimas ar pirštinė pirštų nuo jo neatitraukia.","why_not":{"0":"Nykštys vis tiek būna arti disko, o stumtuvas (push stick) laiko ranką atokiau.","1":"Pirštinė disko nesustabdo, todėl naudokite stumtuvą (push stick), kad pirštai būtų atokiau.","2":"Stumiant greičiau, ranka vis tiek būna arti disko, todėl naudokite stumtuvą (push stick)."}},"safety-b3-20":{"question":"Ant grindų aplink statybvietės stacionarų pjūklą kaupiasi atraižos ir pjuvenos. Ką HSE (darbo saugos tarnyba) sako apie vietą aplink mašiną?","options":["Ją reikia sutvarkyti tik darbo pabaigoje","Pjuvenos ant grindų gerai, nes jos sugeria išsiliejusius skysčius","Ji turi būti švari ir tvarkinga, be daiktų, už kurių galima užkliūti ar ant kurių galima paslysti, ir gerai apšviesta","Švari turi būti tik pati mašina"],"explanation":"HSE (darbo saugos tarnyba) sako, kad darbo vieta aplink mašiną turi būti švari ir tvarkinga, be kliūčių ir be paslydimo ar užkliuvimo pavojų, ir gerai apšviesta. Tvarkykite dirbdami, o ne tik darbo pabaigoje.","why_not":{"0":"HSE (darbo saugos tarnyba) sako, kad vieta aplink mašiną turi būti švari ir tvarkinga, todėl tvarkykite dirbdami.","1":"Pjuvenos ant grindų kelia paslydimo ir užkliuvimo pavojų, todėl vieta turi būti švari ir tvarkinga.","3":"HSE (darbo saugos tarnyba) sako, kad švari ir tvarkinga turi būti visa darbo vieta aplink mašiną, ne tik pati mašina."}},"safety-b3-21":{"question":"Į statybvietę atvežtas išnuomotas grindų pjūklas. Tokias mašinas reikia tikrinti, bet jis atvežtas be patikrinimo ataskaitos, žymos ar etiketės. Kas turėtų būti daroma?","options":["Naudoti jį: nuomos įmonės visada tikrina savo mašinas","Nenaudoti jo, kol nežinote, kad patikrinimas atliktas","Naudoti jį, o ataskaitos paprašyti savaitės pabaigoje","Patiems ant jo užrašyti šiandienos datą"],"explanation":"HSE (darbo saugos tarnyba) sako, kad darbo įrangos, kurią reikia tikrinti, negalima naudoti, jei nežinote, kad patikrinimas atliktas. Iš nuomos įmonės gauta įranga turi turėti paskutinio patikrinimo įrodymą, pvz., ataskaitą, o mažesniems daiktams – žymą, spalvinį kodą ar etiketę.","why_not":{"0":"Nedarykite prielaidų, nes HSE (darbo saugos tarnyba) sako, kad išnuomota įranga turi turėti paskutinio patikrinimo įrodymą.","2":"Nenaudokite pirma, o klauskite vėliau, nes prieš naudodami turite žinoti, kad patikrinimas atliktas.","3":"Patiems užrašyta data nėra patikrinimas, todėl jį tikrai reikia patikrinti."}},"safety-b3-22":{"question":"Iškraunant betono maišyklė nukrito nuo sunkvežimio. Atrodo, kad ji vis dar veikia. Kas turėtų būti padaryta, prieš ja naudojantis?","options":["Naudoti ją: jei veikia, viskas gerai","Palaukti iki kito planinio patikrinimo datos","Nuvalyti ją ir dirbti toliau","Ją reikia patikrinti, nes nutiko kai kas, kas galėjo padaryti ją nesaugią"],"explanation":"Įrangą reikia tikrinti kaskart, kai nutinka kas nors, kas galėjo padaryti ją nesaugią, pvz., kai žinoma ar įtariama, kad ji rimtai pažeista. Vis dar veikianti mašina gali turėti nematomų pažeidimų, todėl ją reikia patikrinti, prieš kam nors ja naudojantis.","why_not":{"0":"Veikianti mašina vis tiek gali turėti nematomų pažeidimų, todėl pirmiausia ją reikia patikrinti.","1":"Nelaukite, nes įtarus rimtą pažeidimą, ją reikia patikrinti prieš kam nors ja naudojantis.","2":"Nuvalius paslėpti pažeidimai nerandami, todėl po tokio kritimo ją reikia patikrinti."}},"safety-b3-23":{"question":"Reikia pakelti sunkią grindinio plokštę. Arčiausiai po ranka – medžio kaltas. Ką turėtumėte daryti?","options":["Paimti tam darbui skirtą įrankį, pvz., plokščių kėliklį ar laužtuvą","Naudoti kaltą: vienai plokštei tiks","Įkalti kaltą po plokšte plaktuku","Vietoj kalto naudoti atsuktuvą"],"explanation":"Įstatymas sako, kad darbo įranga turi būti naudojama tik tiems darbams ir tokiomis sąlygomis, kuriems ji tinka. Kaip svertas naudojamas kaltas ar atsuktuvas gali lūžti ar nuslysti ir jus sužeisti. Naudokite tam darbui skirtą įrankį.","why_not":{"1":"Įrankiai turi būti naudojami tik tiems darbams, kuriems jie tinka, o kaip svertas naudojamas kaltas gali lūžti ar nuslysti.","2":"Įkalus kaltą po plokšte, vis tiek naudojamas netinkamas įrankis, ir jis gali lūžti ir jus sužeisti.","3":"Atsuktuvas kaip svertas ne ką geresnis, nes jis irgi gali lūžti ar nuslysti."}},"safety-b3-24":{"question":"Ką tik uždėjote naują diską ant šlifuoklio. Ką turėtumėte padaryti prieš pradėdami pjauti?","options":["Iš karto pradėti pjauti, kol diskas naujas","Trumpai paleisti jį visu greičiu, kai visi stovi atokiau","Lėtai paleisti jį prie ruošinio, kad įsidirbtų","Paprašyti bendradarbio priglausti ausį ir paklausyti"],"explanation":"HSE (darbo saugos tarnyba) sako, kad nauji ar iš naujo uždėti diskai prieš naudojimą turi trumpai pasisukti laisvai visu darbiniu greičiu, o per šį bandomąjį paleidimą visi turi stovėti atokiau. Apsauginiai gaubtai turi būti uždėti.","why_not":{"0":"HSE (darbo saugos tarnyba) sako pirmiausia trumpai paleisti naują diską laisvai visu greičiu, kai visi stovi atokiau.","2":"Neįdirbinėkite jo į ruošinį: pirmiausia paleiskite jį laisvai visu greičiu, kai visi stovi atokiau.","3":"Per bandomąjį paleidimą visi turi stovėti atokiau, o ne pasilenkti arti paklausyti."}},"safety-b3-26":{"question":"Kaip reikia laikyti plonus pjovimo diskus?","options":["Pakabintus ant vinies ant furgono sienos","Pastatytus ant briaunos ant drėgnos talpos dugno","Paguldytus ant tvirto, lygaus paviršiaus, toliau nuo karščio ir drėgmės","Palaidus įrankių krepšyje su kitais įrankiais"],"explanation":"HSE (darbo saugos tarnyba) sako, kad ploni pjovimo diskai turi būti paguldyti ant standaus, lygaus paviršiaus, toliau nuo per didelio karščio ir drėgmės, kad neišlinktų. Išlinkusio (warped) disko naudoti negalima.","why_not":{"0":"Pakabinti diskai gali išlinkti, todėl HSE (darbo saugos tarnyba) sako juos paguldyti ant tvirto, lygaus paviršiaus.","1":"Dėl drėgmės ir stovėjimo ant briaunos jie gali išlinkti, todėl paguldykite juos toliau nuo karščio ir drėgmės.","3":"Palaidi įrankių krepšyje jie gali sulinkti ar būti pažeisti, todėl paguldykite juos ant tvirto paviršiaus."}},"safety-b3-27":{"question":"HSE (darbo saugos tarnyba) sako, kad dauguma transporto nelaimingų atsitikimų statybvietėse kyla dėl vienos pagrindinės problemos. Kokios?","options":["Transporto priemonėms baigiasi kuras","Pėsčiųjų ir transporto priemonių judėjimas nepakankamai atskirtas","Statybvietėje per daug ženklų","Vairuotojai klausosi radijo"],"explanation":"HSE (darbo saugos tarnyba) sako, kad dauguma transporto nelaimingų atsitikimų statybose kyla dėl to, kad pėstieji ir transporto priemonės nepakankamai atskirti. Padeda atskiri pėsčiųjų takai, užtvaros ir tinkamos perėjos.","why_not":{"0":"HSE (darbo saugos tarnyba) sako, kad pagrindinė problema – nepakankamai atskirti pėstieji ir transporto priemonės, o ne kuras.","2":"Ženklai nėra problema, nes HSE (darbo saugos tarnyba) sako, kad problema – nepakankamai atskirti žmonės ir transporto priemonės.","3":"HSE (darbo saugos tarnyba) kaltina ne radiją, o tai, kad pėstieji ir transporto priemonės nepakankamai atskirti."}},"safety-b3-29":{"question":"Atvažiuojate į statybvietę savo furgonu. Greičiausia pasistatyti visai šalia vietos, kur dirba ekskavatorius. Ką HSE (darbo saugos tarnyba) sako apie darbuotojų automobilių stovėjimą?","options":["Statykite ten, kur arčiausiai jūsų darbo","Statykite darbo zonoje, bet palikite įjungtus avarinius žibintus","Stovėjimas – problema tik sunkvežimiams","Automobilių ir furgonų stovėjimo vieta turi būti atokiau nuo darbo zonos"],"explanation":"Kad būtų mažiau transporto priemonių, judančių ten, kur dirba žmonės, HSE (darbo saugos tarnyba) sako, kad darbuotojų ir lankytojų automobilių stovėjimo vieta turi būti atokiau nuo darbo zonos. Statykite tik jums parodytoje stovėjimo aikštelėje.","why_not":{"0":"HSE (darbo saugos tarnyba) sako, kad automobilių ir furgonų stovėjimo vieta turi būti atokiau nuo darbo zonos.","1":"Avariniai žibintai nepadaro to saugaus, nes stovėjimo vieta turi būti atokiau nuo darbo zonos.","2":"HSE (darbo saugos tarnyba) sako, kad ir darbuotojų automobilių bei furgonų stovėjimo vieta turi būti atokiau nuo darbo zonos."}},"safety-b3-30":{"question":"Savivartis (dumper) verčia gruntą (spoil) į iškasą. Kas, pasak HSE (darbo saugos tarnybos), turi būti įrengta, kad jis nenuvažiuotų per kraštą?","options":["Ratų atramos (wheel stops), įrengtos saugiu atstumu nuo krašto","Kūgių eilė visai prie krašto","Nieko, jei vairuotojas atsargus","Prie krašto stovintis bendradarbis, kuris šauktų, kada sustoti"],"explanation":"HSE (darbo saugos tarnyba) sako, kad ratų atramos (wheel stops) turi būti įrengtos saugiu atstumu nuo iškasų ir duobių kraštų, kad savivarčiai verčiant neįkristų. Kūgiai savivarčio nesustabdys, o prie krašto niekas neturi stovėti.","why_not":{"1":"Kūgiai savivarčio nesustabdys, todėl HSE (darbo saugos tarnyba) sako įrengti ratų atramas (wheel stops) saugiu atstumu nuo krašto.","2":"Vien atsargumo neužtenka, nes HSE (darbo saugos tarnyba) sako, kad ratų atramos (wheel stops) turi neleisti savivarčiams nuvažiuoti per kraštą.","3":"Prie krašto niekas neturi stovėti, nes HSE (darbo saugos tarnyba) sako, kad turi būti įrengtos ratų atramos (wheel stops)."}},"safety-b3-31":{"question":"Vairuojate statybvietės savivartį (dumper). Šį rytą stabdžiai atrodo silpnesni nei paprastai. Ką turėtumėte daryti?","options":["Važiuoti lėtai ir pasakyti apie tai savaitės pabaigoje","Pranešti apie tai: dėl saugos gedimo savivartis nenaudojamas, kol gedimas neištaisytas","Toliau juo naudotis, bet tik lygioje vietoje","Stipriau pumpuoti stabdžius ir važiuoti toliau"],"explanation":"HSE (darbo saugos tarnyba) sako, kad vairuotojai turi pranešti apie defektus ar problemas. Problemos turi būti greitai ištaisytos, o jei gedimas svarbus saugai (safety-critical), savivartis turi būti išimtas iš naudojimo. Stabdžiai yra svarbūs saugai.","why_not":{"0":"Stabdžiai svarbūs saugai, todėl praneškite dabar, ir savivartis nenaudojamas, kol gedimas neištaisytas.","2":"Silpni stabdžiai – saugos gedimas ant bet kokio pagrindo, todėl savivarčio (dumper) reikia nebenaudoti.","3":"Pumpuojant stabdžius gedimas neišnyksta, todėl praneškite, ir savivartis išimamas iš naudojimo."}},"safety-b3-32":{"question":"Teleskopinis krautuvas (telehandler) dirba su pakelta strėle. Kur, pasak HSE (darbo saugos tarnybos), vairuotojui gali būti didelė nematoma zona (blind spot)?","options":["Tiesiai virš kabinos","Tik už kairiojo galinio rato","Priekyje, dešinėje pusėje","Kai strėlė pakelta, nematomų zonų nėra"],"explanation":"HSE (darbo saugos tarnyba) įspėja, kad kai strėlė pakelta, teleskopinio krautuvo (telehandler) priekyje, dešinėje pusėje, gali būti didelė nematoma zona (blind spot). Matyti, kas už krautuvo, taip pat gali būti labai sunku. Laikykitės atokiau ir prieš prieidami įsitikinkite, kad vairuotojas žino, jog esate ten.","why_not":{"0":"HSE (darbo saugos tarnyba) įspėja apie didelę nematomą zoną (blind spot) priekyje, dešinėje pusėje, o ne virš kabinos.","1":"Ne tik už krautuvo: HSE (darbo saugos tarnyba) įspėja, kad kai strėlė pakelta, priekyje, dešinėje pusėje, būna didelė nematoma zona (blind spot).","3":"HSE (darbo saugos tarnyba) įspėja, kad kai strėlė pakelta, priekyje, dešinėje pusėje, gali būti didelė nematoma zona (blind spot)."}},"safety-b3-33":{"question":"Teleskopinio krautuvo (telehandler) vairuotojas važiuoja per statybvietę, aukštai ant šakių iškėlęs blokelių padėklą, kad atvažiavęs galėtų iš karto padėti jį ant pastolių. Ką sako HSE (darbo saugos tarnyba)?","options":["Viskas gerai, jei jis važiuoja lėtai","Taip saugiau, nes krovinys aukštai ir netrukdo žmonėms","Lygiu keliu viskas gerai","Važiuoti su pakeltu kroviniu pavojinga, ir to visada reikia vengti"],"explanation":"HSE (darbo saugos tarnyba) sako, kad važiuoti su pakeltu kroviniu pavojinga, ir to reikia vengti visada. HSE tai nurodo tarp atsargumo priemonių, kad krautuvas nepartrenktų žmonių ir neapvirstų. Lėtas važiavimas ar lygus kelias nepadaro to saugaus.","why_not":{"0":"Lėtas važiavimas nepadaro to saugaus, nes HSE (darbo saugos tarnyba) sako visada vengti važiuoti su pakeltu kroviniu.","1":"Tai nėra saugiau, nes HSE (darbo saugos tarnyba) sako, kad važiuoti su pakeltu kroviniu pavojinga, ir to visada reikia vengti.","2":"Lygus kelias nepadaro to saugaus, nes važiuoti su pakeltu kroviniu visada reikia vengti."}},"safety-b3-35":{"question":"Ekskavatorius krauna gruntą į savivartį sunkvežimį (tipper lorry). Darbininkas įlipa į sunkvežimio kėbulą, kad paskleistų krentantį gruntą. Kas teisinga?","options":["Viskas gerai, jei jis dėvi šalmą","Jis gali likti, jei laikosi kėbulo priekio","Jis turi išlipti: niekas neturi likti ant transporto priemonės, kai kraunamos birios medžiagos, nebent įrengta saugi darbo vieta","Viskas gerai, jei sunkvežimio vairuotojas lieka kabinoje"],"explanation":"Įstatymas sako, kad niekas neturi likti ant transporto priemonės, kai kraunamos ar iškraunamos birios medžiagos, nebent jam įrengta saugi darbo vieta ir ji išlaikoma saugi. Žmogų savivarčio kėbule gali pataikyti kaušas ar gruntas.","why_not":{"0":"Šalmas neapsaugos jo nuo kaušo ar grunto, todėl jis turi išlipti.","1":"Kėbulo priekis kraunant vis tiek yra transporto priemonėje, todėl jis turi išlipti.","3":"Nesvarbu, kur yra vairuotojas, nes kraunant niekas neturi likti kėbule."}},"safety-b3-37":{"question":"Prekių pristatymo vairuotojas laukia, kol teleskopinis krautuvas (telehandler) iškrauna jo sunkvežimį. Kur jis turėtų būti?","options":["Ant sunkvežimio kėbulo, padėdamas nukreipti šakes","Saugioje vietoje, skirtoje vairuotojams laukti","Stovėti visai prie sunkvežimio ir stebėti krovinį","Bet kur, jei jis dėvi ryškiaspalvius drabužius (hi-vis)"],"explanation":"HSE (darbo saugos tarnyba) sako, kad turi būti saugi vieta, kur vairuotojai galėtų laukti visą pakrovimo ir iškrovimo laiką. Pakrovimo zonoje neturi būti nė vieno, kas nedalyvauja darbe. Ryškiaspalviai drabužiai (hi-vis) padeda žmonėms jus pamatyti, bet nuo pavojaus neatitraukia.","why_not":{"0":"Jis neturi būti pakrovimo zonoje, nes HSE (darbo saugos tarnyba) sako, kad turi būti saugi vieta vairuotojams laukti.","2":"Stovėdamas visai prie sunkvežimio, jis atsiduria krovinio kelyje, todėl turėtų laukti saugioje vietoje.","3":"Ryškiaspalviai drabužiai (hi-vis) padeda žmonėms jus pamatyti, bet nuo pavojaus neatitraukia."}},"safety-b3-38":{"question":"Medžiagos laikomos ant statybvietės konteinerio stogo, ir žmonės lipa ten jų sukrauti ir paimti. Ko, pasak HSE (darbo saugos tarnybos), reikia?","options":["Ženklo „Būkite atsargūs“","Nieko: konteinerio stogas nėra toks aukštas, kad tai būtų svarbu","Tik kad lipantis žmogus būtų jaunas ir sportiškas","Apsauginių turėklų (guard rails), jei žmonės gali nukristi krovdami ar imdami medžiagas"],"explanation":"HSE (darbo saugos tarnyba) sako, kad jei medžiagos laikomos aukštyje, pvz., ant konteinerio stogo, turi būti įrengti apsauginiai turėklai (guard rails), jei žmonės gali nukristi krovdami ar imdami medžiagas ar įrangą. Ženklas niekam neleidžia nukristi.","why_not":{"0":"Ženklas niekam neleidžia nukristi, todėl HSE (darbo saugos tarnyba) sako, kad reikia apsauginių turėklų (guard rails).","1":"HSE (darbo saugos tarnyba) būtent konteinerio stogą nurodo kaip pavyzdį, kur reikia apsauginių turėklų (guard rails), jei žmonės gali nukristi.","2":"Jaunystė ir sportiškumas nuo kritimo neapsaugo, todėl reikia apsauginių turėklų (guard rails)."}},"safety-b3-39":{"question":"Pastato, kuriame dirbate, kampe kaupiasi kartoninės pakuotės ir medienos atraižos. Kodėl, pasak HSE (darbo saugos tarnybos), tokias atliekas reikia reguliariai išvežti?","options":["Kad sumažėtų gaisro rizika","Tik kad statybvietė lankytojams atrodytų tvarkinga","Kad savaitės pabaigoje susidarytų pakankamai didelė krūva sudeginti","Jų nereikia išvežti, kol darbas nebaigtas"],"explanation":"HSE (darbo saugos tarnyba) sako, kad visas degias atliekas, pvz., pakuotes ir medienos atraižas, reikia reguliariai išvežti, kad sumažėtų gaisro rizika. Taip pat dingsta daiktai, už kurių žmonės gali užkliūti.","why_not":{"1":"Tai ne tik išvaizdos reikalas, nes HSE (darbo saugos tarnyba) sako, kad išvežant degias atliekas, sumažėja gaisro rizika.","2":"Leidžiant susidaryti didelei krūvai, gaisro rizika didėja, todėl atliekas išvežkite reguliariai.","3":"HSE (darbo saugos tarnyba) sako, kad degias atliekas reikia išvežti reguliariai, o ne palikti iki pabaigos."}},"safety-s08":{"question":"Šis ženklas yra ant dažų sandėlio (paint store) durų. Jūsų paprašė viduje sutaisyti vamzdį dujiniu degikliu (gas torch). Ką darote?","options":["Naudokite degiklį, bet šalia laikykite gesintuvą","Nenaudokite degiklio viduje. Pasakykite darbų vadovui (supervisor)","Naudokite degiklį, nes ženklas skirtas tik rūkymui","Naudokite degiklį, jei paliksite duris atviras"],"explanation":"Apvalus ženklas su raudonu kraštu ir raudona įstriža linija reiškia, kad kažko daryti NEGALIMA. Juodas paveikslėlis rodo, ką daryti draudžiama. Čia jis rodo cigaretę ir degantį degtuką, todėl draudžiama ir rūkyti, ir naudoti atvirą liepsną (naked flames). Dujinis degiklis dega atvira liepsna. Gesintuvas šalia ar atviros durys to neleidžia. Sustokite ir pasakykite darbų vadovui (supervisor), kad darbą būtų galima atlikti kitu būdu.","why_not":{"0":"Gesintuvas gesina jau kilusį gaisrą; šis draudimas neleidžia jam kilti.","2":"Vien rūkymo draudimas (no smoking) rodytų tik cigaretę; čia dar yra degantis degtukas.","3":"Ženklas su degtuku ir cigarete neturi išimties atviroms durims."}},"safety-s14":{"question":"Šis ženklas yra toje vietoje, kur ketinate pusę minutės dirbti šlifuokliu (grinder). Ką privalote daryti?","options":["Prieš pradėdami užsidėkite akių apsaugos priemones","Nieko, nes darbas toks trumpas","Akių apsaugos priemones dėvėkite tik tada, jei daug dulkių","Vietoj to laikykite veidą nusuktą"],"explanation":"Apvalus mėlynas ženklas su baltu paveikslėliu rodo, ką PRIVALOTE daryti. Čia jis rodo galvą su apsauginiais akiniais (goggles), todėl privaloma dėvėti akių apsaugos priemones. Nesvarbu, kiek trumpai truks darbas. Nusukti veidą nėra tas pats, kas apsaugoti akis.","why_not":{"1":"Ženklas su apsauginiais akiniais (goggles) neturi laiko ribos; net kelios šlifavimo sekundės reikalauja akių apsaugos.","2":"Taisyklei „tik kai daug dulkių“ reikėtų užrašo lentelėje; čia jo nėra.","3":"Šlifuoklio kibirkštys ir skeveldros skrieja nenuspėjamai ir gali pataikyti į akis iš šono."}},"specialist-b1-01":{"question":"Dirbate sename pastate. Kaip galite sužinoti, ar ore yra asbesto pluoštų?","options":["Negalite sužinoti. Jų negalima pamatyti, užuosti ar pajusti","Ore jaučiamas chemikalų kvapas","Pamatysite baltą dulkių debesį","Iš karto pradėsite kosėti"],"explanation":"Asbesto pluoštai daug per maži, kad juos pamatytumėte, ir jie neturi kvapo. Jų negalite pajusti nei ore, nei ant drabužių. Todėl jūsų pojūčiai jūsų neįspės. Kvapas, dulkių debesis ar kosulys nepasako, ar asbestas yra, ar ne.","why_not":{"1":"Asbesto pluoštai neturi kvapo. Jų negalite pamatyti, užuosti ar pajusti.","2":"Asbesto pluoštai per maži, kad juos pamatytumėte. Žiūrėdami negalite nustatyti, ar jų yra.","3":"Kūnas jokio įspėjimo neduoda. Asbesto pluoštų negalite pamatyti, užuosti ar pajusti."}},"specialist-b1-02":{"question":"Jūsų įmonė turi darbų keturiuose pastatuose. Kuriame iš jų labiausiai tikėtina rasti asbesto?","options":["Mokykloje, pastatytoje 1972 metais","Name, pastatytame 2015 metais","Sandėlyje, pastatytame 2021 metais","Biurų pastate, pastatytame 2008 metais"],"explanation":"Asbestas buvo naudojamas pastatuose, kol 1999 metais buvo uždraustas. Pastatuose, pastatytuose po 2000 metų, jo tikriausiai nėra. Mokykla – vienintelis čia pastatas, pastatytas iki 2000 metų, todėl joje labiausiai tikėtina rasti asbesto.","why_not":{"1":"Šis namas pastatytas po 2000 metų. Po 2000 metų pastatytuose pastatuose asbesto tikriausiai nėra.","2":"Šis sandėlis pastatytas po 2000 metų. Po 2000 metų pastatytuose pastatuose asbesto tikriausiai nėra.","3":"Šis biurų pastatas pastatytas po 2000 metų. Po 2000 metų pastatytuose pastatuose asbesto tikriausiai nėra."}},"specialist-b1-04":{"question":"Prieš pradedant jūsų darbą buvo atliktas asbesto tyrimas (asbestos survey). Kambaryje, kuriame dirbate, asbesto nerasta. Ką turėtumėte nepamiršti?","options":["Asbestas vis tiek gali būti paslėptas, todėl būkite budrūs ir sustokite, jei rasite medžiagą, dėl kurios nesate tikri","Dabar tikrai žinoma, kad kambaryje asbesto nėra","Galite gręžti ir pjauti bet kur kambaryje, negalvodami apie asbestą","Jei rasite medžiagą, dėl kurios nesate tikri, dirbkite toliau, nes tyrimas visada teisus"],"explanation":"Tyrimas (survey) gali nerasti visų vietų, kur yra asbesto. Jo gali būti paslėpta sienose, grindyse ar lubose. Todėl dirbdami vis stebėkite. Jei randate medžiagą, kurioje, jūsų manymu, gali būti asbesto, nutraukite darbą ir pasakykite darbdaviui.","why_not":{"1":"Tyrimas (survey) gali nerasti viso asbesto. Dalis jo kambaryje vis tiek gali būti paslėpta.","2":"Asbestas gali būti paslėptas net atlikus tyrimą (survey). Dirbdami vis stebėkite.","3":"Tyrimai (surveys) gali praleisti asbestą. Jei randate medžiagą, dėl kurios nesate tikri, nutraukite darbą."}},"specialist-b1-05":{"question":"Kasate rankomis, kad atidengtumėte požeminį elektros kabelį. Kaip turėtumėte naudoti kastuvą?","options":["Švelniai įspausti jį į žemę koja","Smarkiai smeigti žemyn, kad perkirstų akmenis","Jėga mesti į žemę, kad įsmigtų giliai","Pakeisti jį kirtikliu, kad minkštame grunte kastumėte greičiau"],"explanation":"Prie požeminių kabelių naudokite kastuvą ar semtuvą (izoliuotą, geriausia su lenktu kraštu) ir švelniai įspauskite jį koja. Smarkiai smeigiant ar metant kastuvas gali įsikirsti tiesiai į kabelį. HSE (darbo saugos tarnyba) sako, kad minkštame grunte prie požeminių komunikacijų kirtiklių naudoti negalima.","why_not":{"1":"Smarkiai smeigiamas kastuvas gali įsikirsti į kabelį. Švelniai įspauskite jį koja.","2":"Jėga metamas kastuvas gali perkirsti kabelį. HSE (darbo saugos tarnyba) sako jį švelniai įspausti.","3":"HSE (darbo saugos tarnyba) sako, kad minkštame grunte prie požeminių komunikacijų kirtiklių naudoti negalima."}},"specialist-b1-06":{"question":"Esate tranšėjoje, kurioje atidengtas dujų vamzdis. Kaip turėtumėte išlipti?","options":["Išlipti tinkamu išėjimu ir nestovėti ant vamzdžio bei už jo nesilaikyti","Užlipti ant vamzdžio, nes jis pakankamai tvirtas","Laikytis už vamzdžio ir prisitraukti aukštyn","Stovėti ant vamzdžio tik tada, jei jis metalinis"],"explanation":"Atidengtų vamzdžių ir kabelių niekada negalima naudoti kaip laiptelio ar ranktūrio. Jūsų svoris gali juos pažeisti, o pažeistas dujų vamzdis gali praleisti dujas. Iš tranšėjos lipkite kopėčiomis ar kitu saugiu išėjimu.","why_not":{"1":"Atidengtų vamzdžių niekada negalima naudoti kaip laiptelio. Jūsų svoris gali pažeisti vamzdį.","2":"Atidengtų vamzdžių niekada negalima naudoti kaip ranktūrio. Verčiau išlipkite tinkamu išėjimu.","3":"Jokio atidengto vamzdžio negalima naudoti kaip laiptelio, kad ir iš ko jis būtų pagamintas."}},"specialist-b1-08":{"question":"Statybvietėje vairuojate savivartį sunkvežimį (tipper lorry). Jūsų kelias eina po elektros linija virš galvos (overhead power line), per pervažą, pažymėtą vartais (goalposts). Ką privalote daryti?","options":["Nuleisti kėbulą ir likti žemiau vartų skersinio aukščio","Pravažiuoti greitai, kad po linija būtumėte trumpiau","Truputį pakelti kėbulą, kad krovinys nenuslystų","Apvažiuoti vartus iš šono, kad sutaupytumėte laiko"],"explanation":"Vartai (goalposts) žymi saugią vietą pravažiuoti po linija. Ženklai prie pervažos nurodo skersinio aukštį. Vairuotojai turi nuleisti strėles (jibs, booms) ir savivarčių kėbulus ir pravažiuodami likti žemiau to aukščio. Apvažiuodami vartus išvažiuojate iš saugios pervažos.","why_not":{"1":"Greitis jūsų neapsaugo. Privalote nuleisti kėbulą ir likti žemiau vartų (goalposts) skersinio aukščio.","2":"Pakeltas kėbulas gali pasiekti liniją. Pravažiuodami vairuotojai turi nuleisti savivarčių kėbulus.","3":"Vartai (goalposts) žymi saugią pervažą. Apvažiuodami juos iš jos išvažiuojate."}},"specialist-b1-10":{"question":"Signalizuotojas (signaller) nukreipia mašiną. Staiga jis iškelia abi rankas tiesiai aukštyn, delnais į priekį. Ką tai reiškia?","options":["Pavojus: avarinis sustojimas","Pradžia: pasiruoškite mano signalams","Kelti krovinį","Darbas baigtas"],"explanation":"Įstatyme apie saugos ženklus ir signalus abi rankos aukštyn delnais į priekį yra pavojaus signalas: tuoj pat sustokite. Pradžia – abi rankos ištiestos į šonus. Kelti – dešinė ranka nukreipta aukštyn ir lėtai suka ratą. Darbas baigtas – abi rankos sudėtos kartu krūtinės aukštyje.","why_not":{"1":"Pradžia rodoma abiem rankomis, ištiestomis į šonus, o ne iškeltomis aukštyn.","2":"Kelti rodoma dešine ranka, nukreipta aukštyn ir lėtai sukančia ratą.","3":"Darbas baigtas rodoma abiem rankomis, sudėtomis kartu krūtinės aukštyje."}},"specialist-b1-11":{"question":"Vairuojate mašiną, ir jus nukreipia signalizuotojas (signaller). Jis duoda jums signalą, kurio negalite saugiai įvykdyti. Ką turėtumėte daryti?","options":["Sustabdyti judėjimą ir paprašyti naujų nurodymų","Vis tiek vykdyti signalą, nes signalizuotojas yra atsakingas","Dirbti toliau taip, kaip manote geriausia, niekam nesakydami","Vykdyti signalą, bet lėtai"],"explanation":"Įstatymas sako, kad operatorius turi sustabdyti judėjimą ir paprašyti naujų nurodymų, kai negali saugiai įvykdyti komandos. Signalizuotojas jus nukreipia, bet jūs negalite daryti to, ką žinote esant nesaugu. Daryti tai lėtai vis tiek nesaugu, o keisdami planą nepasakę signalizuotojui keliate pavojų žmonėms.","why_not":{"1":"Jei signalo negalite saugiai įvykdyti, įstatymas sako, kad turite sustoti ir paprašyti naujų nurodymų.","2":"Nesielkite savaip. Sustabdykite judėjimą ir paprašykite signalizuotojo (signaller) naujų nurodymų.","3":"Daryti lėtai vis tiek nesaugu. Turite sustabdyti judėjimą ir paprašyti naujų nurodymų."}},"specialist-b1-12":{"question":"Įstatymas apie saugos ženklus ir signalus nustato, kaip turi skambėti signalas, liepiantis žmonėms evakuotis. Ką jis sako?","options":["Jis turi būti nepertraukiamas (skamba be pertraukų)","Jis turi būti trys trumpi pyptelėjimai, tada tyla","Jis turi būti vienas trumpas pyptelėjimas","Jis turi būti tylus, kad neišgąsdintų žmonių"],"explanation":"Saugos ženklų ir signalų taisyklės (Safety Signs and Signals Regulations) sako, kad evakuacijos signalas turi būti nepertraukiamas. Pavojaus signalai taip pat turi būti daug garsesni už aplinkos triukšmą, todėl tylus garsas netinka. Statybvietės instruktaže (induction) jums turėtų būti pasakyta, kaip skamba jūsų statybvietės signalas.","why_not":{"1":"Įstatymas sako, kad evakuacijos signalas turi būti nepertraukiamas, o ne pyptelėjimai su pertraukomis.","2":"Vienas trumpas pyptelėjimas nėra nepertraukiamas signalas. Evakuacijos signalas turi skambėti be pertraukų.","3":"Pavojaus signalai turi būti daug garsesni už aplinkos triukšmą, kad žmonės juos išgirstų."}},"specialist-b1-14":{"question":"Ruošiatės pjauti blokelius patalpoje. Dulkės gali suaktyvinti kambaryje esantį dūmų detektorių. Ką turėtumėte daryti?","options":["Mažinti dulkes ar jas nutraukti ir palikti detektorių veikiantį","Užmauti ant detektoriaus maišelį, kol baigsite","Nuimti detektorių visai dienai","Pasakyti visiems nekreipti dėmesio į signalizaciją, jei ji suskambės"],"explanation":"HSE (darbo saugos tarnyba) sako, kad nepriimtina uždengti ar išjungti dūmų detektorius dėl to, kad darbas kelia dulkes. Uždengtas detektorius negali niekieno įspėti apie tikrą gaisrą. Vietoj to kontroliuokite dulkes, pvz., vandeniu ar nutraukimu. Nekreipti dėmesio į signalizaciją niekada nėra saugu.","why_not":{"1":"HSE (darbo saugos tarnyba) sako, kad uždengti dūmų detektorius dėl dulkių nepriimtina. Verčiau mažinkite dulkes.","2":"Nuėmus detektorių, jis negali įspėti apie tikrą gaisrą. Verčiau kontroliuokite dulkes.","3":"Nekreipti dėmesio į signalizaciją niekada nėra saugu. Tai gali būti tikras gaisras."}},"specialist-b1-15":{"question":"Jums duotas darbų leidimas (permit to work) pavojingam darbui. Kas teisinga?","options":["Vien leidimas nepadaro darbo saugaus. Vis tiek turite įvykdyti jame nurodytas atsargumo priemones","Kai turite leidimą, darbas saugus","Leidimas reiškia, kad darbą galite atlikti kaip tik norite","Leidimas – tik popierius, todėl jo skaityti nereikia"],"explanation":"Darbų leidime (permit to work) nurodyta, kaip pavojingą darbą reikia atlikti saugiai ir kas jį gali atlikti. Vien turėti popierių nepadaro darbo saugaus. Darbas saugus tik tada, kai darbą ruošiantys, prižiūrintys ir atliekantys žmonės įvykdo atsargumo priemones.","why_not":{"1":"Vien darbų leidimas (permit to work) nepadaro darbo saugaus. Atsargumo priemones reikia įvykdyti.","2":"Darbų leidime (permit to work) nurodyta, kaip darbą reikia atlikti saugiai. Turite jo laikytis.","3":"Darbų leidimas (permit to work) – ne tik popierius. Turite jį perskaityti ir įvykdyti jame nurodytas atsargumo priemones."}},"specialist-b1-18":{"question":"Kuris iš šių darbų laikomas karštuoju darbu (hot work)?","options":["Metalo pjovimas kampiniu šlifuokliu su pjovimo disku (disc cutter, grinder)","Sienos dažymas voleliu","Grindinio plytelių klojimas","Tranšėjos kasimas kastuvu"],"explanation":"Karštasis darbas (hot work) – tai bet koks darbas, kurio metu atsiranda liepsna, kibirkštys ar karštis. Šlifuojant ir pjaunant metalą lekia karštos kibirkštys, kurios gali sukelti gaisrą, todėl tai karštasis darbas. Suvirinimas, stogo dangos lydymas degikliu (torch-on roofing) ir darbas karšto oro pūstuvais irgi yra karštieji darbai.","why_not":{"1":"Dažant voleliu neatsiranda liepsnos, kibirkščių ar karščio, todėl tai ne karštasis darbas (hot work).","2":"Klojant plyteles neatsiranda liepsnos, kibirkščių ar karščio, todėl tai ne karštasis darbas (hot work).","3":"Kasant kastuvu neatsiranda liepsnos, kibirkščių ar karščio, todėl tai ne karštasis darbas (hot work)."}},"specialist-b1-19":{"question":"Ką tik baigėte suvirinti statybvietėje. Kiek laiko kas nors turėtų nuolat stebėti, ar toje vietoje nekyla gaisras?","options":["Bent valandą po karštųjų darbų pabaigos","Penkias minutes","Kol susidėsite įrankius","Stebėti nereikia, jei nematote liepsnos"],"explanation":"Medžiagos gali ilgai rusenti, kol užsiliepsnoja. HSE (darbo saugos tarnyba) sako, kad kas nors turėtų nuolat stebėti vietą bent valandą po karštųjų darbų (hot work) pabaigos, o tada dar kartą ją patikrinti po dviejų valandų. Todėl karštieji darbai turėtų baigtis bent dvi valandos prieš darbo dienos pabaigą.","why_not":{"1":"Penkios minutės – gerokai per trumpai. Stebėkite vietą bent valandą po karštųjų darbų (hot work).","2":"Įrankiai susidedami per greitai. Medžiagos gali rusenti, todėl stebėkite bent valandą.","3":"Medžiagos gali rusenti be liepsnos. Kas nors turėtų stebėti bent valandą po karštųjų darbų (hot work)."}},"specialist-b1-22":{"question":"Visą popietę dirbsite vienas tolimame didelės statybvietės kampe. Dėl ko reikėtų susitarti, prieš pradedant?","options":["Kaip ir kada palaikysite ryšį, pvz., skambučiais nustatytu laiku","Nieko, jei jūsų telefonas yra krepšyje","Kad skambinsite tik tada, jei baigsite anksčiau","Kad kitą rytą kas nors jūsų ieškos, jei jūsų nebus"],"explanation":"Kai dirbate vienas, šalia gali nebūti nieko, kas padėtų, jei kas nors nutiktų. HSE (darbo saugos tarnyba) sako, kad turi būti reguliarus ryšys iš anksto sutartu laiku, pvz., telefonu ar racija, ir patikimas būdas patikrinti, ar baigę darbą saugiai grįžote. Vien turėti telefoną neužtenka, jei niekas nelaukia jūsų skambučio.","why_not":{"1":"Telefono krepšyje neužtenka. Susitarkite dėl nustatyto laiko, kada palaikysite ryšį.","2":"Reikia reguliaraus ryšio sutartu laiku, o ne vieno skambučio, jei baigsite anksčiau.","3":"Kitą rytą – gerokai per vėlu. Susitarkite dėl reguliaraus ryšio ir patikrinimo, ar saugiai grįžote."}},"specialist-b1-23":{"question":"Bendradarbiui skauda galvą, ir jis statybvietės pirmosios pagalbos vaistinėlėje ieško vaistų nuo skausmo. Ką HSE (darbo saugos tarnyba) rekomenduoja dėl tablečių ir vaistų?","options":["Jų nereikėtų laikyti pirmosios pagalbos vaistinėlėje","Kiekvienoje pirmosios pagalbos vaistinėlėje privalo būti vaistų nuo skausmo","Įdėti juos į vaistinėlę gali tik statybvietės vadovas","Juos galima laikyti vaistinėlėje, jei jų galiojimo laikas nepasibaigęs"],"explanation":"HSE (darbo saugos tarnyba) rekomenduoja nelaikyti tablečių ir vaistų pirmosios pagalbos vaistinėlėje. Pirmosios pagalbos vaistinėlėje laikomi tokie dalykai kaip pleistrai, tvarsčiai, binto ritinėliai, akių pagalvėlės ir vienkartinės pirštinės. Įstatyme nėra nustatyto sąrašo, kas turi būti kiekvienoje vaistinėlėje; tai priklauso nuo darbo rizikos.","why_not":{"1":"Nustatyto vaistinėlės turinio sąrašo nėra, o HSE (darbo saugos tarnyba) rekomenduoja nelaikyti joje tablečių.","2":"HSE (darbo saugos tarnyba) rekomenduoja apskritai nelaikyti tablečių ir vaistų pirmosios pagalbos vaistinėlėje.","3":"Galiojimo laikas nieko nekeičia. HSE (darbo saugos tarnyba) rekomenduoja nelaikyti vaistų vaistinėlėje."}},"specialist-b1-24":{"question":"Esate naujas statybvietėje. Kaip paprastai sužinotumėte, kas yra pirmosios pagalbos teikėjai (first-aiders) ir kur yra pirmosios pagalbos vaistinėlė?","options":["Iš darbdavio iškabintų skelbimų, kuriuose tai nurodyta","Sužinote tik po nelaimingo atsitikimo","Jums nereikia žinoti. Žinoti reikia tik pirmosios pagalbos teikėjams","Iš HSE (darbo saugos tarnybos) svetainės"],"explanation":"Darbdavys turi jums pasakyti, kaip organizuojama pirmoji pagalba. Paprastai užtenka skelbimų, kuriuose nurodyta, kas yra pirmosios pagalbos teikėjai (first-aiders) ir kur jie yra, ir kur yra pirmosios pagalbos vaistinėlė. Jei jums sunku skaityti angliškai, darbdavys turėtų šią informaciją jums pateikti kitu būdu.","why_not":{"1":"Darbdavys turi pasakyti jums apie pirmąją pagalbą anksčiau, nei kas nors nutinka, paprastai skelbimais.","2":"Žinoti turi visi. Darbdavys turi pasakyti visiems darbuotojams, kaip organizuojama pirmoji pagalba.","3":"Kiekviena statybvietė turi savo pirmosios pagalbos teikėjus (first-aiders). Darbdavys jums tai pasako, paprastai skelbimais statybvietėje."}},"specialist-b1-25":{"question":"Mažoje statybvietėje nėra apmokyto pirmosios pagalbos teikėjo, bet yra pirmajai pagalbai „paskirtas asmuo“ (appointed person). Koks paskirto asmens darbas?","options":["Prižiūrėti pirmosios pagalbos priemones ir, kai reikia, kviesti skubiosios pagalbos tarnybas","Teikti visą pirmąją pagalbą, lygiai kaip apmokytas pirmosios pagalbos teikėjas","Spręsti, ar sužeisti žmonės gali dirbti toliau","Gydyti traumas vaistais iš pirmosios pagalbos vaistinėlės"],"explanation":"Paskirtas asmuo (appointed person) atsakingas už pirmosios pagalbos organizavimą. Jis prižiūri pirmosios pagalbos priemones ir, kai reikia, kviečia skubiosios pagalbos tarnybas. Jam nereikia pirmosios pagalbos mokymų, todėl jis nėra tas pats, kas apmokytas pirmosios pagalbos teikėjas (first-aider).","why_not":{"1":"Paskirtam asmeniui (appointed person) nereikia pirmosios pagalbos mokymų, todėl jis nėra apmokytas pirmosios pagalbos teikėjas (first-aider).","2":"Jo darbas – prižiūrėti pirmosios pagalbos priemones ir kviesti pagalbą, o ne spręsti, kas gali dirbti.","3":"Paskirtam asmeniui (appointed person) nereikia pirmosios pagalbos mokymų. Jo darbas – priemonės ir pagalbos kvietimas."}},"specialist-b2-01":{"question":"Bendradarbis sako: „Pernai įkvėpiau asbesto dulkių ir vis dar jaučiuosi gerai, vadinasi, man tai nepakenkė.“ Kas yra tiesa?","options":["Asbesto ligos paprastai pasireiškia po daugelio metų (dažnai po dešimtmečių), ir jų išgydyti neįmanoma","Jei po metų vis dar jaučiatės gerai, esate saugus","Asbestas pakenkia tik tada, jei tą pačią dieną pasijuntate blogai","Asbesto ligas lengva išgydyti, jei gydytojas jas anksti nustato"],"explanation":"Tai, kad dabar jaučiatės gerai, nieko neįrodo. Ligos, kurias sukelia įkvėptos asbesto skaidulos, paprastai išsivysto per dešimtmečius, o tada jų jau neįmanoma išgydyti. Todėl niekada nerizikuokite su asbesto dulkėmis, net jei atrodo, kad niekas nesuserga.","why_not":{"1":"Asbesto ligos paprastai pasireiškia po dešimtmečių, todėl tai, kad po metų jaučiatės gerai, nieko neįrodo.","2":"Asbesto žala nepasireiškia tą pačią dieną. Ligos paprastai išsivysto per dešimtmečius.","3":"Asbesto ligų išgydyti neįmanoma."}},"specialist-b2-02":{"question":"Patalpos, kurią dažote, lubos yra iš asbesto plokščių. Jos geros būklės, ir jūsų darbas jų neliečia. Kas yra tiesa?","options":["Kol jų niekas neliečia, rizika maža. Pavojus atsiranda, jei jos gręžiamos, laužomos ar pažeidžiamos","Jos visą laiką skleidžia kenksmingas skaidulas, todėl patalpoje niekas niekada negali dirbti","Kadangi jos geros būklės, saugu jose išgręžti kelias mažas skyles","Turėtumėte jas išlaužti ir sudėti į maišus, kad patalpa būtų saugi"],"explanation":"Geros būklės asbestas, kurio niekas neliečia, kelia mažą riziką. Skaidulos išsiskiria, kai jis pažeidžiamas, pvz., gręžiamas, pjaunamas, laužomas ar gadinamas, ir tada žmonės jas įkvepia. Todėl jo nelieskite ir niekada patys jo negręžkite ir nelaužykite.","why_not":{"1":"Geros būklės asbestas, kurio niekas neliečia, kelia mažą riziką. Pavojus atsiranda, kai jis pažeidžiamas.","2":"Gręžiant asbestas pažeidžiamas ir išsiskiria skaidulos, net jei jis geros būklės.","3":"Laužant išsiskiria skaidulos. Jei geros būklės asbesto niekas neliečia, rizika maža."}},"specialist-b2-04":{"question":"Požeminių komunikacijų plane kabelis pažymėtas 1 metro gylyje. Jūsų duobė turi būti tik 40 cm gylio. Ką turėtumėte galvoti?","options":["Planai ne visada tikslūs, o žemės lygis galėjo pasikeisti, todėl kabelis gali būti daug arčiau paviršiaus","Kabelis tikrai gerokai žemiau jūsų duobės, todėl galite kasti kaip norite","Kabeliai niekada nebūna seklau nei 1 metras","Planas yra oficialus dokumentas, todėl jis visada teisingas"],"explanation":"Komunikacijų planai padeda, bet jie ne visada nubraižyti tiksliai, ir atstumais ar gyliais juose negalima pasitikėti. Nuo plano sudarymo žemės lygis taip pat galėjo būti pakeltas ar pažemintas. Kabelis, pažymėtas 1 metro gylyje, gali būti daug sekliau, todėl vis tiek jį suraskite ir kaskite atsargiai.","why_not":{"1":"Planai ne visada tikslūs, todėl kabelis gali būti daug sekliau. Kaskite atsargiai.","2":"Tokios taisyklės nėra. Kabelis gali būti daug arčiau paviršiaus nei 1 metras.","3":"Planai ne visada nubraižyti tiksliai. HSE (darbo saugos tarnyba) sako gyliais juose nepasitikėti."}},"specialist-b2-06":{"question":"Užpylus tranšėją liko šiek tiek geltonos kabelių įspėjamosios juostos. Bendradarbis nori ją apjuosti aplink kitą atvirą tranšėją kaip užtvarą. Kas teisinga?","options":["Nenaudoti jos kaip užtvaros. Įspėjamoji juosta skirta tik tam, kad būtų vėl padėta virš požeminių komunikacijų","Naudoti, nes geltona juosta gerai matoma","Naudoti, bet tik per naktį","Įmesti ją į tranšėją, kai ji užpilama, kad jos atsikratytumėte"],"explanation":"Kai tranšėja užpilama, įspėjamoji juosta ir plytelės vėl dedamos virš komunikacijų, kurias jos žymi. Juostos negalima naudoti niekam kitam, pvz., tranšėjai aptverti, ir jos negalima įmesti į tranšėją ją užpilant. Ne vietoje esanti juosta gali suklaidinti vėliau kasantį žmogų.","why_not":{"1":"Įspėjamoji juosta skirta tik požeminėms komunikacijoms žymėti. Jos negalima naudoti tranšėjai aptverti.","2":"Įspėjamosios juostos negalima naudoti niekam kitam, jokiu paros metu.","3":"HSE (darbo saugos tarnyba) sako nemesti įspėjamosios juostos į tranšėją ją užpilant."}},"specialist-b2-08":{"question":"Turite pernešti ilgas kopėčias per vietą, virš kurios eina elektros linijos. Kaip turėtumėte jas nešti?","options":["Gulsčiai (horizontaliai) ir žemai, arti žemės","Stačiai, nes taip lengviau laikyti","Ant peties, priekiniu galu į viršų, kad nekliudytų žmonių galvoms","Stačiai, bet po laidais eiti greitai"],"explanation":"Šalia elektros linijų virš galvos (overhead power lines) ilgus daiktus, pvz., kopėčias, stulpus ir vamzdžius, neškite gulsčiai ir arti žemės. Tada jokia jų dalis negali pasiekti laidų. Nešant stačiai ar galu į viršų, viršutinis galas gali pasiekti laidus arba priartėti tiek, kad elektra peršoktų.","why_not":{"1":"Nešant stačiai, viršutinis kopėčių galas gali pasiekti laidus. Neškite jas gulsčiai ir žemai.","2":"Nešant galu į viršų, jis gali priartėti prie laidų. Neškite kopėčias gulsčiai ir arti žemės.","3":"Greitas ėjimas nepadeda. Stačiai nešamos kopėčios vis tiek gali pasiekti laidus."}},"specialist-b2-09":{"question":"Statybvietėje matote žemą siją, nudažytą įstrižomis geltonomis ir juodomis juostomis. Ką šios juostos jums sako?","options":["Būkite atsargūs: čia yra pavojus, pvz., kliūtis, į kurią galite atsitrenkti, kritimo vieta ar kas nors, kas gali nukristi","Čia saugi vieta stovėti","Tai kelias į avarinį išėjimą","Ši zona skirta tik transportui"],"explanation":"Įstrižos geltonos ir juodos juostos (arba raudonos ir baltos) žymi vietas, kur galite atsitrenkti į kliūtį, nukristi ar būti sužeisti krentančio daikto. Žema sija taip pažymima, kad žmonės ją pamatytų ir į ją neatsitrenktų.","why_not":{"1":"Šios juostos įspėja apie pavojų, pvz., atsitrenkti į ką nors ar nukristi. Jos nežymi saugios vietos.","2":"Evakuacijos keliai žymimi žaliais ženklais, o ne geltonomis ir juodomis juostomis.","3":"Juostos įspėja apie pavojų atsitrenkti į ką nors ar nukristi, o ne žymi transporto zoną."}},"specialist-b2-10":{"question":"Esate signalizuotojas (signaller), nukreipiantis krano kėlimą. Įpusėjus bendradarbis paprašo padėti jam panešti lentų. Ką turėtumėte daryti?","options":["Atsisakyti. Kol signalizuojate, jūsų vienintelis darbas – nukreipti kėlimą ir saugoti netoliese esančius žmones","Greitai jam padėti. Krano operatorius gali palaukti su kroviniu ore","Padėti jam ir toliau duoti signalus laisva ranka","Pasakyti krano operatoriui tęsti be signalų, kol grįšite"],"explanation":"Įstatymas sako, kad signalizuotojo (signaller) pareigos turi būti tik nukreipti judesius ir saugoti netoliese esančius darbuotojus. Jei nustojate stebėti, kad atliktumėte kitą darbą, krovinio niekas nenukreipia. Pirmiausia užbaikite kėlimą arba tegul su lentomis padeda kitas žmogus.","why_not":{"1":"Signalizuotojo (signaller) vienintelis darbas – nukreipti kėlimą ir saugoti darbuotojus. Nepalikite jo.","2":"Dirbdami kitą darbą, negalite tinkamai nukreipti kėlimo. Nukreipti jį turi būti vienintelė jūsų užduotis.","3":"Krovinio niekas nenukreiptų. Jūsų vienintelis darbas – nukreipti kėlimą, kol jis baigsis."}},"specialist-b2-11":{"question":"Labai triukšmingoje vietoje dirbantys darbuotojai dėvi apsaugines ausines (ear defenders) ir gali negirdėti pavojaus signalo. Ką sako įstatymas apie saugos ženklus ir signalus?","options":["Reikia imtis papildomų priemonių, pvz., pridėti mirksinčias šviesas, kad įspėjimas vis tiek juos pasiektų","Nieko. Jie patys turi atidžiau klausytis","Jie turėtų nusiimti apsaugines ausines, kad girdėtų pavojaus signalą","Toje vietoje pavojaus signalą galima išjungti"],"explanation":"Jei darbuotojai negali gerai girdėti ar matyti ženklo ar signalo, pvz., dėl dėvimų asmeninės apsaugos priemonių (PPE), įstatymas sako, kad reikia imtis papildomų priemonių jam sustiprinti ar pakeisti. Kartu su pavojaus signalu galima naudoti mirksinčias šviesas, kad jo negirdintys žmonės vis tiek gautų įspėjimą. Nusiėmę apsaugines ausines, jie būtų veikiami triukšmo.","why_not":{"1":"Įstatymas sako, kad reikia imtis papildomų priemonių, kai dėl asmeninės apsaugos priemonių (PPE) darbuotojai negirdi signalo.","2":"Nusiėmę apsaugines ausines (ear defenders), jie būtų veikiami triukšmo. Įstatymas sako verčiau imtis papildomų priemonių.","3":"Išjungus pavojaus signalą, jie liktų be įspėjimo. Vietoj to reikia imtis papildomų priemonių."}},"specialist-b2-12":{"question":"Kodėl statybvietėse rengiamos evakuacijos pratybos (emergency drills)?","options":["Įstatymas sako, kad avarinių situacijų planas turi būti kartkartėmis išbandomas praktiškai","Kad būtų patikrinta, kurie darbuotojai lėti","Tik todėl, kad jų reikalauja draudimo bendrovė","Kad darbuotojai pailsėtų, todėl nesvarbu, ką darote"],"explanation":"Statybvietėse turi būti avarinių situacijų valdymo planai, įskaitant visų žmonių išvedimą iš statybvietės. Įstatymas sako, kad visi turi žinoti planą, ir planas turi būti išbandomas jį iš tikrųjų vykdant tinkamu laiku. Pratybos parodo, ar žmonės žino, kaip išeiti, ir ar planas veikia, todėl elkitės kaip tikros avarijos metu.","why_not":{"1":"Pratybos skirtos išbandyti avarinių situacijų planą, o ne patikrinti, kas lėtas.","2":"Pats įstatymas sako, kad avarinių situacijų planą reikia išbandyti jį iš tikrųjų vykdant.","3":"Pratybos išbando avarinių situacijų planą, todėl elkitės kaip tikros avarijos metu."}},"specialist-b2-13":{"question":"Evakuacijos kelyje iš statybvietės rūsio nėra dienos šviesos. Ko šiame kelyje gali reikalauti įstatymas?","options":["Avarinio apšvietimo, kad keliu būtų galima naudotis, net jei užgęsta įprastos šviesos","Nieko, nes darbuotojai gali naudotis telefono žibintuvėliu","Nieko, jei kelias trumpas","Užrašo, liepiančio žmonėms likti vietoje, jei užgęsta šviesa"],"explanation":"Avariniu keliu turi būti galima naudotis bet kada. Kur reikia, pvz., kelyje be dienos šviesos, turi būti avarinis apšvietimas, kuris veikia ir dingus elektrai. Negalima tikėtis, kad gaisro ar elektros dingimo metu kiekvienas turės telefono žibintuvėlį.","why_not":{"1":"Negalima pasikliauti telefonų žibintuvėliais. Kur reikia, įstatymas reikalauja avarinio apšvietimo evakuacijos keliuose.","2":"Trumpu keliu irgi turi būti galima naudotis bet kada, todėl jam gali reikėti avarinio apšvietimo.","3":"Evakuacijos keliais turi būti galima naudotis bet kada. Avarinis apšvietimas padeda žmonėms išeiti, o ne likti vietoje."}},"specialist-b2-14":{"question":"Priešgaisrinės durys laiptinėje vis užsidaro, kai nešate pro jas medžiagas. Ką turėtumėte daryti?","options":["Leisti joms užsidaryti. Priešgaisrinės durys turi būti uždarytos ir niekada nepaliktos atremtos atidarytos","Atremti jas blokeliu, kol baigsite","Nukabinti jas nuo vyrių tai dienai","Pririšti jas atidarytas, jei tik veikia gaisro signalizacija"],"explanation":"Priešgaisrinės durys sustabdo ugnies ir dūmų plitimą ir apsaugo laiptus, kuriais žmonės evakuojasi. Jos veikia tik uždarytos, todėl jų niekada negalima atremti ar pririšti atidarytų. Jei durys turi likti atidarytos, joms reikia specialaus uždarymo įtaiso, kuris jas pats uždaro, kai suskamba signalas.","why_not":{"1":"Priešgaisrinės durys turi būti uždarytos. HSE (darbo saugos tarnyba) sako niekada jų neatremti atidarytų.","2":"Nukabintos nuo vyrių priešgaisrinės durys negali sustabdyti ugnies ir dūmų. Laikykite priešgaisrines duris uždarytas.","3":"Veikianti signalizacija to nekeičia. Priešgaisrinės durys turi būti uždarytos."}},"specialist-b2-15":{"question":"Jūsų darbui reikia darbų leidimo (permit to work). Leidimas dar rašomas, ir kažkas siūlo pradėti, kad sutaupytumėte laiko. Ką turėtumėte daryti?","options":["Laukti. Nepradėti, kol leidimas neišduotas, jūs jį suprantate ir jame nurodytos atsargumo priemonės įgyvendintos","Dabar pradėti lengvas dalis, o baigti, kai bus leidimas","Pradėti, jei vėliau pasirašysite leidimą","Pradėti, nes leidimas – tik popierius"],"explanation":"Darbų leidimas (permit to work) skirtas pavojingiems darbams kontroliuoti. Negalite pradėti darbo, kol leidimas tinkamai patvirtintas ir išduotas, kol suprantate, kas jame parašyta, ir kol įgyvendintos jame reikalaujamos atsargumo priemonės. Pradėję anksčiau, dirbtumėte be tų apsaugų.","why_not":{"1":"Nepradėkite jokios darbo dalies, kol darbų leidimas (permit to work) neišduotas ir jūs jo nesuprantate.","2":"Darbų leidimas (permit to work) turi būti išduotas ir jo atsargumo priemonės įgyvendintos prieš pradedant, o ne pasirašytas vėliau.","3":"Darbų leidimas (permit to work) – ne tik popierius. Pradėję be jo, dirbtumėte be jo numatytų apsaugų."}},"specialist-b2-18":{"question":"Šį rytą turite karštųjų darbų leidimą (hot work permit) pjauti plieną vienoje vietoje. Po pietų jūsų prašo virinti kitoje statybvietės dalyje. Ar galite naudoti tą patį leidimą?","options":["Ne. Karštųjų darbų leidimas apima vieną nustatytą darbą, vienoje vietoje, nustatytą laiką. Reikia naujo","Taip. Turint karštųjų darbų leidimą, karštuosius darbus galima dirbti bet kur statybvietėje","Taip, jei tai vis dar ta pati diena","Taip, jei patys įrašysite į jį naują vietą"],"explanation":"Karštųjų darbų leidimas (hot work permit) skirtas aiškiai nustatytam darbui, vienoje vietoje, nustatytą laiką. Jis baigiasi, kai tas darbas atliktas arba baigiasi laikas. Jis niekada negali būti laisvas leidimas dirbti karštuosius darbus bet kur statybvietėje bet kuriuo metu, nes kiekviena vieta turi savo gaisro pavojų.","why_not":{"1":"Karštųjų darbų leidimas (hot work permit) niekada nėra laisvas leidimas dirbti karštuosius darbus bet kur statybvietėje.","2":"Leidimas skirtas vienam darbui vienoje vietoje. Naujai vietai reikia naujo leidimo.","3":"Patys leidimo keisti negalite. Naujam darbui naujoje vietoje reikia naujo leidimo."}},"specialist-b2-20":{"question":"Po pjovimo jūsų kombinezonas apneštas dulkėmis. Bendradarbis sako, kad galite greitai jas nupūsti pjovimo įrangos deguonies žarna. Ką turėtumėte daryti?","options":["Atsisakyti. Deguonies prisisunkę drabužiai labai lengvai užsidega ir dega labai smarkiai","Nupūsti, jei tik pjovimo degiklis išjungtas","Nupūsti, jei tik jūsų kombinezonas nedegus (fire-retardant)","Nupūsti lauke, kur deguonį išpūs vėjas"],"explanation":"Niekada nenaudokite deguonies dulkėms nuo drabužių nupūsti. Deguonies prisisunkę drabužiai lengvai užsidega ir dega labai smarkiai, net nedegūs (fire-retardant) drabužiai. Viena kibirkštis vėliau gali jus uždegti.","why_not":{"1":"Išjungtas degiklis nepadeda. Deguonies prisisunkę drabužiai vėliau gali lengvai užsidegti.","2":"Net nedegūs (fire-retardant) drabužiai dega labai smarkiai, kai yra prisisunkę deguonies.","3":"Niekada nenaudokite deguonies dulkėms nuo drabužių nupūsti, kad ir kur būtumėte."}},"specialist-b2-21":{"question":"Jūsų paprašė vienam atlikti nedidelį darbą. Bendradarbis sako, kad dirbti vienam draudžia įstatymas. Ar jis teisus?","options":["Ne. Dirbti vienam dažnai saugu, bet prieš pradedant darbdavys turi apgalvoti pavojus ir jų imtis","Taip. Dirbti vienam visada draudžia įstatymas","Ne. Dėl darbo vienam nėra jokių taisyklių","Taip, nebent darbas trunka mažiau nei valandą"],"explanation":"Įstatymas nedraudžia dirbti vienam, ir tai dažnai saugu. Bet prieš kam nors dirbant vienam, darbdavys turi apgalvoti pavojus ir jų imtis, pvz., kaip palaikysite ryšį ir gausite pagalbą. Kai kuriems labai pavojingiems darbams gali reikėti, kad šalia būtų kitas žmogus.","why_not":{"1":"Dirbti vienam įstatymas nedraudžia, ir tai dažnai saugu.","2":"Taisyklės yra. Darbdavys turi apgalvoti darbo vienam pavojus ir jų imtis.","3":"Laikas – ne matas. Dirbti vienam nedraudžiama, bet pirmiausia reikia imtis priemonių dėl pavojų."}},"specialist-b2-22":{"question":"Tai jūsų pirma savaitė naujame darbe. Jūsų prašo vienam dirbti tolimoje statybvietėje. Ką pataria HSE (darbo saugos tarnyba)?","options":["Naujiems darbuotojams iš pradžių gali reikėti, kad kas nors būtų kartu, prieš jiems dirbant vieniems","Nauji darbuotojai turėtų iš karto dirbti vieni, kad greičiau išmoktų","Tinka, jei tik turite telefoną, kad ir kokia būtų jūsų patirtis","Kai jau išklausėte statybvietės instruktažą (induction), jums niekada nereikia, kad kas nors būtų kartu"],"explanation":"HSE (darbo saugos tarnyba) sako, kad vieniems dirbantiems žmonėms iš pradžių gali reikėti, kad kas nors būtų kartu, jei jie nauji darbe, dar mokosi, atlieka ypatingos rizikos darbą ar susiduria su kažkuo nauju. Dirbant vienam reikia pakankamai patirties, kad suprastumėte pavojus ir ką daryti, jei kas nors nutiktų.","why_not":{"1":"HSE (darbo saugos tarnyba) sako, kad naujiems darbuotojams iš pradžių gali reikėti, kad kas nors būtų kartu, prieš jiems dirbant vieniems.","2":"Telefono neužtenka. Jei esate naujas darbe, iš pradžių jums gali reikėti, kad kas nors būtų kartu.","3":"Instruktažo (induction) neužtenka. Naujiems darbuotojams ar naujose situacijose gali reikėti, kad kas nors būtų kartu."}},"specialist-b2-23":{"question":"Randate bendradarbį, nejudantį ir gulintį ant grindų šalia pažeisto elektros kabelio. Ką turėtumėte daryti pirmiausia?","options":["Įsitikinti, kad pačiam negresia pavojus, ir padaryti vietą saugią prieš prieinant","Iš karto jį sugriebti ir patraukti nuo kabelio","Apipilti jį vandeniu, kad atsibustų","Nueiti ir pranešti apie tai per kitą pertrauką"],"explanation":"Avarijos atveju pirmiausia įsitikinkite, kad nekeliate pavojaus sau, ir padarykite vietą saugią. Šiuo atveju tai reiškia, kad elektra turi būti išjungta, prieš kam nors jį liečiant. Tada patikrinkite nukentėjusįjį ir nedelsdami kvieskite pagalbą. Jei susižeisite ir jūs, bus du nukentėjusieji ir nebus kam padėti.","why_not":{"1":"Jis gali vis dar liesti elektrą su įtampa. Prieš jį liesdami, įsitikinkite, kad vieta saugi.","2":"Pildami vandenį šalia pažeisto kabelio, galite patys atsidurti pavojuje. Pirmiausia padarykite vietą saugią.","3":"Nedelskite. Padarykite vietą saugią, patikrinkite jį ir iš karto kvieskite pagalbą."}},"specialist-b2-24":{"question":"Cheminė medžiaga įtiško bendradarbiui į akį. Kiek laiko akį reikia plauti švariu vandeniu?","options":["Bent 10 minučių, švelniai prilaikant vokus atmerktus","Kelias sekundes, kol nustos perštėti","Nenaudoti vandens. Vietoj to akį iššluostyti","Vieną minutę, tada grįžti į darbą"],"explanation":"Jei cheminė medžiaga pateko į akį, plaukite ją švariu vandeniu (ar steriliu akių plovikliu) bent 10 minučių, švelniai prilaikydami vokus atmerktus. Tada nukentėjusysis turi prisidėti prie akies tamponą ir vykti į ligoninę. Visos akių traumos gali būti rimtos.","why_not":{"1":"Kelios sekundės – gerokai per trumpai. Plaukite akį bent 10 minučių.","2":"Šluostyti neteisinga. Plaukite akį švariu vandeniu bent 10 minučių.","3":"Viena minutė – per trumpai. Plaukite akį bent 10 minučių."}},"specialist-b2-25":{"question":"Darbuotojas nukrito ir galbūt susižeidė nugarą ar kaklą. Ten, kur jis guli, jam daugiau negresia pavojus. Ką turėtumėte daryti?","options":["Jo nejudinti ir kviesti specialistų pagalbą","Pasodinti jį, kad lengviau kvėpuotų","Padėti jam nueiti iki statybvietės vagonėlio","Užkelti jį ant padėklo ir išnešti"],"explanation":"Jei žmogus gali turėti kaulo lūžį ar nugaros ar kaklo (stuburo) traumą, kvieskite specialistų pagalbą. Nejudinkite jo, nebent ten, kur jis yra, jam gresia tiesioginis pavojus. Judinant trauma gali tapti daug sunkesnė.","why_not":{"1":"Pasodinus jį, jis judinamas, ir nugaros ar kaklo trauma gali pasunkėti.","2":"Nejudinkite jo, nebent jam gresia pavojus. Einant trauma gali tapti daug sunkesnė.","3":"Nejudinkite jo, nebent jam gresia tiesioginis pavojus. Verčiau kvieskite specialistų pagalbą."}},"specialist-b3-01":{"question":"Ardydami patalpos apdailą, randate seną pilką plokštę. Bendradarbis sako: „Asbestas (asbestos) visada būna baltas arba rudas, todėl pilka plokštė nepavojinga.“ Kas teisinga?","options":["Vien iš spalvos negalima pasakyti, ar tai asbestas","Pilkoje plokštėje asbesto niekada nebūna","Asbesto gali būti tik baltoje plokštėje","Jei plokštė nudažyta, tai negali būti asbestas"],"explanation":"Asbestas (asbestos) būna ne vienos spalvos, ir dažnai jis sumaišytas su kitomis medžiagomis, kurios pakeičia jo išvaizdą. Todėl spalva nieko tikro nepasako. Jei nesate tikri, medžiagą reikia patikrinti.","why_not":{"1":"Spalva nieko nepasako. Asbestas (asbestos) gali būti sumaišytas su kitomis medžiagomis, kurios pakeičia jo išvaizdą.","2":"Pagal spalvą asbesto (asbestos) nenustatysite. Jis gali atrodyti labai įvairiai.","3":"Dažai nieko neįrodo. Vien iš išvaizdos negalima pasakyti, ar tai asbestas (asbestos)."}},"specialist-b3-03":{"question":"Netyčia sulaužote seną plokštę, kurioje gali būti asbesto (asbestos). Šiek tiek dulkių nukrinta ant jūsų rankovių. Ką pataria HSE (darbo saugos tarnyba)?","options":["Likti vietoje, užsidėti kaukę (jei galite), nušluostyti viršutinius drabužius drėgna šluoste ir juos nusivilkti prieš pasitraukiant","Iš karto nueiti į buitinį vagonėlį (welfare cabin) ir ten nusivalyti dulkes šepečiu","Stipriai papurtyti striukę, kad dulkės nukristų","Dirbti toliau, nes šiek tiek dulkių nieko nereiškia"],"explanation":"Jei vaikštote ar purtote drabužius, dulkės pasklinda į kitas vietas ir pasiekia kitus žmones. HSE (darbo saugos tarnyba) sako: likite vietoje, stenkitės dulkių neįkvėpti, užsidėkite kaukę (jei įmanoma), nušluostykite viršutinius drabužius drėgna šluoste ir juos nusivilkite prieš pasitraukdami.","why_not":{"1":"Einant dulkės pasklinda. HSE (darbo saugos tarnyba) sako likti vietoje ir nusivilkti viršutinius drabužius prieš pasitraukiant.","2":"Purtant striukę, dulkės pakyla į orą. Verčiau nušluostykite viršutinius drabužius drėgna šluoste.","3":"Net šiek tiek dulkių svarbu. Likite vietoje, nušluostykite drabužius drėgna šluoste ir juos nusivilkite prieš pasitraukdami."}},"specialist-b3-04":{"question":"Esate apmokyti nedideliam nelicencijuojamam darbui su asbestu (non-licensed asbestos work). Tinkamų respiratorių (respirators) neliko, todėl bendradarbis siūlo užsidėti dvi paprastas dulkių kaukes (dust masks) vieną ant kitos. Ką sako HSE (darbo saugos tarnyba)?","options":["Dvi dulkių kaukės nieko neapsaugo. Reikia tinkamo tipo respiratoriaus","Dvi kaukės apsaugo dvigubai, todėl viskas gerai","Viskas gerai, jei darbas trumpas","Užtenka vienos dulkių kaukės, jei medžiagą prieš tai sudrėkinsite"],"explanation":"Paprasta dulkių kaukė (dust mask) nuo asbesto neapsaugo, ir dvi tokios kaukės to nepakeičia. Reikia tinkamo respiratoriaus (respirator) – tokio tipo, kurį HSE (darbo saugos tarnyba) nurodo kaip tinkamą darbui su asbestu. Jei jo neturite, darbo nepradėkite.","why_not":{"1":"HSE (darbo saugos tarnyba) sako, kad dvi dulkių kaukės (dust masks) vieną ant kitos nieko neapsaugo. Reikia tinkamo respiratoriaus (respirator).","2":"Trumpas darbas to nekeičia. Dulkių kaukės nuo asbesto neapsaugo; reikia respiratoriaus (respirator).","3":"Dulkių kaukė (dust mask) netinka, net sudrėkinus medžiagą. Reikia tinkamo respiratoriaus (respirator)."}},"specialist-b3-06":{"question":"Po gaisro sename pastate ant grindų daug sulaužytos medžiagos su asbestu (asbestos). Jūs nesate licencijuotas asbesto rangovas (licensed asbestos contractor). Viršininkas liepia viską sutvarkyti. Kas teisinga?","options":["To nedaryti. Didelio kiekio asbesto nuolaužų tvarkymas yra licencijuoto rangovo darbas","Daryti, jei prieš tai viską sudrėkinsite","Daryti, nes po gaisro asbestas jau nepavojingas","Daryti, jei baigsite, kol dar niekas neatėjo"],"explanation":"Daug asbesto (asbestos) nuolaužų tvarkymas, pavyzdžiui, po gaisro ar potvynio, yra didesnės rizikos darbas. Jį atlikti gali tik HSE (darbo saugos tarnybos) licenciją turintis rangovas. Jei kada nors nesate tikri, ar darbui reikia licencijos, elkitės taip, lyg jos reikėtų, ir nedirbkite, kol jums nepasakys kitaip.","why_not":{"1":"Sudrėkinus to vis tiek negalima. Didelis kiekis asbesto (asbestos) nuolaužų – licencijuoto rangovo darbas.","2":"Gaisras nepadaro asbesto (asbestos) saugaus. Tvarkymas po gaisro yra licencijuojamas darbas.","3":"Laikas nesvarbus. Didelio kiekio asbesto (asbestos) nuolaužų tvarkymas – licencijuoto rangovo darbas."}},"specialist-b3-08":{"question":"Po žole pakelės juostoje (grass verge) rastas požeminis kabelis. Ant žemės reikia pažymėti, kur jis eina. Kuo žymėti?","options":["Mediniais kuoliukais, įkaltais šiek tiek šalia kabelio linijos","Ilgais plieniniais strypais, įkaltais tiesiai virš kabelio","Metaliniais smaigais, nes jie gerai matomi","Niekuo, nes visi atsimins, kur jis yra"],"explanation":"Ant žolės ar plikos žemės kabelio liniją žymėkite mediniais kuoliukais, įkaltais šiek tiek į šoną nuo kabelio. Plieniniai strypai, smaigai ar ilgi kuoliai gali įlįsti taip giliai, kad pataikytų į arti paviršiaus esantį kabelį.","why_not":{"1":"Plieniniai strypai gali pataikyti į arti paviršiaus esantį kabelį. Naudokite medinius kuoliukus, įkaltus šone.","2":"Metaliniai smaigai gali pažeisti negiliai esantį kabelį. HSE (darbo saugos tarnyba) sako ant žolės naudoti medinius kuoliukus.","3":"Kabelio liniją būtina pažymėti. Ant žolės naudokite medinius kuoliukus, įkaltus šone."}},"specialist-b3-09":{"question":"Po betoniniu taku eina kabelis. Betoną reikia išskaldyti rankiniu skaldymo plaktuku (breaker). Kokiu atstumu nuo pažymėtos kabelio linijos, kur tai įmanoma, turi būti laikomas plaktukas?","options":["Ne mažiau kaip 500 mm (pusės metro)","Ne mažiau kaip 50 mm","Ne mažiau kaip 150 mm","Laikytis atstumo nereikia, nes betonas apsaugo kabelį"],"explanation":"Kietas dangas skaldant rankiniais elektriniais įrankiais, dažnai pataikoma į kabelius. Kur galite, laikykite įrankį ne mažiau kaip 500 mm nuo pažymėtos linijos. Tada kabelį po danga suraskite atsargiai kasdami rankomis.","why_not":{"1":"50 mm – gerokai per arti. Kur galite, laikykite skaldymo plaktuką (breaker) bent 500 mm atstumu.","2":"150 mm – per arti. Kur galite, laikykite skaldymo plaktuką (breaker) bent 500 mm atstumu.","3":"Skaldant kietas dangas, dažnai pataikoma į kabelius. Kur galite, laikykitės bent 500 mm atstumu."}},"specialist-b3-11":{"question":"Tranšėjoje atkasate seną ketinį vamzdį. Niekas tikrai nežino, ar juo teka vanduo, ar dujos. Kaip su juo elgtis, kol sužinosite?","options":["Kaip su dujų vamzdžiu","Kaip su vandens vamzdžiu, nes dauguma senų vamzdžių yra vandentiekio","Kaip su tuščiu vamzdžiu, nes jis atrodo senas","Kaip su vamzdžiu, kurį galima saugiai pjauti, nes dujos niekada neleidžiamos ketiniais vamzdžiais"],"explanation":"Ketiniai ir plieniniai vandens vamzdžiai gali atrodyti visai kaip dujų vamzdžiai. Kol tikrai nežinoma, koks tai vamzdis, elkitės su juo kaip su dujų vamzdžiu.","why_not":{"1":"Ketiniai vandens vamzdžiai ir dujų vamzdžiai gali atrodyti vienodai. Kol nežinote, elkitės kaip su dujų vamzdžiu.","2":"Tai, kad jis atrodo senas, nieko neįrodo. Su tokiu vamzdžiu elkitės kaip su dujų vamzdžiu.","3":"Dujos gali būti leidžiamos ketiniais ar plieniniais vamzdžiais. Kol nežinote, elkitės kaip su dujų vamzdžiu."}},"specialist-b3-12":{"question":"Per statybvietę eina aukštos įtampos elektros linija virš galvos (overhead power line). Atrodo, kad jos laidai padengti plonu plastiko sluoksniu. Kaip su jais elgtis?","options":["Taip, lyg tai būtų pliki laidai be jokios izoliacijos","Kaip su izoliuotais laidais, kuriuos saugu liesti","Kaip su saugiais laidais, jei mūvite pirštines","Kaip su laidais be įtampos, nes padengtais laidais elektra neteka"],"explanation":"Dauguma aukštos įtampos linijų yra plikos, bet kai kurios turi ploną plastiko dangą. Ta danga nepadaro jų saugių. HSE (darbo saugos tarnyba) sako, kad su kiekviena aukštos įtampos linija reikia elgtis taip, lyg ji visai neturėtų izoliacijos.","why_not":{"1":"Plona danga nepadaro jos saugios. Su visomis aukštos įtampos linijomis elkitės kaip su plikais laidais.","2":"Pirštinės nepadaro to saugaus. Su visomis aukštos įtampos linijomis elkitės taip, lyg jos neturėtų izoliacijos.","3":"Padengtomis linijomis vis tiek gali tekėti elektra. Su visomis aukštos įtampos linijomis elkitės kaip su plikais laidais."}},"specialist-b3-13":{"question":"Dirbsite netoli elektros linijos virš galvos (overhead power line). HSE (darbo saugos tarnyba) sako, kad riziką reikia valdyti, jei dirbate arčiau tam tikro atstumo nuo linijos. Atstumas matuojamas žeme nuo vietos po artimiausiu laidu. Koks tas atstumas?","options":["10 metrų","2 metrai","4 metrai","Tik kai esate tiesiai po laidais"],"explanation":"HSE (darbo saugos tarnyba) sako, kad riziką reikia valdyti dirbant bet kokį darbą arčiau nei 10 metrų nuo linijos, matuojant žeme nuo vietos po artimiausiu laidu. Tai galioja net trumpiems ar laikiniems darbams.","why_not":{"1":"2 metrai – per mažai. HSE (darbo saugos tarnyba) sako valdyti riziką 10 metrų atstumu nuo linijos.","2":"4 metrai – per mažai. HSE (darbo saugos tarnyba) sako valdyti riziką 10 metrų atstumu nuo linijos.","3":"Nebūtina būti tiesiai po laidais. Riziką reikia valdyti dirbant arčiau nei 10 metrų."}},"specialist-b3-15":{"question":"Darbų vadovui (supervisor) reikia žinoti, kokiame aukštyje virš žemės yra elektros linija virš galvos (overhead power line). Kaip tai reikia išmatuoti?","options":["Tai turi daryti apmokytas asmuo matavimo prietaisu, kuris neliečia laidų","Ilgą matavimo ruletę iškėlus iki laidų","Kėlus pastolių vamzdį, kol jis beveik paliečia laidus","Spėjant nuo žemės ir dėl saugumo šiek tiek pridedant"],"explanation":"Bet kas, kas keliama link laidų, gali juos paliesti arba priartėti tiek, kad elektra peršoktų. Aukštį turėtų matuoti tam apmokytas žmogus prietaisu, kuriam nereikia liesti linijos.","why_not":{"1":"Iškelti ruletę iki laidų pavojinga. Apmokytas asmuo turėtų naudoti prietaisą, kuris neliečia laidų.","2":"Šalia laidų keliamas vamzdis gali juos paliesti. Aukštį reikia matuoti nieko neliečiant.","3":"Spėti nepakanka. Apmokytas asmuo turėtų jį išmatuoti prietaisu, kuris neliečia laidų."}},"specialist-b3-16":{"question":"Įspėjamoji lemputė statybvietėje gali šviesti nuolat arba mirksėti. Ką reiškia, kai ji mirksi, o ne šviečia nuolat?","options":["Pavojus didesnis arba veikti reikia skubiau","Pavojus praėjo","Lemputė tuoj perdegs","Pavojus mažesnis nei tada, kai ji šviečia nuolat"],"explanation":"Kai lemputė gali ir šviesti, ir mirksėti, įstatymas sako, kad mirksintis signalas naudojamas didesniam pavojui arba kai veikti reikia skubiau. Nuolat šviečianti lemputė reiškia žemesnio lygio įspėjimą.","why_not":{"1":"Mirksinti lemputė reiškia didesnį pavojų, o ne kad pavojus praėjo.","2":"Mirksėjimas yra nustatytas signalas, reiškiantis didesnį pavojų. Tai nesusiję su lempute.","3":"Yra atvirkščiai. Mirksinti lemputė reiškia didesnį pavojų nei nuolat šviečianti."}},"specialist-b3-17":{"question":"Signalizuotojas (signaller) nukreips sunkvežimio vairuotoją, duodamas žodinius nurodymus per raciją. Vairuotojas prastai supranta signalizuotojo kalbą. Ką sako Saugos ženklų ir signalų taisyklės (Safety Signs and Signals Regulations)?","options":["Žodinius signalus naudojantys žmonės turi mokėti kalbą pakankamai gerai, kad teisingai pasakytų ir suprastų pranešimus","Nesvarbu, jei tik racija pakankamai garsi","Vairuotojas gali nuspėti, ką norima pasakyti, iš signalizuotojo balso tono","Žodinius signalus gali duoti bet kas, bet kokia kalba"],"explanation":"Žodiniai signalai veikia tik tada, kai abu žmonės juos gerai supranta. Įstatymas sako, kad visi dalyvaujantys turi mokėti kalbą pakankamai gerai, kad galėtų pasakyti ir suprasti pranešimus ir saugiai veikti.","why_not":{"1":"Garso neužtenka. Abu žmonės turi mokėti kalbą pakankamai gerai, kad suprastų pranešimus.","2":"Spėlioti nesaugu. Įstatymas sako, kad jie turi gerai mokėti kalbą.","3":"Įstatymas sako, kad žodinius signalus naudojantys žmonės turi gerai mokėti vartojamą kalbą."}},"specialist-b3-19":{"question":"Signalizuotojas (signaller) nukreipia kraną. Krovinį reikia perkelti už pastato, kur signalizuotojas iš saugios vietos jo nemato. Kas turėtų būti daroma?","options":["Turėtų būti pasitelktas dar vienas signalizuotojas, kad visą perkėlimą būtų galima saugiai matyti","Signalizuotojas turėtų spėti, kur yra krovinys","Krano operatorius turėtų dirbti toliau be jokių signalų","Signalizuotojas turėtų atsistoti po kroviniu, kad geriau matytų"],"explanation":"Signalizuotojas (signaller) turi matyti visą perkėlimą ir pats nepatekti į pavojų. Jei vienas žmogus to negali, reikėtų pasitelkti vieną ar daugiau papildomų signalizuotojų.","why_not":{"1":"Spėlioti nesaugu. Signalizuotojas (signaller) turi matyti visą perkėlimą.","2":"Perkelti be signalų nesaugu. Reikėtų pasitelkti dar vieną signalizuotoją (signaller).","3":"Stovėdamas po kroviniu, signalizuotojas (signaller) atsiduria pavojuje. Jis turi stebėti iš saugios vietos."}},"specialist-b3-22":{"question":"Kaip dažnai, pasak HSE (darbo saugos tarnybos), paskirtas kompetentingas asmuo (competent person) turėtų išbandyti statybvietės gaisro signalizaciją, kad patikrintų, ar ji veikia ir ar girdima darbo vietose?","options":["Kiekvieną savaitę","Kartą per metus","Tik kai ji įrengiama","Tik po tikro gaisro"],"explanation":"Gaisro signalizacija nieko neverta, jei ji neveikia arba jos negirdėti ten, kur dirba žmonės. HSE (darbo saugos tarnyba) sako, kad ją turėtų kiekvieną savaitę išbandyti paskirtas kompetentingas asmuo (competent person), taip pat ją įrengus arba papildžius.","why_not":{"1":"Kartą per metus – per retai. HSE (darbo saugos tarnyba) sako gaisro signalizaciją išbandyti kiekvieną savaitę.","2":"Išbandyti tik kartą neužtenka. HSE (darbo saugos tarnyba) sako ją išbandyti kiekvieną savaitę.","3":"Laukti tikro gaisro – per vėlu. HSE (darbo saugos tarnyba) sako ją išbandyti kiekvieną savaitę."}},"specialist-b3-23":{"question":"Kad nepavogtų, kažkas užrakino pakabinama spyna avarinio išėjimo (fire exit) duris pastate, kuriame dar dirba žmonės. Ką HSE (darbo saugos tarnyba) sako apie avarinio išėjimo duris?","options":["Jos turi iš karto atsidaryti iš evakuacijos pusės vienu veiksmu, be rakto","Spyna tinka, jei raktas kabo šalia durų","Spyna tinka, jei raktą turi statybvietės vadovas","Spyna tinka darbo valandomis"],"explanation":"Gaisro metu žmonės turi greitai išeiti, net per dūmus. Avarinio išėjimo (fire exit) durys turi iš karto atsidaryti iš vidaus vienu paprastu veiksmu, ir tam neturi reikėti rakto.","why_not":{"1":"Raktas apskritai neturi būti reikalingas. Avarinio išėjimo (fire exit) durys turi atsidaryti vienu veiksmu be rakto.","2":"Gaisro metu žmonės negali laukti rakto. Avarinio išėjimo (fire exit) durys turi atsidaryti be rakto.","3":"Būtent darbo valandomis žmonėms reikia išeiti. Avarinio išėjimo (fire exit) durys turi atsidaryti be rakto."}},"specialist-b3-24":{"question":"Dalis patalpos gaisro aptikimo sistemos buvo išjungta, kad dėl jūsų darbo ji netyčia nesuveiktų. Einate pietauti. Kas turi būti padaryta su sistema?","options":["Ją reikia vėl įjungti, kai darbas sustoja, taip pat per pertraukas ir darbo dienos pabaigoje","Palikti ją išjungtą, kol kitą savaitę bus baigtas visas darbas","Palikti ją išjungtą per pietus, nes niekas nedirba","Vėl ją įjungti gali tik priešgaisrinė gelbėjimo tarnyba"],"explanation":"Gaisras gali kilti, kai niekas nežiūri, pavyzdžiui, per pertrauką. Todėl bet kuri signalizacijos ar gaisro aptikimo sistemos dalis, išjungta dėl darbo, turi būti vėl įjungta kaskart, kai darbas sustoja, taip pat per pertraukas.","why_not":{"1":"Ją reikia vėl įjungti kaskart, kai darbas sustoja, taip pat kiekvienos dienos pabaigoje.","2":"Pertraukos irgi skaičiuojamos. Ją reikia vėl įjungti, kai sustojate pietauti.","3":"Tai nepaliekama priešgaisrinei gelbėjimo tarnybai. Statybvietė turi ją vėl įjungti kaskart, kai darbas sustoja."}},"specialist-b3-25":{"question":"Gaisro signalizacija suskamba, kai esate įpusėję betonavimą. Bendradarbis sako, kad tai tikriausiai tik pratybos ir kad pirmiau reikia baigti. Ką turėtumėte daryti?","options":["Išeiti iš karto. Kai skamba signalizacija, visi turi išeiti nedelsdami","Pirmiau baigti betonavimą, tada išeiti","Palaukti ir pažiūrėti, ar užuosite dūmus, ir tik tada išeiti","Likti vietoje, nes pratybos nesiskaito"],"explanation":"Kai suskamba gaisro signalizacija, visi turi iš karto išeiti. HSE (darbo saugos tarnyba) įspėja, kad žmonės dažnai delsia, nes yra įpusėję darbą arba mano, kad signalizacija – pratybos ar klaidinga. Toks delsimas gali kainuoti gyvybes.","why_not":{"1":"Pirmiau baigiant darbą, delsiama. Kai skamba signalizacija, visi turi iš karto išeiti.","2":"Nelaukite dūmų. Kai skamba signalizacija, visi turi išeiti nedelsdami.","3":"Kiekvieną signalizaciją laikykite tikra. Visi turi išeiti nedelsdami."}},"specialist-b3-26":{"question":"Jūsų darbų vadovas (supervisor) turi teisę išduoti darbų leidimus (permits to work). Jis nori surašyti ir išduoti leidimą darbui, kurį pats atliks. Ką sako HSE (darbo saugos tarnyba)?","options":["Žmogus neturėtų išduoti leidimo pats sau","Viskas gerai, nes taip sutaupoma laiko","Viskas gerai, jei jis pasirašys du kartus","Trumpiems darbams viskas gerai"],"explanation":"Darbų leidimas (permit to work) yra vieno žmogaus atliekamas kito žmogaus darbo patikrinimas. HSE (darbo saugos tarnyba) sako, kad niekas neturėtų išduoti leidimo pats sau. Labai didelės rizikos darbams leidimą prieš išduodant turėtų peržiūrėti ir antras žmogus.","why_not":{"1":"Laiko taupymas – ne priežastis. HSE (darbo saugos tarnyba) sako, kad niekas neturėtų išduoti leidimo pats sau.","2":"Pasirašymas du kartus nepadeda. Žmogus neturėtų išduoti leidimo pats sau.","3":"Trumpi darbai – ne išimtis. Niekas neturėtų išduoti leidimo pats sau."}},"specialist-b3-27":{"question":"Vakar darbas pagal darbų leidimą (permit to work) buvo sustabdytas (suspended), kol laukėte atsarginių dalių. Dabar dalys atvežtos. Kas turi būti padaryta prieš vėl pradedant?","options":["Leidimus išduodantis asmuo turi patikrinti, ar saugu, tada pratęsti leidimą arba išduoti naują","Tiesiog dirbti toliau, nes leidimas niekada nebuvo panaikintas","Pradėti vėl, jei tai vis dar ta pati savaitė","Pradėti vėl, jei bendradarbis sako, kad vieta atrodo taip pat kaip vakar"],"explanation":"Sustabdytas leidimas galioja tol, kol jo nepanaikina, o nuo darbo sustabdymo daug kas galėjo pasikeisti. Darbo nereikėtų atnaujinti, kol leidimus išduodantis asmuo nepatikrino, ar saugu, ir nepratęsė leidimo arba neišdavė naujo.","why_not":{"1":"Sustabdytas darbų leidimas (permit to work) galioja toliau, o padėtis galėjo pasikeisti. Pirmiausia jį reikia patikrinti ir pratęsti.","2":"Savaitė nesvarbi. Leidimus išduodantis asmuo turi patikrinti, ar saugu, ir pratęsti leidimą.","3":"Bendradarbio žvilgsnio neužtenka. Pirmiausia leidimus išduodantis asmuo turi patikrinti, ar saugu."}},"specialist-b3-28":{"question":"Darbas pagal darbų leidimą (permit to work) nebaigtas, kai baigiasi jūsų pamaina. Jį perims naktinė pamaina. Ką turi užtikrinti pamainos perdavimas?","options":["Kad naktinė pamaina žinotų apie nebaigtą darbą pagal leidimą, kiek jis pažengęs ir kokios būklės yra įranga (plant)","Nieko. Naktinė pamaina gali perskaityti leidimą, jei atsitiktinai jį ras","Kad leidimas būtų išmestas ir naktinė pamaina galėtų pradėti iš naujo be jo","Tik kad būtų pasakyta darbų vadovui, o ne perimantiems darbuotojams"],"explanation":"Kai darbas pagal leidimą tęsiasi kitoje pamainoje, perimantiems žmonėms reikia apie tai pasakyti: kas dar nebaigta, kiek darbas pažengęs ir kokios būklės yra įranga (plant). Netinkamas pamainos perdavimas buvo viena iš „Piper Alpha“ katastrofos priežasčių.","why_not":{"1":"Naktinei pamainai reikia pasakyti apie nebaigtus darbus pagal leidimą, o ne palikti, kad sužinotų pati.","2":"Leidimo negalima išmesti. Naktinei pamainai reikia pasakyti apie nebaigtą darbą.","3":"Perimantys darbuotojai turi žinoti apie darbą, kiek jis pažengęs ir kokios būklės yra įranga (plant)."}},"specialist-b3-30":{"question":"Manote, kad jūsų dujinio pjovimo įrangos jungtyje gali būti nedidelis dujų nuotėkis. Kaip tai patikrinti?","options":["Naudoti nuotėkiui aptikti skirtą purškiklį ar tirpalą, skirtą deguonies ir kuro dujų (oxy/fuel) įrangai","Prikišti prie jungties uždegtą degtuką ir žiūrėti, ar liepsna pliūpteli","Ieškoti nuotėkio pjovimo degiklio liepsna","Pauostyti išilgai žarnos ir dirbti toliau, jei nieko neužuodžiate"],"explanation":"Jei dujų nuotėkio ieškosite liepsna, dujos gali užsidegti. HSE (darbo saugos tarnyba) sako, kad reikia naudoti nuotėkiui aptikti skirtą purškiklį ar tirpalą, skirtą deguonies ir kuro dujų (oxy/fuel) įrangai, ir niekada atviros liepsnos. Bet kurią praleidžiančią dalį reikia iš karto suremontuoti arba pakeisti.","why_not":{"1":"Niekada neieškokite dujų nuotėkio liepsna. Dujos gali užsidegti.","2":"Niekada neieškokite dujų nuotėkio liepsna. Verčiau naudokite nuotėkiui aptikti skirtą purškiklį.","3":"Uostymas nėra saugus patikrinimas. Naudokite nuotėkiui aptikti skirtą purškiklį, skirtą deguonies ir kuro dujų (oxy/fuel) įrangai."}},"specialist-b3-31":{"question":"Jūsų prašo dujiniu pjovimo degikliu perpjauti seną alyvos statinę per pusę. Ji atrodo tuščia. Ką turėtumėte žinoti?","options":["Net mažytis viduje likęs kiekis gali sprogti. Nepjaukite, nebent žinote, kad tai saugu","Jei ji atrodo tuščia, ją saugu pjauti","Tai saugu, jei nuimtas dangtis","Tai pavojinga tik tada, kai statinė pilna"],"explanation":"„Tuščiose“ statinėse dugne ar siūlėse dažniausiai dar būna šiek tiek skysčio ar garų. HSE (darbo saugos tarnyba) sako, kad sprogimą gali sukelti net arbatinis šaukštelis degaus skysčio. Niekada nepjaukite degikliu statinės, kurioje buvo ar galėjo būti kas nors degaus, nebent žinote, kad tai saugu.","why_not":{"1":"„Tuščiose“ statinėse paprastai dar būna šiek tiek skysčio ar garų. Sprogimui gali užtekti arbatinio šaukštelio.","2":"Nuimtas dangtis nepadaro to saugaus. Viduje likęs skystis vis tiek gali sprogti.","3":"Tuščia atrodanti statinė vis tiek gali sprogti. Užtenka vos arbatinio šaukštelio degaus skysčio."}},"specialist-b3-32":{"question":"Reikia nupjauti laikiklį nuo seno priekabos rato. Padanga vis dar uždėta, bet ji nuleista. Bendradarbis sako, kad galima pjauti dujiniu degikliu, nes padangoje nėra oro. Ką sako HSE (darbo saugos tarnyba)?","options":["Nepjaukite karštuoju būdu rato su uždėta padanga, net nuleista. Naudokite šaltąjį būdą, pavyzdžiui, pjūklą","Viskas gerai, nes padanga nuleista","Viskas gerai, jei dirbsite greitai","Viskas gerai, jei prieš tai padangą apipilsite vandeniu"],"explanation":"Nuo karščio padanga ir bet kokia alyva ant rato gali išskirti degių garų. Užsilikę padangos viduje, jie gali smarkiai sprogti ir užmušti, net jei padanga nuleista. Jei padangos nuimti negalima, naudokite šaltojo pjovimo būdą, pavyzdžiui, pjūklą.","why_not":{"1":"Nuleista padanga, ją kaitinant, vis tiek gali sprogti. Naudokite šaltąjį būdą, pavyzdžiui, pjūklą.","2":"Greitis nepadeda. Nepjaukite liepsna rato su uždėta padanga.","3":"Apipylus padangą vandeniu, saugiau netampa. Nepjaukite liepsna, kai padanga uždėta."}},"specialist-b3-33":{"question":"Jūsų dujinio pjovimo įrangoje įvyko liepsnos atmušimas (flashback), ir pastebite, kad acetileno balionas įkaito. Ką privalote daryti?","options":["Iš karto visus išvesti iš tos vietos ir skambinti priešgaisrinei gelbėjimo tarnybai","Greitai išnešti balioną į lauką, kad jis atvėstų","Paguldyti balioną ant šono, kad dujos tekėtų lėčiau","Dirbti toliau, jei liepsna užgeso"],"explanation":"Įkaitusio acetileno baliono viduje dujos gali pradėti skilti, ir jis gali sprogti. Jei balionas įkaista ar pradeda drebėti, HSE (darbo saugos tarnyba) sako, kad privalote iš karto pasitraukti ir skambinti priešgaisrinei gelbėjimo tarnybai.","why_not":{"1":"Neikite prie jo. Įkaitęs acetileno balionas gali sprogti, todėl pasitraukite ir skambinkite priešgaisrinei gelbėjimo tarnybai.","2":"Nelieskite jo. Iš karto visus išveskite ir skambinkite priešgaisrinei gelbėjimo tarnybai.","3":"Balionas vis tiek gali sprogti. Išveskite visus ir skambinkite priešgaisrinei gelbėjimo tarnybai."}},"specialist-b3-34":{"question":"Vienas taisote vamzdžius didelio pastato rūsyje. Aukštesniuose aukštuose dirba kiti žmonės, bet su jumis nėra niekieno ir niekas jūsų neprižiūri. Ar esate dirbantis vienas (lone worker)?","options":["Taip. Darbas atskirai nuo kitų toje pačioje vietoje be artimos priežiūros laikomas darbu vienam","Ne. Dirbantis vienas esate tik tada, kai pastate nėra nieko kito","Ne. Darbas vienam reiškia tik darbą naktį","Ne. Darbas vienam taikomas tik prekių pristatymo vairuotojams"],"explanation":"Dirbantis vienas (lone worker) yra bet kuris žmogus, kuris dirba vienas be artimos ar tiesioginės priežiūros. Tai apima ir žmones, dirbančius atskirai nuo kitų tame pačiame pastate, pavyzdžiui, priežiūros ir remonto darbuotojus, o ne tik tuos, kurie yra visiškai vieni.","why_not":{"1":"Darbas atskirai nuo kitų tame pačiame pastate be artimos priežiūros vis tiek laikomas darbu vienam.","2":"Darbas vienam – ne tik naktį. Tai apima ir darbą atskirai nuo kitų be artimos priežiūros.","3":"Vieni dirbantys žmonės (lone workers) būna įvairiuose darbuose, taip pat priežiūros ir remonto."}},"specialist-b3-36":{"question":"Viršininkas sako: „Dirbi vienas, tai pats vertink riziką darbo eigoje. Tikro rizikos vertinimo (risk assessment) mums nereikia.“ Ką sako HSE (darbo saugos tarnyba)?","options":["Rizikos vertinimas darbo eigoje nepakeičia tikro rizikos vertinimo, atlikto iš anksto","Viskas gerai. Užtenka paties vienas dirbančio žmogaus nuovokos","Dirbant vienam rizikos vertinimo niekada nereikia","Rizikos vertinimo reikia tik savarankiškai dirbantiems"],"explanation":"Kai kurie darbdaviai prašo vienų dirbančių darbuotojų vietoje priimti sprendimus dėl rizikos, kurios niekas negalėjo numatyti. HSE (darbo saugos tarnyba) sako, kad tai nepakeičia viso rizikos vertinimo (risk assessment). Darbuotojai, kurių to prašoma, turi būti apmokyti ir turėti pagalbą.","why_not":{"1":"HSE (darbo saugos tarnyba) sako, kad rizikos vertinimas darbo eigoje nepakeičia tikro rizikos vertinimo (risk assessment).","2":"Dirbant vienam, tikro rizikos vertinimo (risk assessment) vis tiek reikia. Vertinimas darbo eigoje jo nepakeičia.","3":"Darbdaviai turi įvertinti vienų dirbančių darbuotojų riziką. Tai skirta ne tik savarankiškai dirbantiems."}},"specialist-b3-38":{"question":"Bendradarbis stipriai nusidegino ranką į karštą vamzdį. Ką sako HSE (darbo saugos tarnybos) pagrindiniai pirmosios pagalbos patarimai?","options":["Vėsinti šaltu vandeniu, kol skausmas sumažės. Tai gali užtrukti 20 minučių ar ilgiau, bet tai neturi atidėti jo vežimo į ligoninę","Vėsinti kelias sekundes, tada laikyti sausai","Visai nevėsinti. Tiesiog tvirtai suvynioti","Pirmiau baigti 20 minučių vėsinimą ir tik tada vykti į ligoninę, net jei dėl to kelionė vėluos"],"explanation":"Nudegimą vėsinkite šaltu vandeniu, kol skausmas sumažės. Tai gali užtrukti 20 minučių ar ilgiau. Jei nukentėjusiajam reikia į ligoninę, vėsinimas neturi to atidėti. Jei abejojate, kreipkitės medicininės pagalbos, nes nudegimai gali būti rimti.","why_not":{"1":"Kelios sekundės – gerokai per trumpai. Vėsinkite nudegimą, kol skausmas sumažės, galbūt 20 minučių ar ilgiau.","2":"Nudegimą reikia vėsinti šaltu vandeniu, kol skausmas sumažės.","3":"Vėsinimas neturi atidėti jo vežimo į ligoninę."}},"specialist-b3-39":{"question":"Po šlifavimo bendradarbiui į akį įstrigo maža metalo skeveldra. Ką turėtumėte daryti?","options":["Nebandyti jos išimti. Kreiptis medicininės pagalbos","Atsargiai ją ištraukti pincetu","Trinti akį, kol ji iškris","Iškelti ją švarios šluostės kampeliu"],"explanation":"Visos akių traumos gali būti rimtos. Laisvas daleles galima išplauti švariu vandeniu arba steriliu akių plovikliu, bet niekada negalima bandyti išimti to, kas įstrigo akyje. Kreipkitės medicininės pagalbos.","why_not":{"1":"Niekada nebandykite išimti to, kas įstrigo akyje. Kreipkitės medicininės pagalbos.","2":"Nebandykite išimti to, kas įstrigo akyje, nei trindami, nei kitaip.","3":"Nebandykite išimti nieko, kas įstrigo akyje. Verčiau kreipkitės medicininės pagalbos."}},"specialist-b3-40":{"question":"Bendradarbį, sergantį astma, ištiko priepuolis, ir jam reikia inhaliatoriaus, kurį jam paskyrė gydytojas. Koks pirmosios pagalbos teikėjo (first-aider) vaidmuo?","options":["Padėti jam pasinaudoti savo inhaliatoriumi ir, jei reikia, skambinti greitosios pagalbos tarnyboms","Atimti inhaliatorių, nes vaistus duoti gali tik gydytojai","Vietoj to duoti jam tablečių iš pirmosios pagalbos vaistinėlės","Nieko nedaryti, kol atvyks greitoji"],"explanation":"Pirmoji pagalba darbe neapima tablečių ar vaistų davimo ligai gydyti. Tačiau jei žmogus turi savo gydytojo paskirtų vaistų, pavyzdžiui, inhaliatorių nuo astmos, pirmosios pagalbos teikėjas (first-aider) gali padėti jam juos pavartoti ir, jei reikia, skambinti greitosios pagalbos tarnyboms.","why_not":{"1":"Jei jis turi savo gydytojo paskirtą inhaliatorių, pirmosios pagalbos teikėjas (first-aider) gali padėti jam juo pasinaudoti.","2":"Pirmoji pagalba darbe neapima tablečių ar vaistų davimo ligai gydyti.","3":"Pirmosios pagalbos teikėjas (first-aider) gali padėti jam pasinaudoti savo inhaliatoriumi ir skambinti greitosios pagalbos tarnyboms."}},"working-environment-b1-02":{"question":"Darbdavys įveda leidimą (permit), kurį privalote užpildyti prieš bet kokius karštuosius darbus (hot work). Jūs manote, kad šie popieriai – laiko švaistymas. Ką sako įstatymas?","options":["Galite jo nepildyti, jei turite daug metų patirties","Jo turi laikytis tik darbų vadovai","Turite bendradarbiauti su darbdaviu, kad jis galėtų vykdyti savo saugos pareigas","Jo turite laikytis tik tada, jei tai parašyta jūsų sutartyje"],"explanation":"Įstatymas kiekvienam darbuotojui nustato pareigą bendradarbiauti su darbdaviu saugos klausimais. Darbdavys privalo laikytis saugos taisyklių, o tam jam reikia, kad jūs laikytumėtės jo nustatytų sistemų, pvz., karštųjų darbų leidimo (hot work permit). Patirtis neleidžia jo praleisti.","why_not":{"0":"Patirtis neleidžia jo praleisti; kiekvienas darbuotojas turi bendradarbiauti laikydamasis saugos sistemų.","1":"Pareiga bendradarbiauti tenka kiekvienam darbuotojui, ne tik darbų vadovams.","3":"Ši pareiga kyla iš įstatymo, todėl ji galioja, kad ir kas būtų parašyta jūsų sutartyje."}},"working-environment-b1-04":{"question":"HSE (darbo saugos tarnybos) inspektorius jūsų įmonei įteikia draudimo pranešimą (prohibition notice) dėl to, kaip jūsų brigada pjauna bordiūrus. Ką tai reiškia?","options":["Tai tik patarimas, todėl darbą galima tęsti kaip anksčiau","Darbą galima tęsti, jei visi užsideda papildomas asmenines apsaugos priemones (PPE)","Sustoti turi tik vadovas, darbuotojai gali dirbti toliau","To darbo negalima dirbti, kol nebus ištaisytos pranešime nurodytos problemos"],"explanation":"Inspektorius įteikia draudimo pranešimą (prohibition notice), kai darbas gali sukelti sunkią traumą. Pranešime parašyta, kad darbo negalima dirbti, kol nebus ištaisytos jame išvardytos problemos. Jis gali įsigalioti iš karto. Tai ne patarimas, ir jis galioja visiems, kurie dirba tą darbą, ne tik vadovui.","why_not":{"0":"Draudimo pranešimas (prohibition notice) yra įsakymas, o ne patarimas; tą darbą reikia sustabdyti, kol problemos bus ištaisytos.","1":"Papildomos asmeninės apsaugos priemonės (PPE) pranešimo nepanaikina; tai padaro tik jame išvardytų problemų ištaisymas.","2":"Pranešimas sustabdo patį darbą, todėl niekas negali jo toliau dirbti."}},"working-environment-b1-05":{"question":"Jus išmokė naudoti pjūklą (cut-off saw) tam tikru būdu. Bendradarbis parodo greitesnį būdą, kuris skiriasi nuo to, ko jus mokė. Ką turėtumėte daryti?","options":["Toliau naudoti pjūklą taip, kaip jus mokė ir kaip jums liepė","Naudoti greitesnį būdą, nes jis taupo laiką","Naudoti greitesnį būdą tik tada, kai darbų vadovo nėra"],"explanation":"Įstatymas sako, kad mašinas ir įrangą turite naudoti taip, kaip jus mokė ir kaip jums nurodė darbdavys. Bendradarbio „greitesnis būdas“ gali praleisti saugos žingsnį. Jei manote, kad yra geresnis būdas, pirmiausia paklauskite darbų vadovo (supervisor).","why_not":{"1":"Įstatymas sako naudoti įrangą taip, kaip jus mokė, net jei kitas būdas greitesnis.","2":"Mokymų turite laikytis visada, ne tik tada, kai darbų vadovas (supervisor) mato."}},"working-environment-b1-06":{"question":"Praėjusį mėnesį gavote instruktažą (induction) kitoje tos pačios įmonės statybvietėje. Šiandien pradedate dirbti naujoje statybvietėje. Ar jums čia reikia instruktažo?","options":["Ne, vienas instruktažas galioja visose tos įmonės statybvietėse","Taip, nes instruktažas turi būti apie šią statybvietę ir jos pavojus","Tik jei dirbsite aukštyje"],"explanation":"Kiekviena statybvietė turi savo pavojus, išdėstymą ir tvarką, pvz., kur yra pirmoji pagalba ir kaip pranešti apie nelaimingą atsitikimą. Todėl kiekvienam darbuotojui reikia instruktažo (induction) apie statybvietę, kurioje jis dirba, net jei jis jau gavo instruktažą kitur.","why_not":{"0":"Kiekviena statybvietė turi savo pavojus, todėl instruktažas (induction) turi būti apie šią statybvietę.","2":"Kiekvienam darbuotojui reikia statybvietės instruktažo (induction), kad ir kokį darbą jis ten dirbs."}},"working-environment-b1-09":{"question":"Nuo pastolių nukrenta kibiras varžtų ir atsitrenkia į žemę metro atstumu nuo jūsų. Niekas nenukentėjo. Kas tai yra ir ką turėtumėte daryti?","options":["Tai nieko, nes niekas nenukentėjo","Tai beveik įvykęs nelaimingas atsitikimas (near miss): praneškite apie jį, kad būtų rasta ir pašalinta priežastis","Tai beveik įvykęs nelaimingas atsitikimas, bet apie jį pranešate tik tada, jei tai pasikartoja","Tai nelaimingas atsitikimas, todėl turite patys skambinti į HSE (darbo saugos tarnybą)"],"explanation":"Beveik įvykęs nelaimingas atsitikimas (near miss) – tai įvykis, kai niekas nenukentėjo, bet kas nors galėjo nukentėti. Kitą kartą kibiras gali kam nors pataikyti. Kai apie tai pranešate, statybvietėje galima išsiaiškinti, kodėl jis nukrito, ir neleisti tam pasikartoti. Tai, kad niekas nenukentėjo, buvo tik sėkmė.","why_not":{"0":"Tai, kad niekas nenukentėjo, buvo sėkmė; kitą kartą kas nors gali nukentėti, todėl praneškite.","2":"Apie beveik įvykusį nelaimingą atsitikimą (near miss) praneškite pirmą kartą, kad priežastis būtų pašalinta, kol niekas nenukentėjo.","3":"Niekas nenukentėjo, todėl tai beveik įvykęs nelaimingas atsitikimas (near miss), o ne nelaimingas atsitikimas; praneškite apie jį statybvietėje, kad priežastis būtų pašalinta."}},"working-environment-b1-10":{"question":"Darbuotojas paslysta ant purvo ir pasitempia kulkšnį. Jis negali dirbti įprasto darbo 5 dienas iš eilės, o tada grįžta į įprastą darbą. Ką turi padaryti jo darbdavys?","options":["Pranešti HSE (darbo saugos tarnybai) pagal pranešimo apie traumas taisykles (RIDDOR)","Visai nieko, nes jis nedirbo mažiau nei 7 dienas","Užregistruoti tai, pvz., nelaimingų atsitikimų žurnale (accident book), bet nepranešti HSE","Pranešti HSE tik tada, jei jis prašys kompensacijos"],"explanation":"Jei darbuotojas negali dirbti įprasto darbo daugiau nei 3 dienas iš eilės, nelaimingą atsitikimą reikia užrašyti, pvz., nelaimingų atsitikimų žurnale (accident book). Pranešti HSE (darbo saugos tarnybai) pagal RIDDOR reikia tik tada, jei tai trunka daugiau nei 7 dienas iš eilės. Penkios dienos yra daugiau nei 3, bet ne daugiau nei 7.","why_not":{"0":"Penkios dienos nėra daugiau nei 7, todėl HSE (darbo saugos tarnybai) pranešti nereikia.","1":"Penkios dienos yra daugiau nei 3, todėl įvykį vis tiek reikia užregistruoti.","3":"Kompensacija su tuo nesusijusi; kas daroma, priklauso nuo to, kiek laiko žmogus negali dirbti."}},"working-environment-b1-13":{"question":"Sugriūva didelė 9 metrų aukščio pastolių dalis. Laimei, niekas nenukentėjo. Ar apie tai reikia pranešti pagal pranešimo apie traumas taisykles (RIDDOR)?","options":["Ne, nes niekas nenukentėjo","Taip, tai „pavojingas įvykis“ (dangerous occurrence), apie kurį reikia pranešti","Ne, tai reikia tik įrašyti į nelaimingų atsitikimų žurnalą","Tik jei tai matė pašaliniai žmonės"],"explanation":"Apie kai kuriuos įvykius reikia pranešti net tada, kai niekas nenukentėjo, nes jie lengvai galėjo ką nors nužudyti. Jie vadinami pavojingais įvykiais (dangerous occurrences). Vienas iš jų – didelės dalies bet kokių aukštesnių nei 5 metrai pastolių sugriuvimas.","why_not":{"0":"Tai pavojingas įvykis (dangerous occurrence), apie kurį reikia pranešti net tada, kai niekas nenukentėjo.","2":"Apie didelės dalies aukštesnių nei 5 metrai pastolių sugriuvimą reikia pranešti institucijoms, o ne tik užrašyti.","3":"Apie tai reikia pranešti, kad ir kas tai matė, nes tai lengvai galėjo ką nors nužudyti."}},"working-environment-b1-15":{"question":"Jūsų brigada nori per naktį laikyti tinko maišus ir nedidelę maišyklę valgyklos vagonėlyje. Ar galima?","options":["Taip, jei jie tvarkingai sukrauti kampe","Taip, jei vagonėlis užrakintas","Ne, poilsio ir valgymo vietų negalima naudoti technikai, įrangai ar medžiagoms laikyti"],"explanation":"Valgykla – vieta, kur žmonės ilsisi ir valgo. Ji turi būti švari ir tvarkinga, ir HSE (darbo saugos tarnyba) sako, kad jos negalima naudoti kaip sandėlio technikai (plant), įrangai ar medžiagoms. Tinko dulkės prie maisto taip pat kenkia sveikatai. Vietoj to raskite tinkamą sandėlį.","why_not":{"0":"Poilsio vietų negalima naudoti technikai (plant), įrangai ar medžiagoms laikyti, kad ir kaip tvarkingai jos sukrautos.","1":"Užrakintas vagonėlis nepadeda; poilsio vietų negalima naudoti kaip sandėlio."}},"working-environment-b1-20":{"question":"Statybvietėje pavojaus signalui apie gaisrą naudojamas oro signalas (air horn). Kas turi būti teisinga apie šį signalą?","options":["Jis turi būti girdimas tik statybvietės biure","Jis gali skambėti taip pat kaip arbatos pertraukos signalas","Visi turi galėti jį girdėti per kitą triukšmą ir žinoti, ką jis reiškia"],"explanation":"Gaisro signalas naudingas tik tada, jei jį gauna visi. HSE (darbo saugos tarnyba) sako, kad tai turi būti išsiskiriantis garsas, girdimas per statybvietės triukšmą, ir visi turi žinoti, kad jis reiškia gaisrą. Jei jis skamba kaip arbatos pertraukos signalas, žmonės gali neišeiti.","why_not":{"0":"Įspėjimą turi girdėti visi statybvietėje, ne tik biure esantys žmonės.","1":"Įspėjimas turi išsiskirti, kad žmonės žinotų, jog jis reiškia gaisrą, ir išeitų."}},"working-environment-b1-22":{"question":"Anglijoje statybvietės kuro talpoje telpa 1 000 litrų. Kiek mažiausiai turi talpinti jos apsauginis pylimas (bund – išorinė sienelė ar padėklas, sulaikantis nuotėkius)?","options":["250 litrų","500 litrų","1 000 litrų","1 100 litrų"],"explanation":"Anglijos įstatymas sako, kad apsauginis pylimas (bund) aplink naftos produktų talpą turi talpinti bent 110% talpos tūrio. 1 000 litrų talpai tai yra 1 100 litrų. Papildomi 10% – atsarga, kad pylimas sulaikytų viską, jei talpa pratekėtų.","why_not":{"0":"Per mažai; apsauginis pylimas (bund) turi talpinti bent 110% talpos tūrio, tai yra 1 100 litrų.","1":"Per mažai; apsauginis pylimas (bund) turi talpinti bent 110% talpos tūrio, tai yra 1 100 litrų.","2":"Ne visai pakankamai; įstatymas reikalauja 110%, tai yra 10% daugiau, nei telpa talpoje."}},"working-environment-b2-01":{"question":"HSE (darbo saugos tarnybos) inspektorius jūsų įmonei įteikia nurodymą ištaisyti pažeidimus (improvement notice). Ką tai reiškia?","options":["Darbas turi būti nedelsiant sustabdytas ir negali būti vėl pradėtas","Įmonė dirbo gerai, ir ją giria už saugą","Inspektorius mano, kad pažeidžiamas saugos įstatymas, ir įmonė turi tai ištaisyti per pranešime nurodytą laiką","Tai tik patarimas, todėl įmonė gali nuspręsti į jį nekreipti dėmesio"],"explanation":"Nurodymas ištaisyti pažeidimus (improvement notice) reiškia, kad inspektorius mano, jog pažeidžiamas saugos įstatymas. Jame parašyta, koks įstatymas, paaiškinta kodėl, ir nurodytas laikas, per kurį įmonė turi viską ištaisyti. Pranešimas, kuris iš karto sustabdo darbą, yra kitos rūšies. Nurodymas ištaisyti pažeidimus nėra pagyrimas, ir jis nėra pasirinktinis – jį vykdyti privaloma.","why_not":{"0":"Tai kitos rūšies pranešimas; nurodymas ištaisyti pažeidimus (improvement notice) nustato laiką viskam ištaisyti.","1":"Tai ne pagyrimas; tai reiškia, kad inspektorius mano, jog pažeidžiamas saugos įstatymas.","3":"Tai ne patarimas; įmonė turi viską ištaisyti per nurodytą laiką."}},"working-environment-b2-02":{"question":"HSE (darbo saugos tarnybos) inspektorius darbo dienos viduryje atvyksta prie statybvietės vartų. Niekas nežinojo, kad jis atvyks. Ar inspektorius gali įeiti į statybvietę?","options":["Taip. Inspektoriai gali įeiti bet kuriuo pagrįstu laiku, o jei mano, kad gali būti pavojus, – bet kada","Ne. Inspektoriai turi užsiregistruoti vizitui bent prieš savaitę","Tik jei užsakovas pasirašo formą, leidžiančią jį įleisti","Tik jei kartu atvyksta policijos pareigūnas"],"explanation":"Įstatymas leidžia inspektoriui įeiti į darbo vietą bet kuriuo pagrįstu laiku, kad atliktų savo darbą. Jei jis mano, kad kas nors yra ar gali būti pavojinga, jis gali įeiti bet kada. Jam nereikia iš anksto užsiregistruoti, gauti užsakovo leidimo ar atsivesti policijos.","why_not":{"1":"Įstatymas leidžia inspektoriui įeiti bet kuriuo pagrįstu laiku, iš anksto neužsiregistravus.","2":"Inspektoriaus teisė įeiti kyla iš įstatymo, o ne iš užsakovo leidimo.","3":"Įstatymas leidžia inspektoriui įeiti bet kuriuo pagrįstu laiku be policijos."}},"working-environment-b2-03":{"question":"Po nelaimingo atsitikimo HSE (darbo saugos tarnybos) inspektorius liepia jums palikti sulūžusį ožį (trestle) ten, kur jis nukrito. Vėliau kažkas sako, kad tą vietą reikia sutvarkyti. Ką turėtumėte daryti?","options":["Jį patraukti, kad statybvietė atrodytų saugi","Išmesti ožį į konteinerį, kad niekas kitas juo nesinaudotų","Nunešti jį į sandėlį, bet prieš tai nufotografuoti","Palikti jį ten, kur yra. Inspektorius gali įsakyti nieko neliesti, kol tiria, kas atsitiko"],"explanation":"Inspektorius gali liepti nieko neliesti toje vietoje ar joje esančių daiktų tiek laiko, kiek jam reikia ištirti, kas atsitiko. Patraukus ar išmetus ožį (trestle), galima sunaikinti įrodymus. Jei kas nors nori jį patraukti, pirmiausia turi pasikalbėti su inspektoriumi.","why_not":{"0":"Inspektorius gali įsakyti nieko neliesti, todėl tvarkant galima sunaikinti įrodymus.","1":"Išmetus ožį (trestle), sunaikinami įrodymai, kuriuos inspektorius įsakė palikti neliestus.","2":"Nuotraukos neužtenka; inspektorius įsakė jį palikti tiksliai ten, kur jis yra."}},"working-environment-b2-04":{"question":"Ką, pagal įstatymą, jūsų darbdavys turi daryti su HSE (darbo saugos tarnybos) plakatu „Health and safety law“ (darbuotojų sveikatos ir saugos įstatymas)?","options":["Laikyti jį užrakintą biure, jei inspektorius paprašytų jį parodyti","Pakabinti jį ten, kur darbuotojai gali lengvai jį matyti ir perskaityti, arba duoti kiekvienam darbuotojui atitinkamą lankstinuką","Rodyti jį tik darbų vadovams ir vadovybei","Nieko. Tai tik pasiūlymas"],"explanation":"Darbdavys turi arba pakabinti patvirtintą plakatą, geros būklės, ten, kur darbe galite lengvai prie jo prieiti ir jį perskaityti, arba duoti jums patvirtintą lankstinuką. Užrakinti jį ar rodyti tik vadovybei – įstatymo neatitinka.","why_not":{"0":"Plakatas turi būti pakabintas ten, kur darbuotojai gali lengvai jį matyti ir perskaityti.","2":"Kiekvienas darbuotojas turi galėti matyti plakatą arba gauti lankstinuką.","3":"Tai įstatymas, o ne pasiūlymas: pakabinkite plakatą arba duokite kiekvienam darbuotojui lankstinuką."}},"working-environment-b2-06":{"question":"Darbe susižeidėte ranką ir negalite rašyti. Kaip nelaimingas atsitikimas vis tiek gali būti įrašytas į nelaimingų atsitikimų žurnalą (accident book)?","options":["Negali. Turite palaukti, kol galėsite įrašyti patys","Rašyti nelaimingų atsitikimų žurnale gali tik HSE inspektorius","Kas nors kitas gali įrašyti duomenis už jus, kuo greičiau","Į žurnalą įrašoma tik tada, jei patenkate į ligoninę"],"explanation":"Nelaimingo atsitikimo duomenis į nelaimingų atsitikimų žurnalą (accident book) gali įrašyti nukentėjęs darbuotojas arba kas nors kitas jo vardu. Tai reikia padaryti kuo greičiau po nelaimingo atsitikimo, kai tik pagrįstai įmanoma. Nereikia laukti, kol galėsite rašyti, ir tai skirta ne tik atvejams, kai patenkama į ligoninę.","why_not":{"0":"Laukti nereikia; kas nors kitas gali įrašyti duomenis už jus.","1":"Įrašą daro nukentėjęs darbuotojas arba kas nors kitas jo vardu, o ne HSE (darbo saugos tarnybos) inspektorius.","3":"Nelaimingi atsitikimai įrašomi į žurnalą, nesvarbu, ar patenkate į ligoninę."}},"working-environment-b2-07":{"question":"Darbų vadovas (supervisor) tiria beveik įvykusį nelaimingą atsitikimą (near miss), kuriame dalyvavote. Koks pagrindinis tyrimo tikslas?","options":["Rasti, ką apkaltinti ir nubausti","Išsiaiškinti, kas turi sumokėti už žalą","Užpildyti formą, kuri paskui padedama į archyvą","Suprasti, kodėl tai atsitiko, ir neleisti tam pasikartoti"],"explanation":"HSE (darbo saugos tarnyba) sako, kad nelaimingo atsitikimo ar beveik įvykusio nelaimingo atsitikimo (near miss) tyrimo tikslas – pasimokyti ir imtis veiksmų, kad tai nepasikartotų. Kai ieškoma kaltųjų, žmonės mažiau nori pasakyti, kas iš tikrųjų atsitiko.","why_not":{"0":"HSE (darbo saugos tarnyba) sako, kad tikslas – pasimokyti, o ieškant kaltųjų žmonės nenori pasakyti, kas atsitiko.","1":"HSE (darbo saugos tarnyba) sako, kad tikslas – pasimokyti ir neleisti tam pasikartoti, o ne išsiaiškinti, kas moka.","2":"Forma archyve nieko nekeičia; tikslas – imtis veiksmų, kad tai nepasikartotų."}},"working-environment-b2-08":{"question":"Darbuotojas darbe susižeidžia nugarą ir 10 dienų iš eilės negali dirbti savo įprasto darbo. Darbdavys turi apie tai pranešti pagal pranešimo apie traumas taisykles (RIDDOR). Iki kada?","options":["Per 15 dienų nuo nelaimingo atsitikimo","Per 24 valandas","Per 6 mėnesius","Tik kai jis grįš į darbą"],"explanation":"Kai darbuotojas dėl nelaimingo atsitikimo darbe daugiau nei 7 dienas iš eilės negali dirbti įprasto darbo, pranešimas turi pasiekti priežiūros instituciją per 15 dienų nuo nelaimingo atsitikimo. Pranešama internetu, užpildant formą. Laukti, kol darbuotojas grįš, gali būti per vėlu.","why_not":{"1":"Kai trauma trunka ilgiau nei 7 dienas, terminas – 15 dienų, o ne 24 valandos.","2":"Šeši mėnesiai – gerokai per vėlu; pranešimas turi pasiekti per 15 dienų.","3":"Terminas – 15 dienų nuo nelaimingo atsitikimo, nesvarbu, ar jis grįžo į darbą."}},"working-environment-b2-09":{"question":"Krintanti plyta pataiko darbuotojui į galvą. Jis kelias sekundes būna be sąmonės, tada atsistoja ir sako, kad jaučiasi gerai. Ar pagal pranešimo apie traumas taisykles (RIDDOR) tai yra nurodyta trauma (specified injury)?","options":["Ne, nes jis buvo be sąmonės tik kelias sekundes","Taip. Apie sąmonės netekimą dėl galvos traumos reikia pranešti, kad ir kiek jis truktų","Ne, nes jis sako, kad jaučiasi gerai","Tik jei jis paliekamas ligoninėje per naktį"],"explanation":"Pagal pranešimo apie traumas taisykles (RIDDOR) sąmonės netekimas dėl galvos traumos darbe yra nurodyta trauma (specified injury). Apie jį reikia pranešti, kad ir kaip trumpai žmogus buvo be sąmonės. Tai, kad paskui jis jaučiasi gerai, nieko nekeičia, ir gulėti ligoninėje nebūtina.","why_not":{"0":"Apie sąmonės netekimą dėl galvos traumos reikia pranešti, kad ir kiek trumpai jis truktų.","2":"Tai, kad paskui jis jaučiasi gerai, nieko nekeičia; apie sąmonės netekimą reikia pranešti.","3":"Gulėti ligoninėje nebūtina; užtenka sąmonės netekimo dėl galvos traumos."}},"working-environment-b2-11":{"question":"Savivartis sunkvežimis (tipper lorry) pakelia kėbulą ir paliečia neizoliuotą elektros liniją virš galvos (overhead power line), kurioje yra 11 000 voltų. Niekas nenukentėjo. Ar apie tai reikia pranešti pagal pranešimo apie traumas taisykles (RIDDOR)?","options":["Ne, nes niekas nenukentėjo","Tik jei netoliese esantys namai lieka be elektros","Tik jei sunkvežimis apgadintas","Taip. Kai technika paliečia neizoliuotą liniją virš galvos, kurioje daugiau nei 200 voltų, tai yra pavojingas įvykis (dangerous occurrence), ir apie jį reikia pranešti"],"explanation":"Kai technika (plant) ar įranga netyčia paliečia neizoliuotą elektros liniją virš galvos, kurioje daugiau nei 200 voltų, tai pagal pranešimo apie traumas taisykles (RIDDOR) yra pavojingas įvykis (dangerous occurrence). Apie jį reikia pranešti, net jei niekas nenukentėjo ir niekas neapgadinta.","why_not":{"0":"Tai pavojingas įvykis (dangerous occurrence), apie kurį reikia pranešti net tada, kai niekas nenukentėjo.","1":"Apie neizoliuotos linijos, kurioje daugiau nei 200 voltų, palietimą reikia pranešti, nesvarbu, ar dingsta elektra.","2":"Apie neizoliuotos linijos, kurioje daugiau nei 200 voltų, palietimą reikia pranešti, net jei niekas neapgadinta."}},"working-environment-b2-12":{"question":"Kada statybos projekte jau turi būti tualetai, prausyklos ir poilsio patalpos?","options":["Nuo projekto pradžios iki jo pabaigos","Kai pastatas jau turi stogą","Po pirmo mėnesio, kai atvyksta daugiau darbuotojų","Tik tada, kai jų paprašo inspektorius"],"explanation":"HSE (darbo saugos tarnyba) sako, kad rangovai turi užtikrinti buitines sąlygas (welfare) savo darbuotojams, kol jie yra statybvietėje, o generalinis rangovas (principal contractor) turi pasirūpinti, kad taip būtų nuo projekto pradžios iki pabaigos. Darbuotojams tualetų ir prausyklų reikia nuo pirmos dienos.","why_not":{"1":"Darbuotojams tualetų ir prausyklų reikia nuo pirmos dienos, o ne tik kai pastatas turi stogą.","2":"Buitinės sąlygos (welfare) turi būti užtikrintos nuo pat projekto pradžios, o ne po mėnesio.","3":"Buitinės sąlygos (welfare) – pareiga nuo pradžios iki pabaigos, nesvarbu, ar to prašo inspektorius."}},"working-environment-b2-13":{"question":"Mažoje statybvietėje yra vienas tualetas, kuriuo naudojasi ir vyrai, ir moterys. Kada tai leidžiama?","options":["Niekada. Vyrams ir moterims visada turi būti atskiri tualetų blokai","Tik jei statybvietėje dirba mažiau nei penkios moterys","Kai tualetas yra atskiroje patalpoje su durimis, kurias galima užrakinti iš vidaus","Tik jei vyrai ir moterys juo naudojasi skirtingu paros metu"],"explanation":"Įstatymas sako, kad vyrams ir moterims turi būti atskiros tualeto patalpos, nebent kiekvienas tualetas yra atskiroje patalpoje su durimis, kurios užsirakina iš vidaus. Tada vienu tualetu galima naudotis bendrai. Moterų skaičius ir paros metas nesvarbu.","why_not":{"0":"Vienu tualetu galima naudotis bendrai, jei jis atskiroje patalpoje, kuri užsirakina iš vidaus.","1":"Moterų skaičius nesvarbus; svarbu, kad tai būtų atskira patalpa, kurią galima užrakinti.","3":"Paros metas nesvarbus; svarbu, kad tai būtų atskira patalpa, kurią galima užrakinti."}},"working-environment-b2-14":{"question":"Visą rytą dirbote su šlapiu cementu. Kur turėtumėte nusiplauti rankas prieš pietus?","options":["Valgyklos kriauklėje, kur žmonės ruošia arbatą","Tinkamose prausyklose (washing facilities), atokiau nuo vietos, kur valgoma","Vandens kibire, kurį naudojote maišymui","Niekur. Užtenka nusišluostyti skuduru"],"explanation":"HSE (darbo saugos tarnyba) sako, kad rankos paprastai neturėtų būti plaunamos ten, kur žmonės valgo ir geria. Tai ypač svarbu, kai dirbate su tokiomis medžiagomis kaip cementas ar švinas, kad jos nepatektų į maistą. Naudokitės prausyklomis (washing facilities), kurios turi būti atskirtos nuo valgymo vietų.","why_not":{"0":"Plaunant cementą ten, kur žmonės ruošia arbatą, jis gali patekti į jų maistą ir gėrimus.","2":"Nešvarus maišymo vanduo nenuplauna cemento nuo rankų; naudokitės tinkamomis prausyklomis (washing facilities).","3":"Skuduras cemento nenuvalo; reikia tinkamų prausyklų (washing facilities)."}},"working-environment-b2-15":{"question":"Trumpam kelio remonto darbui nėra buitinio vagonėlio (welfare unit). Įmonė susitaria su netoliese esančia kavine, kad darbuotojai galės naudotis jos tualetais. Kas dar turi būti užtikrinta?","options":["Kavinės tualetai turi būti atviri visą laiką, kol darbuotojai yra darbo vietoje","HSE (darbo saugos tarnyba) turi pasirašyti susitarimą su kavine","Nieko daugiau. Tinka net jei kavinė užsidaro 2 val. po pietų, o darbas tęsiasi iki 5 val. vakaro","Kiekvienas darbuotojas pirmiausia turi ką nors nusipirkti kavinėje"],"explanation":"HSE (darbo saugos tarnyba) sako, kad įmonė gali naudotis tualetais kavinėje, viešaisiais tualetais ar kitame pastate, bet savininkas turi sutikti, o tualetai turi būti atviri visą laiką, kol darbuotojai yra darbo vietoje. Susitarimo nebūtina užrašyti, ir HSE jo nepasirašo.","why_not":{"1":"HSE (darbo saugos tarnyba) jo nepasirašo; susitariama su savininku, ir susitarimo nebūtina užrašyti.","2":"Tualetai turi būti atviri visą laiką, kol darbuotojai yra darbo vietoje, o ne tik iki 2 val. po pietų.","3":"HSE (darbo saugos tarnyba) sako, kad savininkas turi sutikti, jog tualetais būtų naudojamasi, o ne kad darbuotojai turi ką nors pirkti."}},"working-environment-b2-18":{"question":"Jums reikia vietos sukrauti gipso kartono plokštėms. Vienintelė laisva vieta – koridorius, pažymėtas kaip evakuacijos kelias gaisro atveju (fire escape route). Ką turėtumėte daryti?","options":["Sukrauti jas ten, bet palikti siaurą tarpą prasispraudimui","Sukrauti jas ten, bet tik šiandien","Sukrauti jas ten ir nuimti evakuacijos kelio ženklą","Nekrauti jų ten. Evakuacijos keliai turi būti laisvi, todėl paklauskite darbų vadovo (supervisor), kur jas dėti"],"explanation":"Įstatymas sako, kad avariniai keliai ir išėjimai, taip pat keliai, vedantys į juos, turi būti laisvi, kad jais būtų galima naudotis bet kada. Net trumpam laikui ar su siauru tarpu tai gali įkalinti žmones gaisro metu. Raskite kitą vietą plokštėms laikyti.","why_not":{"0":"Evakuacijos keliai turi būti laisvi, o pro siaurą tarpą žmonės gaisro metu gali neišeiti.","1":"Evakuacijos keliai turi būti laisvi, kad jais būtų galima naudotis bet kada, net šiandien.","2":"Nuėmus ženklą, bus dar blogiau; kelias turi likti laisvas ir pažymėtas."}},"working-environment-b2-19":{"question":"Jūsų prašo dujiniu degikliu nudeginti seną dažų sluoksnį. Niekada juo nesinaudojote, ir niekas jums nepasakė apie gaisro pavojų. Ką turėtumėte daryti?","options":["Pabandyti ir mokytis dirbant","Paprašyti bendradarbio jus prižiūrėti ir pradėti","Nepradėti, kol nebūsite tinkamai instruktuotas, kaip šį darbą atlikti saugiai","Atlikti jį greitai dienos pabaigoje, kai aplink mažiau žmonių"],"explanation":"Įstatymas sako, kad kai darbas kelia ypatingą gaisro pavojų, negalite jo dirbti, jei nebuvote tinkamai instruktuotas. Pasakykite darbų vadovui (supervisor), kad pirmiausia jums reikia instruktažo. Dirbant vėlai, kai aplink nieko nėra, didesnė tikimybė, kad gaisro niekas laiku nepastebės.","why_not":{"0":"Įstatymas sako, kad darbo, keliančio ypatingą gaisro pavojų, negalite dirbti, kol nebūsite instruktuotas.","1":"Bendradarbio priežiūra nėra instruktažas; pirmiausia turite būti tinkamai instruktuotas.","3":"Dirbant, kai aplink mažai žmonių, gaisro gali niekas nepastebėti."}},"working-environment-b2-20":{"question":"Trečiame aukšte montuojate putplasčio izoliacines plokštes. Atvežtas visas užsakymas. Ką HSE (darbo saugos tarnyba) pataria, kad gaisro pavojus būtų mažesnis?","options":["Užnešti visą užsakymą dabar, kad nereikėtų vaikščioti kelis kartus","Užnešti tik tiek, kiek dabar reikia, o likusias saugiai laikyti, kol jų prireiks","Sukrauti visas plokštes ant laiptų, kad būtų po ranka","Atsargines plokštes laikyti šalia vietos, kur vykdomi karštieji darbai (hot work)"],"explanation":"HSE (darbo saugos tarnyba) sako, kad laikant darbo vietoje kuo mažiau degių medžiagų, kol jų prireiks, gaisro pavojus sumažėja. Putplasčio plokštės dega. Sukrautos ant laiptų, jos dar gali užblokuoti išėjimą.","why_not":{"0":"HSE (darbo saugos tarnyba) sako laikyti darbo vietoje kuo mažiau degių medžiagų, kol jų prireiks.","2":"Plokštės ant laiptų didina gaisro pavojų ir gali užblokuoti išėjimą.","3":"Putplasčio plokštės dega, todėl laikant jas šalia karštųjų darbų (hot work) gaisras tampa labiau tikėtinas."}},"working-environment-b2-23":{"question":"Jūsų statybvietė yra šalia gyvenamųjų namų. Jums pasakyta, kad skaldymo plaktukus (breakers) galima naudoti tik nuo 8 val. ryto iki 6 val. vakaro. Kas turi teisę nustatyti tokias taisykles statybvietei?","options":["Niekas. Statybviečių triukšmui taisyklių nėra","Įmonė, kuri išnuomojo skaldymo plaktukus","Vietos savivaldybė (local council), kuri gali įteikti pranešimą, nustatantį darbo valandas, triukšmo lygį ir kokias mašinas galima naudoti","Bet kuris besiskundžiantis kaimynas"],"explanation":"Įstatymas leidžia vietos savivaldybei (local council) įteikti statybvietei pranešimą dėl triukšmo. Jame gali būti nurodyta, kokias mašinas galima ar negalima naudoti, kokiomis valandomis galima dirbti ir koks triukšmas leidžiamas. Pažeisti pranešimą be svarios priežasties yra nusikaltimas.","why_not":{"0":"Taisyklių yra: vietos savivaldybė (local council) gali įteikti pranešimą dėl statybvietės triukšmo.","1":"Nuomos įmonė tokios teisės neturi; ją turi vietos savivaldybė (local council).","3":"Kaimynas gali skųstis, bet pranešimą įteikti gali tik vietos savivaldybė (local council)."}},"working-environment-b3-01":{"question":"Jūsų darbdavys turi 12 darbuotojų ir atliko jūsų darbo rizikos vertinimą (risk assessment). Ką, pasak įstatymo, jis turi daryti su pagrindinėmis išvadomis?","options":["Jas užrašyti tik tada, jei paprašo inspektorius","Jas užrašyti","Išmesti vertinimą, kai tik prasideda darbas","Nieko, nes jas užrašyti privalo tik įmonės, turinčios 50 ar daugiau darbuotojų"],"explanation":"Darbdavys, turintis penkis ar daugiau darbuotojų, privalo užrašyti pagrindines rizikos vertinimo (risk assessment) išvadas (significant findings). Jis taip pat turi užrašyti bet kurią darbuotojų grupę, kuriai, jo nustatymu, kyla ypatinga rizika. Dvylika darbuotojų yra daugiau nei penki, todėl išvadas reikia užrašyti. Tai taikoma ne tik didelėms įmonėms, ir nereikia laukti, kol paprašys inspektorius.","why_not":{"0":"Kai darbuotojų penki ar daugiau, išvadas reikia užrašyti bet kokiu atveju, ne tik kai paprašoma.","2":"Pagrindines išvadas reikia užrašyti, o ne išmesti.","3":"Taisyklė taikoma nuo penkių darbuotojų, o ne nuo 50, todėl 12 darbuotojų užtenka."}},"working-environment-b3-03":{"question":"Dirbate tranšėjoje, kai jos sienelė pradeda trūkinėti ir byrėti. Iš karto išlipate ir neisite atgal, kol ji nebus sutvirtinta. Viršininkas sako, kad už darbo nutraukimą sumažins jums atlyginimą. Ką sako įstatymas?","options":["Esate apsaugoti: darbdavys negali su jumis blogai elgtis dėl to, kad pasitraukėte nuo pavojaus, kurį pagrįstai laikėte rimtu ir gresiančiu tuoj pat","Esate apsaugoti tik tada, jei kas nors iš tikrųjų nukentėjo","Turite grįžti, kai tik viršininkas liepia","Viršininkas gali sumažinti atlyginimą, nes sustojote nepaklausę"],"explanation":"Įstatymas saugo darbuotoją, kuris pasitraukia iš darbo vietos ar atsisako į ją grįžti dėl pavojaus, kurį pagrįstai laiko rimtu ir gresiančiu tuoj pat, ir kurio negalėjo pagrįstai sustabdyti. Darbdavys negali su jumis dėl to blogai elgtis, pavyzdžiui, sumažinti atlyginimo. Niekas neturi pirma nukentėti.","why_not":{"1":"Niekas neturi nukentėti; įstatymas jus saugo, kai pasitraukiate nuo rimto pavojaus.","2":"Galite atsisakyti grįžti, kol rimtas pavojus vis dar yra.","3":"Darbdavys negali su jumis blogai elgtis, pavyzdžiui, mažinti atlyginimo, dėl to, kad pasitraukėte nuo rimto pavojaus."}},"working-environment-b3-04":{"question":"16 metų jaunuolis netrukus pradės dirbti jūsų įmonėje kaip mokinys (trainee). Ką darbdavys privalo padaryti prieš jį priimdamas?","options":["Palaukti, kol jam beveik įvyks nelaimingas atsitikimas (near miss), ir tik tada atlikti vertinimą","Paprašyti tėvų raštu sutikti su rizika","Nieko papildomo, nes jauniems darbuotojams kyla tokia pati rizika kaip visiems","Atlikti arba peržiūrėti rizikos vertinimą (risk assessment), kuriame įvertinama rizika jauniems žmonėms, pavyzdžiui, dėl jų patirties stokos"],"explanation":"Įstatymas sako, kad darbdavys negali įdarbinti jauno žmogaus (jaunesnio nei 18 metų), kol neatliko ar neperžiūrėjo rizikos vertinimo (risk assessment), apimančio riziką jauniems žmonėms. Jis turi ypač atsižvelgti į jų nepatyrimą, menką rizikos suvokimą ir nebrandumą. Tėvai negali savo parašu panaikinti šios rizikos.","why_not":{"0":"Vertinimą reikia atlikti prieš jaunuoliui pradedant dirbti, o ne po beveik įvykusio nelaimingo atsitikimo (near miss).","1":"Tėvai negali savo parašu panaikinti rizikos; darbdavys turi įvertinti riziką jauniems žmonėms.","2":"Jauniems darbuotojams kyla papildoma rizika, pavyzdžiui, dėl patirties stokos, ir darbdavys turi ją įvertinti."}},"working-environment-b3-05":{"question":"Generalinis rangovas (principal contractor) planuoja pakeisti pėsčiųjų takus statybvietėje. Pakeitimas palies visus ten dirbančius. Ką įstatymas sako apie darbuotojus?","options":["Reikia klausti tik užsakovo","Darbuotojai neturi teisės pasisakyti apie sveikatą ir saugą statybvietėje","Generalinis rangovas turi laiku pasitarti su darbuotojais arba jų atstovais","Darbuotojams reikia pasakyti tik tada, kai pakeitimas jau padarytas"],"explanation":"Pagal Statybos projektavimo ir valdymo taisykles (CDM 2015) generalinis rangovas (principal contractor) turi laiku pasitarti su darbuotojais arba jų atstovais apie projekto klausimus, kurie gali paveikti jų sveikatą, saugą ar buitines sąlygas (welfare), nebent tai jau padarė jų pačių darbdavys. Pasakyti žmonėms po pakeitimo nėra pasitarimas su jais.","why_not":{"0":"Generalinis rangovas (principal contractor) turi pasitarti su darbuotojais, o ne tik su užsakovu.","1":"Įstatymas sako, kad dėl saugos statybvietėje reikia pasitarti su darbuotojais arba jų atstovais.","3":"Pasakyti žmonėms po pakeitimo nėra laiku su jais pasitarti."}},"working-environment-b3-06":{"question":"Projekte, kuriame yra generalinis rangovas (principal contractor) ir dar keli rangovai, kas, pasak įstatymo, turi pasirūpinti, kad būtų pravestas tinkamas statybvietės instruktažas (site induction)?","options":["Vietos savivaldybė","Kiekvienas darbuotojas turi juo pasirūpinti pats","Įmonė, kuri atveža medžiagas","Generalinis rangovas"],"explanation":"Statybos projektavimo ir valdymo taisyklės (CDM 2015) sako, kad generalinis rangovas (principal contractor) turi pasirūpinti, kad būtų pravestas tinkamas statybvietės instruktažas (site induction). Generalinis rangovas vadovauja statybos etapui, kai projekte dirba daugiau nei vienas rangovas. Darbuotojai neturi patys rūpintis savo instruktažu.","why_not":{"0":"Savivaldybė instruktažų neveda; generalinis rangovas (principal contractor) turi pasirūpinti, kad jis būtų pravestas.","1":"Darbuotojai patys savo instruktažu nesirūpina; generalinis rangovas (principal contractor) turi pasirūpinti, kad jis būtų pravestas.","2":"Medžiagas atvežanti įmonė statybvietei nevadovauja; jai vadovauja generalinis rangovas (principal contractor)."}},"working-environment-b3-08":{"question":"Jūsų įmonė remontuoja dalį prekybos centro, kuris dirbant lieka atidarytas. Parduotuvė turi savo saugos taisykles, be jūsų statybvietės taisyklių (site rules). Ką pataria HSE (darbo saugos tarnyba)?","options":["Laikytis tų taisyklių, kurių tuo metu lengviau laikytis","Aiškiai nustatyti, kur galioja statybvietės taisyklės, o kur – parduotuvės taisyklės, kad visi laikytųsi tinkamų","Leisti kiekvienam darbuotojui pačiam nuspręsti, kurių taisyklių laikytis","Nepaisyti parduotuvės taisyklių, nes galioja tik statybvietės taisyklės"],"explanation":"Kai užsakovo verslas dirbant tęsiasi, HSE (darbo saugos tarnyba) sako, kad reikia aiškiai nustatyti, kur galioja jūsų statybvietės taisyklės (site rules), o kur – paties užsakovo taisyklės. Visi turi žinoti ir laikytis tos vietos, kurioje yra, taisyklių.","why_not":{"0":"HSE (darbo saugos tarnyba) sako, kad visi turi žinoti ir laikytis tos vietos, kurioje yra, taisyklių.","2":"Darbuotojai patys nesirenka; HSE (darbo saugos tarnyba) sako aiškiai nustatyti, kurios taisyklės kur galioja.","3":"Parduotuvės zonose galioja parduotuvės taisyklės, todėl svarbūs abu taisyklių rinkiniai."}},"working-environment-b3-09":{"question":"Aprašote nelaimingą atsitikimą statybvietės nelaimingų atsitikimų žurnale (accident book). Ką, pasak įstatymo, darbdavys tada privalo daryti?","options":["Imtis pagrįstų veiksmų išsiaiškinti, kaip įvyko nelaimingas atsitikimas","Išplėšti lapą, kai grįšite į darbą","Palaukti, ar pateiksite ieškinį, ir tik tada ką nors daryti","Nieko, nes žurnalas yra tik įrašas"],"explanation":"Darbdavys privalo imtis pagrįstų veiksmų ištirti kiekvieną nelaimingą atsitikimą, apie kurį jam taip pranešta. Jei jis nustato ką nors kita, nei buvo užrašyta, turi užrašyti tai, ką nustatė. Nelaimingų atsitikimų žurnalas (accident book) nėra vieta, kur dalykai tiesiog padedami į stalčių.","why_not":{"1":"Išplėšus lapą, nelaimingas atsitikimas netiriamas, o darbdavys privalo jį ištirti.","2":"Darbdavys turi ištirti nelaimingą atsitikimą, nesvarbu, ar pateiksite ieškinį.","3":"Įstatymas sako, kad darbdavys turi imtis pagrįstų veiksmų jį ištirti."}},"working-environment-b3-10":{"question":"Jūsų darbdavys turi 40 darbuotojų, kurie paprastai dirba toje pačioje vietoje, ir ten laiko nelaimingų atsitikimų žurnalą (accident book). Kiek laiko reikia saugoti kiekvieną įrašą?","options":["6 mėnesius","Iki darbo pabaigos","Ne mažiau kaip 3 metus nuo įrašymo dienos","Kol nukentėjęs žmogus grįš į darbą"],"explanation":"Darbdaviai, kurių toje pačioje vietoje paprastai dirba 10 ar daugiau žmonių (ir kai kurie kiti, pavyzdžiui, gamyklos), privalo turėti nelaimingų atsitikimų žurnalą (accident book) arba jo elektroninę versiją lengvai pasiekiamoje vietoje. Kiekvienas įrašas turi būti saugomas ne mažiau kaip 3 metus nuo įrašymo dienos.","why_not":{"0":"Per trumpai; kiekvienas įrašas turi būti saugomas ne mažiau kaip 3 metus.","1":"Darbo pabaiga – per anksti; įrašai turi būti saugomi ne mažiau kaip 3 metus.","3":"Grįžimas į darbą šios pareigos nepanaikina; įrašai turi būti saugomi ne mažiau kaip 3 metus."}},"working-environment-b3-11":{"question":"Jūsų statybvietėje pagalbiniai darbininkai dažnai siunčiami vairuoti savivarčio (dumper), nors nė vienas iš jų nėra apmokytas juo naudotis. Kol kas niekas nenukentėjo ir nieko neatsitiko. Kaip tokią padėtį vadina HSE (darbo saugos tarnybos) nelaimingų atsitikimų tyrimo vadovas?","options":["Nepageidaujama aplinkybė (undesired circumstance): sąlygos, kurios gali sukelti traumą ar susirgimą","Beveik įvykęs nelaimingas atsitikimas (near miss)","Tai ne saugos klausimas, nes nieko neatsitiko","Nelaimingas atsitikimas"],"explanation":"HSE (darbo saugos tarnybos) vadovas tai vadina „nepageidaujama aplinkybe“ (undesired circumstance): tai sąlygos, kurios gali sukelti traumą ar susirgimą, pavyzdžiui, kai neapmokyti žmonės atlieka pavojingą darbą. Nelaimingas atsitikimas – kai kas nors nukenčia, o beveik įvykęs nelaimingas atsitikimas (near miss) – įvykis, per kurį kas nors galėjo nukentėti. Čia jokio įvykio dar nebuvo, bet pavojus tikras, ir jį reikia pašalinti.","why_not":{"1":"Beveik įvykęs nelaimingas atsitikimas (near miss) yra įvykis, per kurį vos nenukentėjo žmogus; čia jokio įvykio dar nebuvo.","2":"Neapmokyti žmonės, vairuojantys savivarčius, yra tikras pavojus, net kol dar niekas neatsitiko.","3":"Nelaimingas atsitikimas – kai kas nors nukenčia; čia niekas nenukentėjo."}},"working-environment-b3-13":{"question":"Darbuotojas darbe nukrito ir susilaužė koją. Pagal pranešimo apie traumas taisykles (RIDDOR) tai yra nurodyta trauma (specified injury). Kaip greitai atsakingas asmuo turi pranešti priežiūros institucijai (enforcing authority)?","options":["Tik kai jis nedirbs ilgiau nei 7 dienas","Nedelsiant, ir pranešimas turi būti gautas per 10 dienų","Per 1 mėnesį","Per 15 dienų"],"explanation":"Apie mirtis, nurodytas darbuotojų traumas (specified injuries), ne darbuotojų gydymą ligoninėje ir pavojingus įvykius (dangerous occurrences) reikia pranešti nedelsiant, paprasčiausiai internetu. Pranešimas turi būti gautas per 10 dienų. Apie mirtis ir nurodytas traumas galima pranešti ir telefonu. 15 dienų terminas taikomas traumoms, dėl kurių darbuotojas nedirba ilgiau nei 7 dienas.","why_not":{"0":"Lūžusi koja yra nurodyta trauma (specified injury), todėl apie ją reikia pranešti, nelaukiant, kiek laiko jis nedirbs.","2":"Per lėtai; pranešimas apie nurodytą traumą (specified injury) turi būti gautas per 10 dienų.","3":"Penkiolika dienų taikoma traumoms, dėl kurių nedirbama ilgiau nei 7 dienas; pranešimas apie nurodytas traumas turi būti gautas per 10 dienų."}},"working-environment-b3-14":{"question":"Darbuotojas per nelaimingą atsitikimą darbe patyrė nurodytą traumą (specified injury), ir apie ją buvo pranešta. Po aštuonių mėnesių jis miršta, ir trauma buvo viena iš jo mirties priežasčių. Ką privalo padaryti jo darbdavys?","options":["Nieko daugiau, nes apie traumą jau pranešta","Tik pasakyti jo šeimai","Nieko, nes mirtys skaičiuojamos tik per 30 dienų nuo nelaimingo atsitikimo","Nedelsiant pranešti apie mirtį priežiūros institucijai (enforcing authority)"],"explanation":"Jei trauma, apie kurią reikia pranešti, yra viena iš darbuotojo mirties priežasčių ir jis miršta per vienus metus nuo nelaimingo atsitikimo, darbdavys privalo nedelsiant pranešti apie mirtį priežiūros institucijai (enforcing authority). Tai taikoma net jei apie traumą buvo pranešta anksčiau.","why_not":{"0":"Apie mirtį per metus, kurią sukėlė trauma, reikia pranešti, net jei apie traumą jau buvo pranešta.","1":"Pasakyti šeimai neužtenka; priežiūros institucijai (enforcing authority) reikia pranešti nedelsiant.","2":"Terminas – vieni metai nuo nelaimingo atsitikimo, o ne 30 dienų."}},"working-environment-b3-15":{"question":"Dėl uždaryto kelio supykęs vairuotojas smogia čia dirbančiam eismo reguliuotojui (traffic marshal) ir sulaužo jam žandikaulį. Ar tai gali būti laikoma nelaimingu atsitikimu pagal pranešimo apie traumas taisykles (RIDDOR)?","options":["Tik jei reguliuotojas smogė atgal","Ne, nes vairuotojas nebuvo darbuotojas","Ne, nes smurto sukeltos traumos niekada nesiskaito","Taip. Smurtas prieš dirbančius žmones, su kuriuo jie nesutiko, pagal RIDDOR laikomas nelaimingu atsitikimu"],"explanation":"Pagal RIDDOR nelaimingas atsitikimas yra atskiras, neplanuotas įvykis, sukeliantis fizinę traumą. HSE (darbo saugos tarnyba) sako, kad tai apima ir smurtą prieš dirbančius žmones, su kuriuo jie nesutiko. Todėl užpuolimas prieš darbuotoją gali būti nelaimingas atsitikimas, apie kurį reikia pranešti, net jei užpuolikas yra pašalinis asmuo.","why_not":{"0":"Smogti atgal nebūtina; smurtas prieš darbuotoją, su kuriuo jis nesutiko, skaičiuojamas.","1":"Nesvarbu, kas užpuolikas; smurtas prieš darbuotoją skaičiuojamas.","2":"HSE (darbo saugos tarnyba) sako, kad smurtas prieš dirbančius žmones, su kuriuo jie nesutiko, skaičiuojamas."}},"working-environment-b3-16":{"question":"Tinkuotojo nugara per daugelį mėnesių, kilnojant plokštes, pamažu blogėjo. Nebuvo vieno įvykio, kuris ją sužeistų. Ar tai „nelaimingas atsitikimas“ pagal pranešimo apie traumas taisykles (RIDDOR)?","options":["Taip, kai tik jis pajunta aštrų skausmą","Ne. Žala, kuri kaupiasi pamažu, pavyzdžiui, dėl pasikartojančio kėlimo, pagal RIDDOR nelaikoma nelaimingu atsitikimu","Taip, nes prie to prisidėjo darbas","Taip, bet koks darbe jaučiamas skausmas laikomas nelaimingu atsitikimu"],"explanation":"Pagal RIDDOR turi būti atskiras įvykis, kurį galima aiškiai nurodyti, pavyzdžiui, kai kas nors užkrenta ant žmogaus. Žala, kuri pamažu kaupiasi dėl pasikartojančio kėlimo, pagal RIDDOR nelaikoma „nelaimingu atsitikimu“, ir vien aštraus skausmo pajutimas taip pat nėra nelaimingas atsitikimas. Tinkuotojas vis tiek turėtų pasakyti darbų vadovui (supervisor), kad darbą būtų galima padaryti saugesnį.","why_not":{"0":"Aštraus skausmo pajutimas yra trauma, o ne nelaimingas atsitikimas; turi būti atskiras įvykis.","2":"Neužtenka, kad prie to prisidėjo darbas; pamažu besikaupianti žala nėra nelaimingas atsitikimas.","3":"Vien skausmas nėra nelaimingas atsitikimas; turi būti atskiras įvykis, kuris jį sukėlė."}},"working-environment-b3-17":{"question":"Darbuotojo ilgi plaukai įsivelia į besisukantį grąžtą, ir nuo galvos nuplėšiama dalis odos. Jam reikia gydymo ligoninėje. Ar tai nurodyta trauma (specified injury) pagal pranešimo apie traumas taisykles (RIDDOR)?","options":["Tik jei jis nedirbs ilgiau nei 7 dienas","Ne, nes galvos žaizdos niekada nesiskaito","Taip. Bet kokio dydžio galvos odos nuplėšimas, kuriam reikia gydymo ligoninėje, yra nurodyta trauma","Tik jei jis buvo netekęs sąmonės"],"explanation":"Galvos odos nuplėšimas (scalping) reiškia, kad per nelaimingą atsitikimą nuo galvos nuplėšiama ar nulupama oda, pavyzdžiui, kai plaukai įsivelia į mašiną. Bet kokio dydžio galvos odos nuplėšimas, kuriam reikia gydymo ligoninėje, yra nurodyta trauma (specified injury), ir apie jį reikia pranešti. Tai nepriklauso nuo to, kiek laiko žmogus nedirba.","why_not":{"0":"Apie galvos odos nuplėšimą (scalping), kuriam reikia gydymo ligoninėje, reikia pranešti, kad ir kiek laiko žmogus nedirbtų.","1":"Galvos odos nuplėšimas (scalping) yra galvos žaizda, kuri yra nurodytų traumų (specified injuries) sąraše.","3":"Galvos odos nuplėšimas (scalping), kuriam reikia gydymo ligoninėje, skaičiuojamas savaime, be sąmonės netekimo."}},"working-environment-b3-18":{"question":"Darbuotojas, valantis karštos uždaros talpos vidų, nualpsta nuo perkaitimo (heat illness). Ar tai nurodyta trauma (specified injury) pagal pranešimo apie traumas taisykles (RIDDOR)?","options":["Taip. Trauma dirbant uždaroje erdvėje, dėl kurios žmogus perkaista, yra nurodyta trauma","Ne, perkaitimas nėra trauma","Tik jei jis savaitę išbus ligoninėje","Tik jei jis mirs"],"explanation":"Trauma dirbant uždaroje erdvėje yra nurodyta trauma (specified injury), jei dėl jos žmogus peršąla (hypothermia) ar perkaista (heat illness), jį reikia gaivinti arba jis paguldomas į ligoninę ilgiau nei 24 valandoms. Nualpimas nuo perkaitimo talpos viduje atitinka pirmąjį iš šių atvejų.","why_not":{"1":"Perkaitimas (heat illness) dirbant uždaroje erdvėje yra nurodytų traumų (specified injuries) sąraše.","2":"Užtenka vien perkaitimo (heat illness); ilgai gulėti ligoninėje nebūtina.","3":"Užtenka vien perkaitimo (heat illness); kad tai būtų skaičiuojama, jam nebūtina mirti."}},"working-environment-b3-19":{"question":"Griaunant pastatą, vikšrinis kranas (crawler crane), kuriuo verčiama siena, apvirsta. Niekas nenukentėjo. Ar apie tai reikia pranešti pagal pranešimo apie traumas taisykles (RIDDOR)?","options":["Taip. Apie apvirtusį kraną reikia pranešti, kad ir kokį darbą jis dirbo, taip pat ir griovimą","Ne, nes tuo metu jis nekėlė krovinio","Ne, nes niekas nenukentėjo","Tik jei kranas buvo išsinuomotas"],"explanation":"Kėlimo įrangos sugriuvimas ar apvirtimas pagal RIDDOR yra pavojingas įvykis (dangerous occurrence), net kai niekas nenukentėjo. HSE (darbo saugos tarnyba) sako, kad apie incidentus su kranais reikia pranešti, kad ir kokį darbą kranas dirbo, ne tik kėlimą, ir kaip pavyzdį nurodo griovimą.","why_not":{"1":"Apie incidentus su kranais reikia pranešti, kad ir kokį darbą kranas dirbo, ne tik keldamas.","2":"Krano apvirtimas yra pavojingas įvykis (dangerous occurrence), apie kurį pranešama net tada, kai niekas nenukentėjo.","3":"Nesvarbu, kam priklauso kranas; apie tai reikia pranešti."}},"working-environment-b3-21":{"question":"Statybvietėje naudojami kilnojamieji cheminiai tualetai. Ten dirba 14 žmonių po 40 valandų per savaitę. Pagal Britanijos standartą (British Standard), kurį cituoja HSE (darbo saugos tarnyba), kiek mažiausiai turėtų būti cheminių tualetų?","options":["7","4","2","1"],"explanation":"HSE (darbo saugos tarnyba) nurodo Britanijos standartą (British Standard), kuris rekomenduoja vieną cheminį tualetą kiekvieniems septyniems žmonėms, dirbantiems 40 valandų per savaitę. Keturiolika žmonių reiškia bent du. Priklausomai nuo to, kiek jais naudojamasi, gali reikėti daugiau tualetų arba juos dažniau ištuštinti.","why_not":{"0":"Septyni – tai žmonių skaičius vienam tualetui, o ne tualetų skaičius.","1":"Keturi – daugiau, nei reikalauja standartas; vienas tualetas septyniems žmonėms reiškia du.","3":"Vienas tualetas skirtas septyniems žmonėms; 14 žmonių reikia bent dviejų."}},"working-environment-b3-25":{"question":"Statybvietėje Anglijoje bendradarbis per pietus užsidega cigaretę valgyklos vagonėlyje. Vagonėlis turi stogą ir sienas, ir juo naudojasi visa jūsų brigada. Ar tai leidžiama?","options":["Taip, nes tai pertrauka, o ne darbo laikas","Taip, jei niekas nesiskundžia","Taip, jei jis surūko tik vieną","Ne. Uždara vieta, kurioje dirba daugiau nei vienas žmogus, pagal įstatymą visada yra nerūkymo zona"],"explanation":"Anglijoje uždaros ar beveik uždaros vietos, kuriose dirba daugiau nei vienas žmogus, visada yra nerūkymo zonos (smoke-free), net jei žmonės jomis naudojasi skirtingu metu. Statybvietės vagonėlis yra uždaras, ir juo naudojasi visa brigada, todėl rūkyti jame draudžia įstatymas.","why_not":{"0":"Vagonėlis yra nerūkymo zona (smoke-free) visą laiką, taip pat ir per pertraukas.","1":"Įstatymas jį paverčia nerūkymo zona (smoke-free), nesvarbu, ar kas nors skundžiasi.","2":"Net viena cigaretė uždaroje bendroje darbo vietoje pažeidžia įstatymą."}},"working-environment-b3-26":{"question":"Anglijoje jūsų įmonės furgonu darbui naudojatės jūs ir du bendradarbiai. Vienas iš jų nori jame rūkyti, kai vairuoja vienas. Ką sako įstatymas?","options":["Trumpose kelionėse galima","Furgone rūkyti draudžiama (smoke-free), nes tai uždara transporto priemonė, kuria darbui naudojasi daugiau nei vienas žmogus, net jei skirtingu metu","Galima, kai jis furgone vienas","Nerūkymo taisyklės taikomos tik autobusams ir taksi"],"explanation":"Uždaroje transporto priemonėje, kuria apmokamam ar savanoriškam darbui naudojasi daugiau nei vienas žmogus, pagal įstatymą rūkyti draudžiama (smoke-free). Tai taikoma net jei tie žmonės furgonu naudojasi skirtingu metu. Todėl jame rūkyti negalima, net kai jis vienas.","why_not":{"0":"Furgone rūkyti draudžiama (smoke-free) kiekvienos kelionės metu, trumpos ar ilgos.","2":"Rūkyti draudžiama (smoke-free) net tada, kai jis vienas, nes darbui furgonu naudojasi daugiau nei vienas žmogus.","3":"Taisyklės taikomos ir darbo transporto priemonėms, kuriomis naudojasi daugiau nei vienas žmogus, kaip šis furgonas."}},"working-environment-b3-27":{"question":"Užsidega kartono ir medienos atraižų krūva. Kokį gesintuvą HSE (darbo saugos tarnyba) nurodo medienos, popieriaus ir audinių gaisrams?","options":["Jokio; leisti išdegti","Anglies dioksido (CO2)","Vandens","Bet kokį, nes visi vienodai tinka visiems gaisrams"],"explanation":"HSE (darbo saugos tarnyba) medienos, popieriaus ir audinių gaisrams nurodo vandens gesintuvus. Elektros gaisrams ji nurodo anglies dioksido (CO2) gesintuvus, o degiems skysčiams – miltelinius ar putų gesintuvus. Gesintuvai nėra vienodi, todėl prieš naudodami patikrinkite etiketę.","why_not":{"0":"Paliktas degti gaisras gali išplisti; medienai, popieriui ir audiniams HSE (darbo saugos tarnyba) nurodo vandens gesintuvus.","1":"HSE (darbo saugos tarnyba) anglies dioksido (CO2) gesintuvus nurodo elektros gaisrams, o ne medienai, popieriui ir audiniams.","3":"Gesintuvai nėra vienodi; HSE (darbo saugos tarnyba) kiekvieną tipą priskiria tam tikros rūšies gaisrui."}},"working-environment-b3-31":{"question":"Kur, pasak HSE (darbo saugos tarnybos) priešgaisrinės saugos vadovo, statybvietėje turėtų būti leidžiama rūkyti?","options":["Šalia atliekų konteinerio (skip), kad pelenai iš karto kristų į jį","Pastato viduje, jei langai atidaryti","Bet kur lauke","Tik nustatytose rūkymo vietose toliau nuo pastatų ir to, kas gali degti"],"explanation":"HSE (darbo saugos tarnybos) vadovas sako, kad statybvietėje rūkyti neturėtų būti leidžiama niekur, išskyrus nustatytas rūkymo vietas toliau nuo pastatų ir degių medžiagų. Šiukšlių pilnas atliekų konteineris (skip) yra būtent tai, ką gali uždegti nuorūka.","why_not":{"0":"Atliekų konteineris (skip) pilnas to, kas dega, todėl rūkyti reikia toliau nuo jo.","1":"Rūkyti reikia toliau nuo pastatų, nesvarbu, ar langai atidaryti.","2":"Ne bet kur; tik nustatytose vietose toliau nuo pastatų ir to, kas gali degti."}},"working-environment-b3-35":{"question":"Registruotas atliekų vežėjas (registered waste carrier) išveža konteinerį mišrių (nepavojingų) statybinių atliekų. Statybvietė ir vežėjas abu pasirašo rašytinį atliekų aprašymą, dažnai vadinamą atliekų perdavimo važtaraščiu (waste transfer note). Kiek laiko kiekvienas iš jų turi jį saugoti?","options":["Kol konteineris bus ištuštintas","Ne mažiau kaip 2 metus","1 savaitę","Jo saugoti nereikia"],"explanation":"Ir atliekas perduodantis, ir jas priimantis asmuo turi saugoti rašytinį aprašymą (waste transfer note) ar jo kopiją ne mažiau kaip 2 metus. Paprašius, jie turi jį parodyti pareigūnui per 7 dienas.","why_not":{"0":"Per trumpai; abi pusės turi jį saugoti ne mažiau kaip 2 metus.","2":"Per trumpai; abi pusės turi jį saugoti ne mažiau kaip 2 metus.","3":"Jį reikia saugoti ne mažiau kaip 2 metus ir, paprašius, parodyti pareigūnui."}},"working-environment-b3-36":{"question":"Viršininkas liepia nuvažiuoti įmonės furgonu į nuošalų keliuką ir ten išversti krūvą senų gipso kartono plokščių. Ką sako įstatymas?","options":["Galima, nes taip liepė viršininkas","Galima, jei keliukas yra kaime","Galima, jei tai tik vienas furgonas","Negalima. Versti atliekas ant žemės be tai leidžiančio leidimo draudžia įstatymas"],"explanation":"Įstatymas sako, kad niekas negali versti atliekų ant žemės ar sąmoningai sukelti ar leisti jas ten išversti, nebent tai leidžia aplinkosaugos leidimas (environmental permit). Atliekų išvertimas keliuke yra neteisėtas atliekų išmetimas (fly-tipping). Tai, kad liepė viršininkas, nepadaro to teisėtu, todėl atsisakykite ir paaiškinkite kodėl.","why_not":{"0":"Tai, kad liepė viršininkas, nepadaro atliekų išvertimo teisėto.","1":"Versti atliekas ant bet kokios žemės be leidimo draudžia įstatymas, nesvarbu, ar tai kaime.","2":"Net vienas be leidimo išverstas krovinys pažeidžia įstatymą."}},"working-environment-b3-37":{"question":"Bendradarbis siūlo nudeginti plastikinę izoliaciją nuo laužo elektros kabelio, kad būtų galima parduoti varį. Ką sako įstatymas?","options":["Galima, jei tai daroma po darbo","Galima ant nedidelio laužo","Nudeginti izoliaciją nuo kabelio, kad būtų išgautas metalas, yra nusikaltimas","Galima, jei pinigai atiteks labdarai"],"explanation":"Švaraus oro įstatymas (Clean Air Act) nustato, kad nudeginti izoliaciją nuo kabelio metalui išgauti yra nusikaltimas (nebent tai specialiai leidžiamo proceso dalis). Deginant plastiką, išsiskiria kenksmingi dūmai. Kabelių laužą verčiau atiduokite tinkamu atliekų ar perdirbimo keliu.","why_not":{"0":"Nudeginti kabelio izoliaciją metalui išgauti yra nusikaltimas bet kuriuo metu.","1":"Laužo dydis nesvarbus; nudeginti kabelio izoliaciją metalui išgauti yra nusikaltimas.","3":"Nesvarbu, kur atiteks pinigai; tai vis tiek nusikaltimas."}}};
